    override fun onConfigure(db: SQLiteDatabase) {
        super.onConfigure(db)
        db.setForeignKeyConstraintsEnabled(true)
        db.enableWriteAheadLogging()
    }

    override fun onCreate(db: SQLiteDatabase) {
        db.beginTransaction()
        try {
            createAllTables(db)
            ensureProductReferenceData(db)
            ensureVehicleArchiveSchema(db)
            ensureVehicleTripLifecycleSchema(db)
            ensureDeliveriesSchema(db)
            ensureFuelSalesSchema(db)
            ensureLegacyAssetsSchema(db)
            ensureModule007Schema(db)
            ensureModule010Schema(db)
            ensureReportCacheTable(db)
            insertInitialData(db)
            ensureContractSchema(db)
            ensureActivityPermissions(db)
            ensureTaskPermissions(db)
            ensureMessagingPermissions(db)
            ensureSmsSettings(db)
            ensureFuelCommerceSchema(db)
            db.setTransactionSuccessful()
            Log.d(TAG, "Database V$VERSION created successfully")
        } finally {
            db.endTransaction()
        }
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        db.beginTransaction()
        try {
            for (v in oldVersion until newVersion) {
                when (v) {
                    5 -> migrateV5ToV6(db)
                    6 -> migrateV6ToV7(db)
                    7 -> migrateV7ToV8(db)
                    8 -> migrateV8ToV9(db)
                    9 -> migrateV9ToV10(db)
                    10 -> migrateV10ToV11(db)
                    11 -> migrateV11ToV12(db)
                    12 -> migrateV12ToV13(db)
                    13 -> migrateV13ToV14(db)
                    14 -> migrateV14ToV15(db)
                    15 -> migrateV15ToV16(db)
                    16 -> migrateV16ToV17(db)
                    17 -> migrateV17ToV18(db)
                    18 -> ensureReportCacheTable(db)
                    19 -> migrateV19ToV20(db)
                    20 -> migrateV20ToV21(db)
                    21 -> migrateV21ToV22(db)
                    22 -> createSmsCognitiveTables(db)
                    23 -> migrateV23ToV24(db)
                    24 -> migrateV24ToV25(db)
                    25 -> cleanupRetiredChannelArtifacts(db)
                    26 -> migrateV26ToV27(db)
                    27 -> migrateV27ToV28(db)
                    28 -> migrateV28ToV29(db)
                    29 -> migrateV29ToV30(db)
                    30 -> migrateV30ToV31(db)
                    31 -> migrateV31ToV32(db)
                    32 -> migrateV32ToV33(db)
                    33 -> ensureFuelCommerceSchema(db)
                }
            }
            ensureModule006Schema(db)
            ensureModule007Schema(db)
            ensureModule010Schema(db)
            ensureProductReferenceData(db)
            ensureDeliveriesSchema(db)
            ensureFuelSalesSchema(db)
            ensureLegacyAssetsSchema(db)
            ensureVehicleArchiveSchema(db)
            ensureVehicleTripLifecycleSchema(db)
            db.setTransactionSuccessful()
        } finally {
            db.endTransaction()
        }
    }

