    /**
     * يضيف دورة حياة صريحة لسجل الرحلة وخطاً زمنياً مدققاً. لا يستنتج الحالات
     * التاريخية من العدادات أو المسافة؛ السجلات القديمة تبدأ «مجدولة» فقط.
     */
    private fun ensureVehicleTripLifecycleSchema(db: SQLiteDatabase) {
        ensureColumn(db, "vehicle_trips", "trip_status", "TEXT NOT NULL DEFAULT 'scheduled' CHECK(trip_status IN ('scheduled', 'active', 'completed', 'cancelled'))")
        ensureColumn(db, "vehicle_trips", "scheduled_at", "DATETIME")
        ensureColumn(db, "vehicle_trips", "started_at", "DATETIME")
        ensureColumn(db, "vehicle_trips", "completed_at", "DATETIME")
        ensureColumn(db, "vehicle_trips", "cancelled_at", "DATETIME")
        ensureColumn(db, "vehicle_trips", "status_note", "TEXT")
        ensureColumn(db, "vehicle_trips", "updated_at", "DATETIME")
        db.execSQL("UPDATE vehicle_trips SET trip_status = 'scheduled' WHERE trip_status IS NULL OR trim(trip_status) = ''")
        db.execSQL("UPDATE vehicle_trips SET scheduled_at = COALESCE(scheduled_at, created_at) WHERE trip_status = 'scheduled'")
        db.execSQL("""
            CREATE TABLE IF NOT EXISTS vehicle_trip_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                uuid TEXT UNIQUE NOT NULL,
                trip_id INTEGER NOT NULL,
                event_type TEXT NOT NULL CHECK(event_type IN ('created', 'scheduled', 'started', 'completed', 'cancelled')),
                event_note TEXT,
                occurred_at DATETIME NOT NULL,
                created_by INTEGER,
                FOREIGN KEY (trip_id) REFERENCES vehicle_trips(id) ON DELETE CASCADE,
                FOREIGN KEY (created_by) REFERENCES users(id)
            )
        """.trimIndent())
        db.execSQL("CREATE INDEX IF NOT EXISTS idx_vehicle_trips_status_date ON vehicle_trips(trip_status, trip_date, vehicle_id)")
        db.execSQL("CREATE INDEX IF NOT EXISTS idx_vehicle_trip_events_trip_time ON vehicle_trip_events(trip_id, occurred_at, id)")
        db.execSQL("""
            INSERT OR IGNORE INTO vehicle_trip_events (uuid, trip_id, event_type, event_note, occurred_at)
            SELECT 'trip-created-' || t.id, t.id, 'created', 'تم ترحيل سجل الرحلة قبل إضافة دورة الحالة', COALESCE(t.created_at, t.trip_date || ' 00:00:00')
            FROM vehicle_trips t
            WHERE NOT EXISTS (SELECT 1 FROM vehicle_trip_events e WHERE e.trip_id = t.id AND e.event_type = 'created')
        """.trimIndent())
    }

