    private fun ensureMaintenanceScheduleStationScopeSchema(db: SQLiteDatabase) {
        // تُعزل السجلات القديمة fail-closed: لا تُسند لمحطة إلا عندما يكون منشئها
        // مرتبطاً فعلياً بمحطة صالحة. السجلات غير القابلة للإسناد تبقى عند 0 ولا تُقرأ تشغيلياً.
        ensureColumn(db, "maintenance_schedule", "station_id", "INTEGER NOT NULL DEFAULT 0")
        db.execSQL(
            """
            UPDATE maintenance_schedule
            SET station_id = COALESCE((
                SELECT u.station_id FROM users u
                WHERE u.id = maintenance_schedule.created_by
                  AND u.station_id IS NOT NULL AND u.station_id > 0
            ), 0)
            WHERE station_id IS NULL OR station_id = 0
            """.trimIndent()
        )
        db.execSQL("CREATE INDEX IF NOT EXISTS idx_maintenance_schedule_station_active ON maintenance_schedule(station_id, is_active, id)")
    }

