    /**
     * Adds soft-delete metadata to the fleet maintenance and insurance tables.
     * This helper is deliberately idempotent so it is safe for fresh databases,
     * partially upgraded databases, and installations upgraded from V29.
     */
    private fun ensureVehicleArchiveSchema(db: SQLiteDatabase) {
        val tables = listOf("vehicle_maintenance", "vehicle_insurance")
        tables.forEach { tableName ->
            ensureColumn(db, tableName, "is_deleted", "INTEGER NOT NULL DEFAULT 0")
            ensureColumn(db, tableName, "deleted_at", "DATETIME")
            ensureColumn(db, tableName, "deleted_by", "INTEGER")
            db.execSQL("UPDATE $tableName SET is_deleted = 0 WHERE is_deleted IS NULL")
            db.execSQL("CREATE INDEX IF NOT EXISTS idx_${tableName}_deleted ON $tableName(is_deleted, vehicle_id)")
        }
    }

