    fun getUserRecoveryContactByPhone(phone: String): JSONObject? {
        val digits = phone.filter { it.isDigit() }
        if (digits.isBlank()) return null
        val national = when {
            digits.startsWith("00967") -> digits.removePrefix("00967")
            digits.startsWith("967") -> digits.removePrefix("967")
            digits.startsWith("0") && digits.length == 10 -> digits.removePrefix("0")
            else -> digits
        }
        val variants = linkedSetOf(
            phone.trim(),
            digits,
            "967$national",
            "0$national",
            national
        ).filter { it.isNotBlank() }
        val placeholders = variants.joinToString(",") { "?" }
        dbLock.lock()
        return try {
            readableDatabase.rawQuery(
                "SELECT id, username, phone, status FROM users WHERE is_deleted = 0 AND phone IN ($placeholders) LIMIT 1",
                variants.toTypedArray()
            ).use { cursor ->
                if (!cursor.moveToFirst()) null else JSONObject().apply {
                    put("user_id", cursor.getLong(cursor.getColumnIndexOrThrow("id")))
                    put("username", cursor.getString(cursor.getColumnIndexOrThrow("username")))
                    put("phone", cursor.getString(cursor.getColumnIndexOrThrow("phone")))
                    put("status", cursor.getString(cursor.getColumnIndexOrThrow("status")))
                }
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun updateBiometricStatus(username: String, enabled: Boolean): Boolean {
        val cv = ContentValues().apply {
            put("biometric_enabled", if (enabled) 1 else 0)
        }
        val rows = writableDatabase.update("users", cv, "username=?", arrayOf(username))
        return rows > 0
    }

    fun getUserById(userId: Long): JSONObject? {

        val db = readableDatabase

        val cursor = db.rawQuery(
            """
            SELECT
                u.id,
                u.uuid,
                u.username,
                u.full_name,
                u.full_name_ar,
                u.display_name,
                u.role_id,
                r.role_code AS role,
                u.station_id,
                u.branch_id,
                u.company_id,
                u.preferred_language,
                u.theme,
                u.status
            FROM users u
            LEFT JOIN roles r ON r.id = u.role_id
            WHERE u.id = ?
            AND u.is_deleted = 0
            LIMIT 1
            """,
            arrayOf(userId.toString())
        )

        return cursor.use {

            if (it.moveToFirst()) {

                JSONObject().apply {

                    put("user_id", it.getLong(it.getColumnIndexOrThrow("id")))
                    put("uuid", it.getString(it.getColumnIndexOrThrow("uuid")))
                    put("username", it.getString(it.getColumnIndexOrThrow("username")))
                    put("full_name", it.getString(it.getColumnIndexOrThrow("full_name")))
                    put("full_name_ar", it.getString(it.getColumnIndexOrThrow("full_name_ar")))
                    put("display_name", it.getString(it.getColumnIndexOrThrow("display_name")))
                    put("role", it.getString(it.getColumnIndexOrThrow("role")))
                    put("role_id", it.getLong(it.getColumnIndexOrThrow("role_id")))
                    put("station_id", it.getLong(it.getColumnIndexOrThrow("station_id")))
                    put("branch_id", it.getLong(it.getColumnIndexOrThrow("branch_id")))
                    put("company_id", it.getLong(it.getColumnIndexOrThrow("company_id")))
                    put("language", it.getString(it.getColumnIndexOrThrow("preferred_language")))
                    put("theme", it.getString(it.getColumnIndexOrThrow("theme")))
                    put("status", it.getString(it.getColumnIndexOrThrow("status")))
                }

            } else {
                null
            }
        }
    }

    fun getShiftFormContext(currentUserId: Long): JSONObject {
        require(currentUserId > 0L) { "معرف المستخدم الحالي غير صالح" }

        dbLock.lock()
        return try {
            val db = readableDatabase
            val currentUser = getUserById(currentUserId)
                ?: throw IllegalStateException("المستخدم الحالي غير موجود في قاعدة البيانات")
            val stationId = currentUser.optLong("station_id", 0L)
            require(stationId > 0L) { "لا توجد محطة مرتبطة بالمستخدم الحالي" }

            val station = JSONObject()
            db.rawQuery(
                """
                SELECT id, station_code, station_name, station_name_ar
                FROM stations WHERE id = ? LIMIT 1
                """.trimIndent(),
                arrayOf(stationId.toString())
            ).use { cursor ->
                if (cursor.moveToFirst()) {
                    station.put("id", cursor.getLong(cursor.getColumnIndexOrThrow("id")))
                    station.put("station_code", cursor.getString(cursor.getColumnIndexOrThrow("station_code")))
                    station.put("station_name", cursor.getString(cursor.getColumnIndexOrThrow("station_name")))
                    station.put("station_name_ar", cursor.getString(cursor.getColumnIndexOrThrow("station_name_ar")))
                }
            }

            fun employeesByTitles(titles: List<String>, includeAllActive: Boolean = false): JSONArray {
                val titlePlaceholders = titles.joinToString(",") { "?" }
                val predicate = if (includeAllActive) "1=1" else """
                    (
                        UPPER(TRIM(COALESCE(e.job_title, ''))) IN ($titlePlaceholders)
                        OR TRIM(COALESCE(e.job_title_ar, '')) IN ($titlePlaceholders)
                    )
                """.trimIndent()
                val args: Array<String> = if (includeAllActive) {
                    arrayOf(stationId.toString())
                } else {
                    (titles.map { it.uppercase(Locale.US) } + titles + listOf(stationId.toString())).toTypedArray()
                }
                val sql = """
                    SELECT e.id, e.employee_code, e.full_name, e.full_name_ar,
                           e.job_title, e.job_title_ar, e.department, e.station_id,
                           e.user_id, e.status
                    FROM employees e
                    WHERE e.station_id = ?
                      AND e.is_deleted = 0
                      AND e.status = 'active'
                      AND $predicate
                    ORDER BY COALESCE(e.full_name_ar, e.full_name, e.employee_code)
                """.trimIndent()
                return db.rawQuery(sql, args).use { cursorToJsonArray(it) }
            }

            val managers = employeesByTitles(
                listOf("STATION_MANAGER", "SHIFT_SUPERVISOR", "DEPUTY_STATION_MANAGER", "OPERATIONS_ASSISTANT"),
                false
            )
            // دعم البيانات العربية الحالية، مع الرموز الإنجليزية القياسية أعلاه.
            val managerTitlesAr = listOf("مدير المحطة", "نائب مدير المحطة", "مشرف وردية", "مساعد مدير العمليات")
            val args = (listOf(stationId.toString()) + managerTitlesAr).toTypedArray()
            val managersAr = db.rawQuery(
                """
                    SELECT e.id, e.employee_code, e.full_name, e.full_name_ar, e.job_title, e.job_title_ar, e.department, e.station_id, e.user_id, e.status FROM employees e WHERE e.station_id =? AND e.is_deleted = 0 AND e.status ='active' AND (TRIM(COALESCE(e.job_title_ar,'')) IN (${managerTitlesAr.joinToString(",") { "?" }})) ORDER BY COALESCE(e.full_name_ar, e.full_name, e.employee_code)
                """.trimIndent(), args
            ).use { cursorToJsonArray(it) }                                    
            val allManagers = JSONArray()
            val seenManagers = HashSet<Long>()
            for (i in 0 until managers.length()) { val o = managers.optJSONObject(i); if (o != null && seenManagers.add(o.optLong("id"))) allManagers.put(o) }
            for (i in 0 until managersAr.length()) { val o = managersAr.optJSONObject(i); if (o != null && seenManagers.add(o.optLong("id"))) allManagers.put(o) }

            val cashiers = db.rawQuery(
                """
                SELECT e.id, e.employee_code, e.full_name, e.full_name_ar,
                       e.job_title, e.job_title_ar, e.department, e.station_id,
                       e.user_id, e.status
                FROM employees e
                WHERE e.station_id = ? AND e.is_deleted = 0 AND e.status = 'active'
                  AND (
                      UPPER(TRIM(COALESCE(e.job_title,''))) = 'CASHIER'
                      OR TRIM(COALESCE(e.job_title_ar,'')) IN ('أمين صندوق','أمين الصندوق')
                  )
                ORDER BY COALESCE(e.full_name_ar, e.full_name, e.employee_code)
                """.trimIndent(), arrayOf(stationId.toString())
            ).use { cursorToJsonArray(it) }

            val attendants = db.rawQuery(
                """
                SELECT e.id, e.employee_code, e.full_name, e.full_name_ar,
                       e.job_title, e.job_title_ar, e.department, e.station_id,
                       e.user_id, e.status
                FROM employees e
                WHERE e.station_id = ? AND e.is_deleted = 0 AND e.status = 'active'
                ORDER BY COALESCE(e.full_name_ar, e.full_name, e.employee_code)
                """.trimIndent(), arrayOf(stationId.toString())
            ).use { cursorToJsonArray(it) }

            JSONObject().apply {
                put("success", true)
                put("current_user", currentUser)
                put("station", station)
                put("managers", allManagers)
                put("cashiers", cashiers)
                put("attendants", attendants)
            }
        } finally {
            dbLock.unlock()
        }
    }

