    private fun primaryPartyContactSql(partyAlias: String, column: String): String =
        "(SELECT pc.$column FROM party_contacts pc WHERE pc.party_id = $partyAlias.id AND pc.is_deleted = 0 AND pc.is_active = 1 ORDER BY pc.is_primary DESC, pc.id ASC LIMIT 1)"

    private fun primaryPartyAddressSql(partyAlias: String, column: String): String =
        "(SELECT pa.$column FROM party_addresses pa WHERE pa.party_id = $partyAlias.id AND pa.is_deleted = 0 ORDER BY pa.is_default DESC, pa.id ASC LIMIT 1)"

    /**
     * إسقاط موحد للطرف يعيد الحقول legacy التي تحتاجها شاشات WebView،
     * مع قراءتها من الجداول المطَبّعة party_contacts وparty_addresses.
     */
    private fun partyProjection(partyAlias: String = "p"): String = listOf(
        "$partyAlias.id",
        "$partyAlias.party_code",
        "$partyAlias.barcode",
        "$partyAlias.qr_code",
        "$partyAlias.party_type_id",
        "$partyAlias.station_id",
        "$partyAlias.commercial_name",
        "$partyAlias.commercial_name_ar",
        "$partyAlias.legal_name",
        "COALESCE(${primaryPartyContactSql(partyAlias, "phone")}, '') AS phone",
        "COALESCE(${primaryPartyContactSql(partyAlias, "phone2")}, '') AS phone2",
        "COALESCE(${primaryPartyContactSql(partyAlias, "email")}, '') AS email",
        "COALESCE(${primaryPartyAddressSql(partyAlias, "address_line1")}, '') AS address",
        "COALESCE(${primaryPartyAddressSql(partyAlias, "city")}, '') AS city",
        "COALESCE(${primaryPartyAddressSql(partyAlias, "state")}, '') AS region",
        "$partyAlias.tax_number",
        "$partyAlias.commercial_register",
        "$partyAlias.vat_number",
        "$partyAlias.credit_limit",
        "$partyAlias.current_balance",
        "$partyAlias.total_purchases",
        "$partyAlias.total_payments",
        "$partyAlias.total_due",
        "$partyAlias.overdue_amount",
        "$partyAlias.payment_terms",
        "$partyAlias.currency_id",
        "$partyAlias.loyalty_points",
        "$partyAlias.loyalty_tier",
        "$partyAlias.risk_level",
        "$partyAlias.blacklist_reason",
        "$partyAlias.blacklist_date",
        "$partyAlias.blacklist_by",
        "$partyAlias.referred_by",
        "$partyAlias.assigned_to",
        "$partyAlias.rating",
        "$partyAlias.total_orders",
        "$partyAlias.total_order_amount",
        "$partyAlias.on_time_rate",
        "$partyAlias.fuel_type_preference_id",
        "$partyAlias.fleet_size",
        "$partyAlias.is_active",
        "$partyAlias.extra_data",
        "$partyAlias.created_at",
        "$partyAlias.updated_at"
    ).joinToString(", ")

    private fun syncLegacyPartyContact(db: SQLiteDatabase, partyId: Long, data: JSONObject) {
        val keys = listOf("phone", "phone2", "email")
        if (keys.none { data.has(it) }) return
        val existingId = db.rawQuery(
            "SELECT id FROM party_contacts WHERE party_id = ? AND is_deleted = 0 ORDER BY is_primary DESC, id ASC LIMIT 1",
            arrayOf(partyId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) cursor.getLong(0) else 0L }
        val values = ContentValues().apply {
            put("party_id", partyId)
            put("contact_name", data.optString("contact_name", data.optString("commercial_name", "جهة اتصال")).trim().ifEmpty { "جهة اتصال" })
            put("contact_name_ar", data.optString("contact_name_ar", data.optString("commercial_name_ar", "جهة اتصال")).trim())
            put("phone", data.optString("phone", "").trim())
            put("phone2", data.optString("phone2", "").trim())
            put("email", data.optString("email", "").trim())
            put("is_primary", 1)
            put("is_active", 1)
            put("is_deleted", 0)
            put("updated_at", getCurrentDateTime())
        }
        if (existingId > 0L) {
            db.update("party_contacts", values, "id = ?", arrayOf(existingId.toString()))
        } else {
            values.put("uuid", UUID.randomUUID().toString())
            values.put("created_at", getCurrentDateTime())
            db.insertOrThrow("party_contacts", null, values)
        }
    }

    private fun syncLegacyPartyAddress(db: SQLiteDatabase, partyId: Long, data: JSONObject) {
        val addressObject = data.opt("address") as? JSONObject
        val hasAddress = data.has("address") || data.has("address_line1") || data.has("address_line2") || data.has("city") || data.has("region") || data.has("state")
        if (!hasAddress) return
        val addressText = addressObject?.optString("address_line1", "") ?: data.optString("address", "")
        val addressLine2 = addressObject?.optString("address_line2", "") ?: data.optString("address_line2", "")
        val city = addressObject?.optString("city", "") ?: data.optString("city", "")
        val state = addressObject?.optString("state", "") ?: data.optString("region", data.optString("state", ""))
        val existingId = db.rawQuery(
            "SELECT id FROM party_addresses WHERE party_id = ? AND is_default = 1 AND is_deleted = 0 ORDER BY id ASC LIMIT 1",
            arrayOf(partyId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) cursor.getLong(0) else 0L }
        val values = ContentValues().apply {
            put("party_id", partyId)
            put("address_type", addressObject?.optString("address_type", "main") ?: "main")
            put("address_line1", addressText.trim())
            put("address_line2", addressLine2.trim())
            put("city", city.trim())
            put("state", state.trim())
            put("postal_code", addressObject?.optString("postal_code", "") ?: data.optString("postal_code", ""))
            put("country", addressObject?.optString("country", "") ?: data.optString("country", ""))
            put("is_default", 1)
            put("is_deleted", 0)
            put("updated_at", getCurrentDateTime())
        }
        if (existingId > 0L) {
            db.update("party_addresses", values, "id = ?", arrayOf(existingId.toString()))
        } else {
            values.put("uuid", UUID.randomUUID().toString())
            values.put("created_at", getCurrentDateTime())
            db.insertOrThrow("party_addresses", null, values)
        }
    }

    fun getParties(typeId: Int? = null, stationScopeId: Int? = null): JSONArray {
        val arr = JSONArray()
        val db = readableDatabase
        val predicates = mutableListOf("is_deleted=0")
        val args = mutableListOf<String>()
        if (typeId != null) { predicates += "party_type_id=?"; args += typeId.toString() }
        if (stationScopeId != null) { require(stationScopeId > 0) { "معرف المحطة غير صالح" }; predicates += "station_id=?"; args += stationScopeId.toString() }
        val sql = "SELECT ${partyProjection("p")} FROM parties p WHERE ${predicates.joinToString(" AND ")} ORDER BY p.commercial_name"
        db.rawQuery(sql, if (args.isEmpty()) null else args.toTypedArray()).use { cursor ->
            while (cursor.moveToNext()) {
                arr.put(partyCursorToJson(cursor))
            }
        }
        return arr
    }

        private fun partyTypeCodesFor(kind: String): List<String>? = when (kind.trim().lowercase(Locale.US)) {
        "customer", "customers" -> listOf("INDIVIDUAL", "COMPANY", "GOVERNMENT", "TRANSPORT", "CONTRACTOR")
        "supplier", "suppliers" -> listOf("SUPPLIER")
        "driver", "drivers" -> listOf("DRIVER")
        else -> null
    }

    fun getParties(type: String): JSONArray = getParties(type, null)

    fun getParties(type: String, stationScopeId: Int?): JSONArray {
        val codes = partyTypeCodesFor(type)
        if (stationScopeId != null) require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        val db = readableDatabase
        val predicates = mutableListOf("p.is_deleted=0")
        val args = mutableListOf<String>()
        if (codes != null) {
            predicates += "p.party_type_id IN (SELECT id FROM party_types WHERE is_deleted=0 AND type_code IN (${codes.joinToString(",") { "?" }}))"
            args += codes
        }
        if (stationScopeId != null) {
            predicates += "p.station_id=?"
            args += stationScopeId.toString()
        }
        val projection = partyProjection("p")
        val sql = "SELECT $projection FROM parties p WHERE ${predicates.joinToString(" AND ")} ORDER BY p.commercial_name"
        db.rawQuery(sql, if (args.isEmpty()) null else args.toTypedArray()).use { cursor ->
            val arr = JSONArray()
            while (cursor.moveToNext()) arr.put(partyCursorToJson(cursor))
            return arr
        }
    }

    fun getParty(id: Int, stationScopeId: Int? = null): JSONObject? {
        val db = readableDatabase
        val selection = if (stationScopeId != null) "id=? AND station_id=? AND is_deleted=0" else "id=? AND is_deleted=0"
        val args = if (stationScopeId != null) arrayOf(id.toString(), stationScopeId.toString()) else arrayOf(id.toString())

        val projection = partyProjection("p")
        return db.rawQuery(
            "SELECT $projection FROM parties p WHERE $selection",
            args
        ).use { cursor ->

            if (cursor.moveToFirst()) {
                partyCursorToJson(cursor)
            } else {
                null
            }
        }
    }

    fun getPartyById(id: Long, stationScopeId: Int? = null): JSONObject? = getParty(id.toInt(), stationScopeId)

        private fun requirePartyInStation(db: SQLiteDatabase, partyId: Long, stationScopeId: Int) {
        require(partyId > 0 && stationScopeId > 0) { "معرف الطرف والمحطة مطلوبان" }
        val owned = db.rawQuery(
            "SELECT 1 FROM parties WHERE id=? AND station_id=? AND is_deleted=0 LIMIT 1",
            arrayOf(partyId.toString(), stationScopeId.toString())
        ).use { it.moveToFirst() }
        require(owned) { "الطرف غير موجود ضمن محطة المستخدم" }
    }

    private fun jsonBooleanFlag(data: JSONObject, key: String, defaultValue: Int = 1): Int {
        if (!data.has(key) || data.isNull(key)) return defaultValue
        return when (val value = data.opt(key)) {
            is Boolean -> if (value) 1 else 0
            is Number -> if (value.toInt() != 0) 1 else 0
            is String -> when (value.trim().lowercase(Locale.US)) {
                "1", "true", "yes", "on" -> 1
                "0", "false", "no", "off" -> 0
                else -> defaultValue
            }
            else -> defaultValue
        }
    }

    private fun resolvePartyTypeId(db: SQLiteDatabase, requestedId: Int, requestedKind: String): Int {
        val normalized = requestedKind.trim().lowercase(Locale.US)
        val typeCode = when (normalized) {
            "customer", "customers" -> "INDIVIDUAL"
            "supplier", "suppliers" -> "SUPPLIER"
            "driver", "drivers" -> "DRIVER"
            else -> ""
        }
        val cursorArgs = if (requestedId > 0) arrayOf(requestedId.toString()) else arrayOf(typeCode)
        val sql = if (requestedId > 0) {
            "SELECT id FROM party_types WHERE id=? AND is_deleted=0 AND is_active=1 LIMIT 1"
        } else {
            require(typeCode.isNotBlank()) { "نوع الطرف مطلوب" }
            "SELECT id FROM party_types WHERE type_code=? AND is_deleted=0 AND is_active=1 LIMIT 1"
        }
        return db.rawQuery(sql, cursorArgs).use { cursor ->
            require(cursor.moveToFirst()) { "نوع الطرف غير موجود أو غير نشط" }
            cursor.getInt(0)
        }
    }

    private fun nextAutomaticPartyCode(db: SQLiteDatabase, stationId: Int): String {
        val nextId = db.rawQuery("SELECT COALESCE(MAX(id), 0) + 1 FROM parties", emptyArray()).use { cursor ->
            if (cursor.moveToFirst()) cursor.getLong(0) else 1L
        }
        return "PTY-${stationId.toString().padStart(3, '0')}-${nextId.toString().padStart(6, '0')}"
    }

    fun insertParty(data: JSONObject, stationScopeId: Int? = null): Long {
        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
            val authorizedStationId = stationScopeId ?: data.optInt("station_id", 0)
            require(authorizedStationId > 0) { "معرف المحطة مطلوب" }
            val partyType = data.optString("party_type", "").trim()
            val typeId = resolvePartyTypeId(db, data.optInt("party_type_id", 0), partyType)
            val values = ContentValues().apply {
                put("uuid", UUID.randomUUID().toString())
                val requestedCode = data.optString("party_code", "").trim()
                put("party_code", if (requestedCode.isNotEmpty()) requestedCode else nextAutomaticPartyCode(db, authorizedStationId))
                put("barcode", data.optString("barcode", "").trim())
                put("qr_code", data.optString("qr_code", "").trim())
                put("party_type_id", typeId)
                put("station_id", authorizedStationId)
                put("commercial_name", data.optString("commercial_name", data.optString("party_name", "")))
                put("commercial_name_ar", data.optString("commercial_name_ar", data.optString("party_name_ar", "")))
                put("legal_name", data.optString("legal_name", ""))
                put("tax_number", data.optString("tax_number", ""))
                put("commercial_register", data.optString("commercial_register", ""))
                put("vat_number", data.optString("vat_number", "").trim())
                put("credit_limit", data.optDouble("credit_limit", 0.0))
                if (data.has("current_balance")) put("current_balance", data.optDouble("current_balance", 0.0))
                if (data.has("total_due")) put("total_due", data.optDouble("total_due", 0.0))
                put("payment_terms", data.optString("payment_terms", "").trim())
                if (data.has("currency_id") && !data.isNull("currency_id")) put("currency_id", data.optLong("currency_id"))
                if (data.has("loyalty_points")) put("loyalty_points", data.optInt("loyalty_points", 0))
                put("loyalty_tier", data.optString("loyalty_tier", "bronze"))
                put("risk_level", data.optString("risk_level", "low"))
                put("blacklist_reason", data.optString("blacklist_reason", "").trim())
                if (data.has("blacklist_date") && !data.isNull("blacklist_date")) put("blacklist_date", data.optString("blacklist_date"))
                if (data.has("blacklist_by") && !data.isNull("blacklist_by")) put("blacklist_by", data.optLong("blacklist_by"))
                if (data.has("referred_by") && !data.isNull("referred_by")) put("referred_by", data.optLong("referred_by"))
                if (data.has("assigned_to") && !data.isNull("assigned_to")) put("assigned_to", data.optLong("assigned_to"))
                put("rating", data.optDouble("rating", 3.0))
                put("total_orders", data.optInt("total_orders", 0))
                put("total_order_amount", data.optDouble("total_order_amount", 0.0))
                put("on_time_rate", data.optDouble("on_time_rate", 100.0))
                if (data.has("fuel_type_preference_id") && !data.isNull("fuel_type_preference_id")) put("fuel_type_preference_id", data.optLong("fuel_type_preference_id"))
                put("fleet_size", data.optInt("fleet_size", 0))
                put("is_active", jsonBooleanFlag(data, "is_active", 1))
                put("notes", data.optString("notes", ""))
                if (data.has("extra_data")) put("extra_data", data.optString("extra_data"))
                put("created_at", getCurrentDateTime())
                put("updated_at", getCurrentDateTime())
            }
            val id = db.insert("parties", null, values)
            require(id > 0) { "تعذر حفظ الطرف في SQLite" }
            syncLegacyPartyContact(db, id, data)
            syncLegacyPartyAddress(db, id, data)
            logActivity(
                "system",
                "insert_party",
                "إضافة طرف: ${data.optString("commercial_name")}",
                authorizedStationId,
                targetTable = "parties",
                targetId = id
            )
            db.setTransactionSuccessful()
            id
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun updateParty(id: Long, data: JSONObject, stationScopeId: Int? = null): Int {
        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
            val authorizedStationId = stationScopeId ?: data.optInt("station_id", 0)
            require(authorizedStationId > 0) { "معرف المحطة مطلوب" }
            val values = ContentValues().apply {
                if (data.has("barcode")) put("barcode", data.optString("barcode").trim())
                if (data.has("qr_code")) put("qr_code", data.optString("qr_code").trim())
                if (data.has("party_type_id")) {
                    val requestedTypeId = data.optInt("party_type_id", 0)
                    put("party_type_id", resolvePartyTypeId(db, requestedTypeId, data.optString("party_type", "")))
                }
                put("commercial_name", data.optString("commercial_name", data.optString("party_name", "")))
                put("commercial_name_ar", data.optString("commercial_name_ar", data.optString("party_name_ar", "")))
                put("legal_name", data.optString("legal_name", ""))
                put("tax_number", data.optString("tax_number", ""))
                put("commercial_register", data.optString("commercial_register", ""))
                if (data.has("vat_number")) put("vat_number", data.optString("vat_number").trim())
                put("credit_limit", data.optDouble("credit_limit", 0.0))
                if (data.has("current_balance")) put("current_balance", data.optDouble("current_balance", 0.0))
                if (data.has("total_due")) put("total_due", data.optDouble("total_due", 0.0))
                if (data.has("payment_terms")) put("payment_terms", data.optString("payment_terms").trim())
                if (data.has("currency_id")) {
                    if (data.isNull("currency_id")) putNull("currency_id") else put("currency_id", data.optLong("currency_id"))
                }
                if (data.has("loyalty_points")) put("loyalty_points", data.optInt("loyalty_points", 0))
                if (data.has("loyalty_tier")) put("loyalty_tier", data.optString("loyalty_tier"))
                if (data.has("risk_level")) put("risk_level", data.optString("risk_level"))
                if (data.has("blacklist_reason")) put("blacklist_reason", data.optString("blacklist_reason").trim())
                if (data.has("blacklist_date")) {
                    if (data.isNull("blacklist_date")) putNull("blacklist_date") else put("blacklist_date", data.optString("blacklist_date"))
                }
                if (data.has("blacklist_by")) {
                    if (data.isNull("blacklist_by")) putNull("blacklist_by") else put("blacklist_by", data.optLong("blacklist_by"))
                }
                if (data.has("referred_by")) {
                    if (data.isNull("referred_by")) putNull("referred_by") else put("referred_by", data.optLong("referred_by"))
                }
                if (data.has("assigned_to")) {
                    if (data.isNull("assigned_to")) putNull("assigned_to") else put("assigned_to", data.optLong("assigned_to"))
                }
                if (data.has("rating")) put("rating", data.optDouble("rating", 3.0))
                if (data.has("total_orders")) put("total_orders", data.optInt("total_orders", 0))
                if (data.has("total_order_amount")) put("total_order_amount", data.optDouble("total_order_amount", 0.0))
                if (data.has("on_time_rate")) put("on_time_rate", data.optDouble("on_time_rate", 100.0))
                if (data.has("fuel_type_preference_id")) {
                    if (data.isNull("fuel_type_preference_id")) putNull("fuel_type_preference_id") else put("fuel_type_preference_id", data.optLong("fuel_type_preference_id"))
                }
                if (data.has("fleet_size")) put("fleet_size", data.optInt("fleet_size", 0))
                put("is_active", jsonBooleanFlag(data, "is_active", 1))
                put("notes", data.optString("notes", ""))
                if (data.has("extra_data")) put("extra_data", data.optString("extra_data"))
                put("updated_at", getCurrentDateTime())
            }
            val rows = db.update("parties", values, "id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), authorizedStationId.toString()))
            if (rows > 0) {
                syncLegacyPartyContact(db, id, data)
                syncLegacyPartyAddress(db, id, data)
                logActivity(
                    "system",
                    "update_party",
                    "تحديث طرف: $id",
                    authorizedStationId,
                    targetTable = "parties",
                    targetId = id
                )
            }
            db.setTransactionSuccessful()
            rows
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun deleteParty(id: Long, stationScopeId: Int? = null): Int {
        dbLock.lock()
        return try {
            val db = writableDatabase
            val authorizedStationId = stationScopeId ?: 0
            require(authorizedStationId > 0) { "معرف المحطة مطلوب" }
            val cv = ContentValues().apply { put("is_deleted", 1); put("updated_at", getCurrentDateTime()) }
            val rows = db.update("parties", cv, "id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), authorizedStationId.toString()))
            if (rows > 0) logActivity("system", "delete_party", "حذف طرف: $id")
            rows
        } finally {
            dbLock.unlock()
        }
    }

    fun archiveParty(id: Long, stationScopeId: Int? = null): Int {
        dbLock.lock()
        return try {
            val db = writableDatabase
            val authorizedStationId = stationScopeId ?: 0
            require(authorizedStationId > 0) { "معرف المحطة مطلوب" }
            val cv = ContentValues().apply {
                put("is_active", 0)
                put("updated_at", getCurrentDateTime())
            }
            val rows = db.update("parties", cv, "id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), authorizedStationId.toString()))
            if (rows > 0) logActivity("system", "archive_party", "أرشفة طرف: $id")
            rows
        } finally {
            dbLock.unlock()
        }
    }

    fun searchParties(query: String, stationScopeId: Int? = null): JSONArray {
        dbLock.lock()
        return try {
            val arr = JSONArray()
            val db = readableDatabase
            val likeQuery = "%$query%"
            db.rawQuery(
                """SELECT ${partyProjection("p")} FROM parties p
                   WHERE (p.commercial_name LIKE ? OR p.commercial_name_ar LIKE ? OR p.party_code LIKE ? OR COALESCE(${primaryPartyContactSql("p", "phone")}, '') LIKE ?)
                   AND p.is_deleted=0 AND p.station_id=? ORDER BY p.commercial_name LIMIT 50""",
                arrayOf(likeQuery, likeQuery, likeQuery, likeQuery, requireNotNull(stationScopeId).also { require(it > 0) }.toString())
            ).use { cursor ->
                while (cursor.moveToNext()) {
                    arr.put(partyCursorToJson(cursor))
                }
            }
            arr
        } finally {
            dbLock.unlock()
        }
    }

