            }
        }
        return arr
    }

    fun updateTankQuantity(tankId: Int, newQuantity: Double, operator: String = "System", stationScopeId: Int? = null): Boolean {
        val db = writableDatabase
        if (stationScopeId != null && stationScopeId > 0) {
            db.rawQuery("SELECT id FROM tanks WHERE id = ? AND station_id = ?", arrayOf(tankId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "الخزان خارج نطاق المحطة" }
            }
        }
        db.beginTransaction()
        try {
            db.execSQL("UPDATE tanks SET current_quantity = ? WHERE id = ?", arrayOf(newQuantity, tankId))
            db.setTransactionSuccessful()
            logActivity(operator, "tank_update", "تحديث كمية الخزان $tankId إلى $newQuantity لتر")
            return true
        } finally {
            db.endTransaction()
        }
    }

    // ========================================================================
    // دوال الورديات (جزء منها)
    // ========================================================================

    fun openShift(stationId: Int, shiftType: String, cashierId: Int, openingCash: Double, openingBank: Double = 0.0): Long {
        require(stationId > 0) { "معرف المحطة مطلوب لبدء الوردية" }
        require(cashierId > 0) { "معرف أمين الصندوق غير صالح" }
        require(shiftType in setOf("morning", "evening", "night", "full_day")) { "نوع الوردية غير صالح" }
        require(openingCash.isFinite() && openingCash >= 0.0) { "الرصيد النقدي الافتتاحي غير صالح" }
        require(openingBank.isFinite() && openingBank >= 0.0) { "الرصيد البنكي الافتتاحي غير صالح" }
        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
                db.rawQuery("SELECT id FROM shifts WHERE station_id = ? AND status = 'open' AND is_deleted = 0 LIMIT 1", arrayOf(stationId.toString())).use { cursor ->
                    require(!cursor.moveToFirst()) { "توجد وردية مفتوحة للمحطة الحالية" }
                }
                val shiftCode = "SHF-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}"
                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("shift_code", shiftCode)
                    put("station_id", stationId)
                    put("shift_date", getCurrentDate())
                    put("shift_type", shiftType)
                    put("start_time", getCurrentDateTime())
                    put("cashier_id", cashierId)
                    put("opening_cash", openingCash)
                    put("opening_bank", openingBank)
                    put("status", "open")
                }
                val id = db.insertOrThrow("shifts", null, cv)
                db.setTransactionSuccessful()
                id
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun saveShiftRecordTyped(
        stationId: Int,
        branchId: Int,
        shiftType: String,
        startTime: String,
        managerId: Long,
        cashierId: Long,
        attendantIds: String,
        openingCash: Double,
        openingBank: Double,
        openingCredit: Double,
        remarks: String?
    ): Long {
        require(stationId > 0) { "معرف المحطة مطلوب" }
        require(branchId > 0) { "معرف الفرع مطلوب" }
        require(
            shiftType in setOf(
                "morning", "evening", "night", "full_day"
            )
        ) { "نوع الوردية غير صالح" }
        require(managerId > 0L) { "معرف مدير الوردية مطلوب" }
        require(cashierId > 0L) { "معرف أمين الصندوق مطلوب" }
        require(startTime.isNotBlank()) { "وقت بداية الوردية مطلوب" }
        require(openingCash.isFinite() && openingCash >= 0.0) { "النقدية الافتتاحية غير صالحة" }
        require(openingBank.isFinite() && openingBank >= 0.0) { "الرصيد البنكي الافتتاحي غير صالح" }
        require(openingCredit.isFinite() && openingCredit >= 0.0) { "الرصيد الائتماني الافتتاحي غير صالح" }

        val normalizedAttendants = try {
            val input = JSONArray(
                attendantIds.ifBlank { "[]" }
            )
            val ids = JSONArray()
            for (i in 0 until input.length()) {
                val id = input.optLong(i, 0L)
                if (id > 0L) {
                    ids.put(id)
                }
            }
            ids.toString()
        } catch (_: Exception) {
            "[]"
        }

        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
                // منع وجود ورديتين مفتوحتين للمحطة نفسها.
                db.rawQuery(
                    """ 
                    SELECT id FROM shifts WHERE station_id = ? AND status = 'open' AND is_deleted = 0 LIMIT 1 
                    """.trimIndent(),
                    arrayOf(stationId.toString())
                ).use { cursor ->
                    require(!cursor.moveToFirst()) { "توجد وردية مفتوحة بالفعل لهذه المحطة" }
                }

                // التحقق من مدير الوردية: الاختيار من employees، مع الحفاظ على manager_id كـ users.id في مخطط shifts الحالي.
                val managerUserId = db.rawQuery(
                    """
                    SELECT COALESCE(e.user_id, u.id)
                    FROM employees e
                    LEFT JOIN users u ON u.id = e.user_id OR u.employee_id = e.id
                    WHERE e.id = ? AND e.station_id = ? AND e.is_deleted = 0 AND e.status = 'active'
                      AND TRIM(COALESCE(e.job_title_ar,'')) IN ('مدير المحطة','نائب مدير المحطة','مشرف وردية','مساعد مدير العمليات')
                    LIMIT 1
                    """.trimIndent(), arrayOf(managerId.toString(), stationId.toString())
                ).use { c -> if (c.moveToFirst() && !c.isNull(0)) c.getLong(0) else 0L }
                require(managerUserId > 0L) { "مدير الوردية غير صالح أو لا يملك حساب مستخدم مرتبطاً" }

                // التحقق من أمين الصندوق: المصدر employees، مع تحويل employee.id إلى user.id للحقل cashier_id الحالي.
                val cashierUserId = db.rawQuery(
                    """
                    SELECT COALESCE(e.user_id, u.id)
                    FROM employees e
                    LEFT JOIN users u ON u.id = e.user_id OR u.employee_id = e.id
                    WHERE e.id = ? AND e.station_id = ? AND e.is_deleted = 0 AND e.status = 'active'
                      AND (UPPER(TRIM(COALESCE(e.job_title,''))) = 'CASHIER' OR TRIM(COALESCE(e.job_title_ar,'')) IN ('أمين صندوق','أمين الصندوق'))
                    LIMIT 1
                    """.trimIndent(), arrayOf(cashierId.toString(), stationId.toString())
                ).use { c -> if (c.moveToFirst() && !c.isNull(0)) c.getLong(0) else 0L }
                require(cashierUserId > 0L) { "أمين الصندوق غير صالح أو لا يملك حساب مستخدم مرتبطاً" }

                // التحقق من العاملين: المصدر employees وتُحفظ معرفاتهم في JSON attendant_ids.
                val attendants = JSONArray(normalizedAttendants)
                for (i in 0 until attendants.length()) {
                    val attendantId = attendants.optLong(i, 0L)
                    require(attendantId > 0L) { "معرف أحد العاملين غير صالح" }
                    db.rawQuery(
                        "SELECT e.id FROM employees e WHERE e.id = ? AND e.station_id = ? AND e.is_deleted = 0 AND e.status = 'active' LIMIT 1",
                        arrayOf(attendantId.toString(), stationId.toString())
                    ).use { cursor -> require(cursor.moveToFirst()) { "أحد العاملين غير صالح أو لا يتبع المحطة" } }
                }

                val shiftCode = "SHF-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}"
                val cv = ContentValues().apply {
                    put(
                        "uuid", UUID.randomUUID().toString()
                    )
                    put(
                        "shift_code", shiftCode
                    )
                    put(
                        "station_id", stationId
                    )
                    put(
                        "branch_id", branchId
                    )
                    put(
                        "shift_date", startTime.take(10)
                    )
                    put(
                        "shift_type", shiftType
                    )
                    put(
                        "start_time", startTime
                    )
                    put(
                        "manager_id", managerUserId
                    )
                    put(
                        "cashier_id", cashierUserId
                    )
                    put(
                        "attendant_ids", normalizedAttendants
                    )
                    put(
                        "opening_cash", openingCash
                    )
                    put(
                        "opening_bank", openingBank
                    )
                    put(
                        "opening_credit", openingCredit
                    )
                    put(
                        "status", "open"
                    )
                    if (!remarks.isNullOrBlank()) {
                        put("remarks", remarks)
                    }
                    put(
                        "created_at", getCurrentDateTime()
                    )
                }
                val id = db.insertOrThrow(
                    "shifts", null, cv
                )
                require(id > 0L) { "تعذر الحصول على معرف الوردية بعد الحفظ" }
                db.rawQuery(
                    "SELECT id FROM shifts WHERE id = ? AND station_id = ? AND is_deleted = 0 LIMIT 1",
                    arrayOf(id.toString(), stationId.toString())
                ).use { cursor ->
                    require(cursor.moveToFirst()) {
                        "تم إدراج الوردية لكن تعذر التحقق من نطاق المحطة بعد الحفظ"
                    }
                }
                db.setTransactionSuccessful()
                id
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun closeShift(shiftId: Int, stationScopeId: Int, closingCash: Double, closingBank: Double, totalSales: Double, operator: String): Boolean {
        require(shiftId > 0) { "معرف الوردية غير صالح" }
        require(stationScopeId > 0) { "معرف المحطة مطلوب لإغلاق الوردية" }
        require(closingCash.isFinite() && closingCash >= 0.0) { "الرصيد النقدي الختامي غير صالح" }
        require(closingBank.isFinite() && closingBank >= 0.0) { "الرصيد البنكي الختامي غير صالح" }
        val db = writableDatabase
        db.beginTransaction()
        try {
            var openingCash = 0.0
            db.rawQuery("SELECT opening_cash FROM shifts WHERE id = ? AND station_id = ? AND is_deleted = 0 AND status = 'open'", arrayOf(shiftId.toString(), stationScopeId.toString())).use { cursor ->
                if (!cursor.moveToFirst()) return false
                openingCash = cursor.getDouble(0)
            }
            var total = 0.0
            var cash = 0.0
            var card = 0.0
            var transfer = 0.0
            var credit = 0.0
            var other = 0.0
            db.rawQuery("""SELECT COALESCE(SUM(net_amount),0),
                    COALESCE(SUM(CASE WHEN payment_method='cash' THEN net_amount ELSE 0 END),0),
                    COALESCE(SUM(CASE WHEN payment_method='credit_card' THEN net_amount ELSE 0 END),0),
                    COALESCE(SUM(CASE WHEN payment_method='bank_transfer' THEN net_amount ELSE 0 END),0),
                    COALESCE(SUM(CASE WHEN payment_method='credit' THEN net_amount ELSE 0 END),0),
                    COALESCE(SUM(CASE WHEN payment_method NOT IN ('cash','credit_card','bank_transfer','credit') THEN net_amount ELSE 0 END),0)
                    FROM sales_transactions WHERE shift_id=? AND station_id=? AND status='completed' AND is_deleted=0""", arrayOf(shiftId.toString(), stationScopeId.toString())).use { cursor ->
                if (cursor.moveToFirst()) { total = cursor.getDouble(0); cash = cursor.getDouble(1); card = cursor.getDouble(2); transfer = cursor.getDouble(3); credit = cursor.getDouble(4); other = cursor.getDouble(5) }
            }
            val cv = ContentValues().apply {
                put("end_time", getCurrentDateTime())
                put("closing_cash", closingCash)
                put("closing_bank", closingBank)
                put("total_sales", total)
                put("total_cash", cash)
                put("total_credit_card", card)
                put("total_bank_transfer", transfer)
                put("total_credit_sales", credit)
                put("total_other", other)
                put("cash_variance", closingCash - (openingCash + cash))
                put("status", "closed")
            }
            val rows = db.update("shifts", cv, "id = ? AND station_id = ? AND is_deleted = 0 AND status = 'open'", arrayOf(shiftId.toString(), stationScopeId.toString()))
            if (rows != 1) return false
            db.setTransactionSuccessful()
            logActivity(operator, "shift_close", "إغلاق الوردية $shiftId")
            return true
        } finally {
            db.endTransaction()
        }
    }

    fun getShifts(stationId: Int, limit: Int = 50): JSONArray {
        require(stationId > 0) { "معرف المحطة مطلوب لقراءة الورديات" }
        require(limit in 1..500) { "حجم قائمة الورديات غير صالح" }
        val arr = JSONArray()
        val db = readableDatabase
        db.rawQuery(
            "SELECT * FROM shifts WHERE station_id=? AND is_deleted=0 ORDER BY id DESC LIMIT ?",
            arrayOf(stationId.toString(), limit.toString())
        ).use { cursor ->
            while (cursor.moveToNext()) {
                arr.put(JSONObject().apply {
                    put("shift_id", cursor.getInt(cursor.getColumnIndexOrThrow("id")))
                    put("shift_code", cursor.getString(cursor.getColumnIndexOrThrow("shift_code")))
                    put("shift_type", cursor.getString(cursor.getColumnIndexOrThrow("shift_type")))
                    put("shift_date", cursor.getString(cursor.getColumnIndexOrThrow("shift_date")))
                    put("start_time", cursor.getString(cursor.getColumnIndexOrThrow("start_time")))
                    put("end_time", cursor.getString(cursor.getColumnIndexOrThrow("end_time")))
                    put("opening_cash", cursor.getDouble(cursor.getColumnIndexOrThrow("opening_cash")))
                    put("closing_cash", cursor.getDouble(cursor.getColumnIndexOrThrow("closing_cash")))
                    put("total_sales", cursor.getDouble(cursor.getColumnIndexOrThrow("total_sales")))
                    put("status", cursor.getString(cursor.getColumnIndexOrThrow("status")))
                })
            }
        }
        return arr
    }

    fun getOpenShift(stationId: Int): JSONObject? {
        require(stationId > 0) { "معرف المحطة مطلوب للوردية المفتوحة" }
        val db = readableDatabase
        db.rawQuery(
            "SELECT * FROM shifts WHERE station_id=? AND status='open' AND is_deleted=0 ORDER BY id DESC LIMIT 1",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                return JSONObject().apply {
                    put("shift_id", cursor.getInt(cursor.getColumnIndexOrThrow("id")))
                    put("shift_code", cursor.getString(cursor.getColumnIndexOrThrow("shift_code")))
                    put("opening_cash", cursor.getDouble(cursor.getColumnIndexOrThrow("opening_cash")))
                }
            }
            return null
        }
    }

    fun getCurrentShift(stationId: Int): JSONObject? = getOpenShift(stationId)

    fun deleteShift(shiftId: Long, stationScopeId: Int, deletedBy: Long, operator: String): Int {
        require(shiftId in 1L..Int.MAX_VALUE.toLong()) { "معرف الوردية غير صالح" }
        require(stationScopeId > 0) { "معرف المحطة مطلوب لحذف الوردية" }
        require(deletedBy > 0L) { "معرف المستخدم مطلوب لحذف الوردية" }
        val db = writableDatabase
        db.beginTransaction()
        try {
            val rows = db.update(
                "shifts",
                ContentValues().apply {
                    put("is_deleted", 1)
                    put("deleted_at", getCurrentDateTime())
                    put("deleted_by", deletedBy)
                },
                "id = ? AND station_id = ? AND is_deleted = 0",
                arrayOf(shiftId.toString(), stationScopeId.toString())
            )
            if (rows == 1) {
                db.setTransactionSuccessful()
                logActivity(operator, "delete_shift", "حذف وردية $shiftId")
            }
            return rows
        } finally {
            db.endTransaction()
        }
    }

    // ========================================================================
    // دوال المبيعات (جزء منها)
    // ========================================================================

    fun insertSaleTransaction(
        stationId: Int,
        shiftId: Int,
        customerPartyId: Int?,
        fuelTypeId: Int?,
        pumpId: Int?,
        nozzleId: Int?,
        liters: Double,
        pricePerLiter: Double,
        subtotal: Double,
        discountAmount: Double,
        taxAmount: Double,
        grossAmount: Double,
        netAmount: Double,
        paymentMethod: String,
        isCredit: Boolean,
        dueDate: String?,
        cashierId: Int,
        notes: String = "",
        deliveryLocation: String? = null,
        deliveryTime: String? = null,
        orderType: String = "sale",
        paidAmount: Double? = null,
        manageTransaction: Boolean = true
    ): Long {
        return insertSaleTransactionInternal(
            writableDatabase,
            stationId = stationId,
            shiftId = shiftId,
            customerPartyId = customerPartyId,
            fuelTypeId = fuelTypeId,
            pumpId = pumpId,
            nozzleId = nozzleId,
            liters = liters,
            pricePerLiter = pricePerLiter,
            subtotal = subtotal,
            discountAmount = discountAmount,
            taxAmount = taxAmount,
            grossAmount = grossAmount,
            netAmount = netAmount,
            paymentMethod = paymentMethod,
            isCredit = isCredit,
            dueDate = dueDate,
            cashierId = cashierId,
            notes = notes,
            deliveryLocation = deliveryLocation,
            deliveryTime = deliveryTime,
            orderType = orderType,
            paidAmount = paidAmount,
            manageTransaction = manageTransaction
        )
    }

    private fun insertSaleTransactionInternal(
        db: SQLiteDatabase,
        stationId: Int,
        shiftId: Int,
        customerPartyId: Int?,
        fuelTypeId: Int?,
        pumpId: Int?,
        nozzleId: Int?,
        liters: Double,
        pricePerLiter: Double,
        subtotal: Double,
        discountAmount: Double,
        taxAmount: Double,
        grossAmount: Double,
        netAmount: Double,
        paymentMethod: String,
        isCredit: Boolean,
        dueDate: String?,
        cashierId: Int,
        notes: String = "",
        deliveryLocation: String? = null,
        deliveryTime: String? = null,
        orderType: String = "sale",
        paidAmount: Double? = null,
        manageTransaction: Boolean = true
    ): Long {
        require(stationId > 0) { "معرف المحطة غير صالح" }
        require(shiftId > 0) { "معرف الوردية غير صالح" }
        require(cashierId > 0) { "معرف المستخدم غير صالح" }
        require(liters.isFinite() && liters >= 0.0) { "كمية الوقود غير صالحة" }
        require(pricePerLiter.isFinite() && pricePerLiter >= 0.0) { "سعر الوقود غير صالح" }
        require(subtotal.isFinite() && subtotal >= 0.0) { "الإجمالي الفرعي غير صالح" }
        require(discountAmount.isFinite() && discountAmount >= 0.0) { "الخصم غير صالح" }
        require(taxAmount.isFinite() && taxAmount >= 0.0) { "الضريبة غير صالحة" }
        require(grossAmount.isFinite() && grossAmount >= 0.0) { "الإجمالي غير صالح" }
        require(netAmount.isFinite() && netAmount >= 0.0) { "الصافي غير صالح" }
        require(paymentMethod in setOf("cash", "credit_card", "bank_transfer", "credit", "cheque", "mobile_money", "loyalty_points")) { "طريقة الدفع غير مدعومة" }
        require(!isCredit || customerPartyId != null) { "العميل مطلوب للبيع الآجل" }
        val actualPaid = paidAmount ?: if (isCredit) 0.0 else netAmount
        require(actualPaid.isFinite() && actualPaid >= 0.0) { "المبلغ المدفوع غير صالح" }
        require(isCredit || actualPaid + 1e-9 >= netAmount) { "المبلغ المدفوع أقل من الإجمالي" }

        dbLock.lock()
        return try {
            if (manageTransaction) db.beginTransaction()
            try {
                db.rawQuery(
                    "SELECT id FROM shifts WHERE id = ? AND station_id = ? AND status = 'open' AND is_deleted = 0",
                    arrayOf(shiftId.toString(), stationId.toString())
                ).use { cursor -> require(cursor.moveToFirst()) { "الوردية غير مفتوحة أو خارج نطاق المحطة" } }

                var customerCurrentBalance = 0.0
                var customerCreditLimit = 0.0
                if (customerPartyId != null) {
                    db.rawQuery(
                        """SELECT p.current_balance, p.credit_limit
                           FROM parties p
                           WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0 AND p.is_active = 1
                             AND p.party_type_id IN (
                                 SELECT id FROM party_types
                                 WHERE type_code IN ('INDIVIDUAL','COMPANY','GOVERNMENT','TRANSPORT','CONTRACTOR')
                                   AND is_deleted = 0 AND is_active = 1
                             )""",
                        arrayOf(customerPartyId.toString(), stationId.toString())
                    ).use { cursor ->
                        require(cursor.moveToFirst()) { "العميل خارج نطاق المحطة أو غير نشط أو ليس عميلاً معتمداً" }
                        customerCurrentBalance = cursor.getDouble(0)
                        customerCreditLimit = cursor.getDouble(1)
                    }
                }
                if (fuelTypeId != null) {
                    db.rawQuery(
                        "SELECT id FROM fuel_types WHERE id = ? AND is_deleted = 0 AND is_active = 1",
                        arrayOf(fuelTypeId.toString())
                    ).use { cursor -> require(cursor.moveToFirst()) { "نوع الوقود غير صالح" } }
                }

                var tankId: Long? = null
                if (pumpId != null) {
                    db.rawQuery(
                        "SELECT p.tank_id, t.fuel_type_id, t.current_quantity FROM pumps p JOIN tanks t ON t.id = p.tank_id WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0 AND p.status = 'active' AND t.station_id = ? AND t.is_deleted = 0 AND t.status <> 'retired'",
                        arrayOf(pumpId.toString(), stationId.toString(), stationId.toString())
                    ).use { cursor ->
                        require(cursor.moveToFirst()) { "المضخة خارج نطاق المحطة أو غير نشطة" }
                        tankId = cursor.getLong(0)
                        val tankFuelType = cursor.getLong(1)
                        require(fuelTypeId == null || tankFuelType == fuelTypeId.toLong()) { "نوع الوقود لا يطابق خزان المضخة" }
                        require(liters <= cursor.getDouble(2) + 1e-9) { "كمية الوقود غير متوفرة في الخزان" }
                    }
                }

                val saleCode = "SALE-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}"
                val invoiceNo = "INV-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}"
                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("sale_code", saleCode)
                    put("station_id", stationId)
                    put("shift_id", shiftId)
                    if (customerPartyId != null) put("customer_party_id", customerPartyId)
                    if (fuelTypeId != null) put("fuel_type_id", fuelTypeId)
                    if (pumpId != null) put("pump_id", pumpId)
                    if (nozzleId != null) put("nozzle_id", nozzleId)
                    put("liters", liters)
                    put("price_per_liter", pricePerLiter)
                    put("fuel_subtotal", liters * pricePerLiter)
                    put("subtotal", subtotal)
                    put("discount_amount", discountAmount)
                    put("tax_amount", taxAmount)
                    put("gross_amount", grossAmount)
                    put("net_amount", netAmount)
                    put("payment_method", paymentMethod)
                    put("payment_status", if (isCredit) "pending" else "paid")
                    put("paid_amount", actualPaid)
                    put("remaining_amount", (netAmount - actualPaid).coerceAtLeast(0.0))
                    put("is_credit", if (isCredit) 1 else 0)
                    if (dueDate != null) put("due_date", dueDate)
                    put("invoice_number", invoiceNo)
                    put("cashier_id", cashierId)
                    put("status", "completed")
                    put("remarks", notes)
                    put("order_type", orderType)
                    if (deliveryLocation != null) put("delivery_location", deliveryLocation)
                    if (deliveryTime != null) put("delivery_time", deliveryTime)
                }
                val saleId = db.insertOrThrow("sales_transactions", null, cv)
                if (actualPaid > 0.0) {
                    val payment = ContentValues().apply {
                        put("uuid", UUID.randomUUID().toString())
                        put("payment_code", "PAY-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}")
                        put("sale_id", saleId)
                        if (customerPartyId != null) put("customer_party_id", customerPartyId)
                        put("payment_type", if (paymentMethod == "credit") "cash" else paymentMethod)
                        put("payment_method", paymentMethod)
                        put("amount", actualPaid)
                        put("is_partial", if (actualPaid + 1e-9 < netAmount) 1 else 0)
                        put("total_invoice_amount", netAmount)
                        put("remaining_after", (netAmount - actualPaid).coerceAtLeast(0.0))
                        put("status", "completed")
                        put("created_by", cashierId)
                    }
                    db.insertOrThrow("payments", null, payment)
                }

                if (tankId != null && liters > 0.0) {
                    val changed = db.compileStatement("UPDATE tanks SET current_quantity = current_quantity - ? WHERE id = ? AND station_id = ? AND is_deleted = 0 AND current_quantity >= ?").apply {
                        bindDouble(1, liters)
                        bindLong(2, tankId!!)
                        bindLong(3, stationId.toLong())
                        bindDouble(4, liters)
                    }.executeUpdateDelete()
                    require(changed == 1) { "تعذر خصم كمية الوقود من الخزان" }
                }

                val shiftUpdated = db.compileStatement("UPDATE shifts SET total_sales = total_sales + ?, total_fuel_liters = total_fuel_liters + ? WHERE id = ? AND station_id = ? AND status = 'open' AND is_deleted = 0").apply {
                    bindDouble(1, netAmount)
                    bindDouble(2, liters)
                    bindLong(3, shiftId.toLong())
                    bindLong(4, stationId.toLong())
                }.executeUpdateDelete()
                require(shiftUpdated == 1) { "تعذر تحديث إجمالي الوردية" }

                if (isCredit && customerPartyId != null) {
                    val outstandingAmount = (netAmount - actualPaid).coerceAtLeast(0.0)
                    require(customerCreditLimit <= 0.0 || customerCurrentBalance + outstandingAmount <= customerCreditLimit + 1e-9) { "يتجاوز البيع الآجل الحد الائتماني للعميل" }
                    val partyUpdated = db.compileStatement("UPDATE parties SET current_balance = current_balance + ?, total_due = total_due + ? WHERE id = ? AND station_id = ? AND is_deleted = 0 AND is_active = 1").apply {
                        bindDouble(1, outstandingAmount)
                        bindDouble(2, outstandingAmount)
                        bindLong(3, customerPartyId.toLong())
                        bindLong(4, stationId.toLong())
                    }.executeUpdateDelete()
                    require(partyUpdated == 1) { "تعذر تحديث رصيد العميل" }
                    val ledgerCv = ContentValues().apply {
                        put("uuid", UUID.randomUUID().toString())
                        put("party_id", customerPartyId)
                        put("transaction_date", getCurrentDateTime())
                        put("transaction_type", "sale_credit")
                        put("transaction_id", saleId.toInt())
                        put("reference_number", invoiceNo)
                        put("debit", outstandingAmount)
                        put("credit", 0.0)
                        put("balance", getPartyBalance(customerPartyId))
                        put("description", "فاتورة بيع آجل: $invoiceNo")
                    }
                    db.insertOrThrow("customer_ledger", null, ledgerCv)
                }

                if (manageTransaction) db.setTransactionSuccessful()
                logActivity("cashier_$cashierId", "sale", "بيع جديد: $saleId - $netAmount")
                saleId
            } finally {
                if (manageTransaction) db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    private fun module008Page(rows: JSONArray, totalCount: Int, limit: Int, offset: Int): JSONObject = JSONObject().apply {
        put("rows", rows)
        put("total_count", totalCount)
        put("page_size", limit)
        put("offset", offset)
        put("page", if (totalCount == 0) 0 else offset / limit)
        put("total_pages", if (totalCount == 0) 0 else (totalCount + limit - 1) / limit)
    }

    fun getSalesPage(data: JSONObject, stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لقراءة المبيعات" }
        val limit = data.optInt("limit", 50).coerceIn(1, 100)
        val offset = data.optInt("offset", 0).coerceAtLeast(0)
        val where = mutableListOf("s.station_id = ?", "s.is_deleted = 0")
        val args = mutableListOf(stationScopeId.toString())
        data.optString("search").trim().takeIf { it.isNotEmpty() }?.let { q -> val like = "%$q%"; where += "(s.sale_code LIKE ? OR s.invoice_number LIKE ? OR COALESCE(p.commercial_name,'') LIKE ?)"; args += like; args += like; args += like }
        data.optString("status").trim().takeIf { it.isNotEmpty() }?.let { where += "s.status = ?"; args += it }
        data.optString("payment_method").trim().takeIf { it.isNotEmpty() }?.let { where += "s.payment_method = ?"; args += it }
        data.optString("from_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(s.created_at) >= date(?)"; args += it }
        data.optString("to_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(s.created_at) <= date(?)"; args += it }
        val whereSql = where.joinToString(" AND ")
        val db = readableDatabase
        val searchIndex = where.indexOfFirst { it.contains("p.commercial_name") }
        val finalCountSql = if (searchIndex != -1) "SELECT COUNT(*) FROM sales_transactions s LEFT JOIN parties p ON p.id = s.customer_party_id WHERE $whereSql" else "SELECT COUNT(*) FROM sales_transactions s WHERE $whereSql"
        val total = db.rawQuery(finalCountSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
        val sortColumn = when (data.optString("sort_by")) { "invoice_number" -> "s.invoice_number"; "net_amount" -> "s.net_amount"; "payment_method" -> "s.payment_method"; "created_at" -> "s.created_at"; else -> "s.id" }
        val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
        val pageArgs = args.toMutableList().apply { add(limit.toString()); add(offset.toString()) }
        val rows = db.rawQuery("""SELECT s.id AS sale_id, s.sale_code, s.invoice_number, s.station_id, s.shift_id, s.customer_party_id, COALESCE(p.commercial_name, p.commercial_name_ar, '') AS customer_name, s.subtotal, s.discount_amount, s.tax_amount, s.gross_amount, s.net_amount, s.payment_method, s.payment_status, s.paid_amount, s.remaining_amount, s.status, s.order_type, s.created_at, (SELECT COUNT(*) FROM sale_items si WHERE si.sale_id = s.id) AS item_count FROM sales_transactions s LEFT JOIN parties p ON p.id = s.customer_party_id WHERE $whereSql ORDER BY $sortColumn $direction LIMIT ? OFFSET ?""", pageArgs.toTypedArray()).use { cursorToJsonArray(it) }
        return module008Page(rows, total, limit, offset)
    }

    fun getOrdersPage(data: JSONObject, stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لقراءة الطلبات" }
        val limit = data.optInt("limit", 50).coerceIn(1, 100)
        val offset = data.optInt("offset", 0).coerceAtLeast(0)
        val where = mutableListOf("s.station_id = ?", "s.is_deleted = 0", "s.order_type = 'order'")
        val args = mutableListOf(stationScopeId.toString())
        data.optString("search").trim().takeIf { it.isNotEmpty() }?.let { q -> val like = "%$q%"; where += "(s.sale_code LIKE ? OR s.invoice_number LIKE ? OR COALESCE(p.commercial_name,'') LIKE ?)"; args += like; args += like; args += like }
        data.optString("status").trim().takeIf { it.isNotEmpty() }?.let { where += "s.status = ?"; args += it }
        data.optString("from_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(s.created_at) >= date(?)"; args += it }
        data.optString("to_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(s.created_at) <= date(?)"; args += it }
        val whereSql = where.joinToString(" AND ")
        val db = readableDatabase
        val searchIndex = where.indexOfFirst { it.contains("p.commercial_name") }
        val finalCountSql = if (searchIndex != -1) "SELECT COUNT(*) FROM sales_transactions s LEFT JOIN parties p ON p.id = s.customer_party_id WHERE $whereSql" else "SELECT COUNT(*) FROM sales_transactions s WHERE $whereSql"
        val total = db.rawQuery(finalCountSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
        val sortColumn = when (data.optString("sort_by")) { "total_amount", "net_amount" -> "s.net_amount"; "status" -> "s.status"; "created_at" -> "s.created_at"; else -> "s.id" }
        val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
        val pageArgs = args.toMutableList().apply { add(limit.toString()); add(offset.toString()) }
        val rows = db.rawQuery("""SELECT s.id AS order_id,
                       s.sale_code AS order_number,
                       s.invoice_number,
                       s.invoice_series,
                       s.receipt_number,
                       s.station_id,
                       COALESCE(st.station_name_ar, st.station_name, '') AS station_name,
                       s.shift_id,
                       COALESCE(sh.shift_code, '') AS shift_code,
                       s.customer_party_id,
                       COALESCE(p.commercial_name_ar, p.commercial_name, p.legal_name, '') AS customer_name,
                       s.vehicle_id,
                       COALESCE(v.plate_number_ar, v.plate_number, v.vehicle_code, '') AS vehicle_name,
                       s.driver_id,
                       COALESCE(d.full_name_ar, d.full_name, d.driver_code, '') AS driver_name,
                       s.fuel_type_id,
                       COALESCE(f.fuel_name_ar, f.fuel_name, '') AS fuel_type_name,
                       s.pump_id,
                       COALESCE(pu.pump_name_ar, pu.pump_name, pu.pump_code, '') AS pump_name,
                       s.nozzle_id,
                       COALESCE(n.nozzle_number, n.nozzle_code, '') AS nozzle_name,
                       s.liters AS quantity,
                       s.price_per_liter,
                       s.fuel_subtotal,
                       s.product_id,
                       s.quantity AS product_quantity,
                       s.unit_price,
                       s.product_subtotal,
                       s.subtotal,
                       s.discount_amount,
                       s.tax_amount,
                       s.vat_amount,
                       s.service_fee,
                       s.commission,
                       s.gross_amount,
                       s.net_amount AS total_amount,
                       s.payment_method,
                       s.payment_status,
                       s.paid_amount,
                       s.remaining_amount,
                       s.is_credit,
                       s.status,
                       s.order_type,
                       s.delivery_location,
                       s.delivery_time,
                       s.cashier_id,
                       s.created_at
                FROM sales_transactions s
                LEFT JOIN parties p ON p.id = s.customer_party_id
                LEFT JOIN stations st ON st.id = s.station_id
                LEFT JOIN shifts sh ON sh.id = s.shift_id
                LEFT JOIN vehicles v ON v.id = s.vehicle_id
                LEFT JOIN drivers d ON d.id = s.driver_id
                LEFT JOIN fuel_types f ON f.id = s.fuel_type_id
                LEFT JOIN pumps pu ON pu.id = s.pump_id
                LEFT JOIN pump_nozzles n ON n.id = s.nozzle_id
                WHERE $whereSql
                ORDER BY $sortColumn $direction LIMIT ? OFFSET ?""", pageArgs.toTypedArray()).use { cursorToJsonArray(it) }
        return module008Page(rows, total, limit, offset)
    }

    fun getLatestCustomerSaleForDelivery(
        partyId: Long,
        stationScopeId: Int
    ): JSONObject {
        require(partyId > 0L) { "معرف العميل مطلوب" }
        require(stationScopeId > 0) { "معرف المحطة مطلوب" }
        val db = readableDatabase
        val sql = """
            SELECT s.id AS sale_id, s.sale_code, s.invoice_number, s.invoice_series, s.receipt_number, s.station_id, COALESCE( st.station_name_ar, st.station_name, '' ) AS station_name, s.shift_id, COALESCE( sh.shift_code, '' ) AS shift_code, s.customer_party_id, COALESCE( p.commercial_name_ar, p.commercial_name, p.legal_name, '' ) AS customer_name, s.vehicle_id, COALESCE( v.plate_number_ar, v.plate_number, v.vehicle_code, '' ) AS vehicle_name, s.driver_id, COALESCE( d.full_name_ar, d.full_name, d.driver_code, '' ) AS driver_name, s.fuel_type_id, COALESCE( f.fuel_name_ar, f.fuel_name, '' ) AS fuel_type_name, s.pump_id, COALESCE( pu.pump_name_ar, pu.pump_name, pu.pump_code, '' ) AS pump_name, s.nozzle_id, COALESCE( n.nozzle_number, n.nozzle_code, '' ) AS nozzle_name, s.liters AS quantity, s.price_per_liter, s.fuel_subtotal, s.product_id, s.quantity AS product_quantity, s.unit_price, s.product_subtotal, s.subtotal, s.discount_amount, s.tax_amount, s.vat_amount, s.service_fee, s.commission, s.gross_amount, s.net_amount AS total_amount, s.payment_method, s.payment_status, s.paid_amount, s.remaining_amount, s.is_credit, s.status, s.order_type, s.delivery_location AS location, s.delivery_time, s.cashier_id, s.created_at FROM sales_transactions s LEFT JOIN parties p ON p.id = s.customer_party_id LEFT JOIN stations st ON st.id = s.station_id LEFT JOIN shifts sh ON sh.id = s.shift_id LEFT JOIN vehicles v ON v.id = s.vehicle_id LEFT JOIN drivers d ON d.id = s.driver_id LEFT JOIN fuel_types f ON f.id = s.fuel_type_id LEFT JOIN pumps pu ON pu.id = s.pump_id LEFT JOIN pump_nozzles n ON n.id = s.nozzle_id WHERE s.station_id =? AND s.customer_party_id =? AND s.is_deleted = 0 AND s.order_type ='order' ORDER BY datetime(s.created_at) DESC, s.id DESC LIMIT 1
            """.trimIndent()
        return db.rawQuery(
            sql, arrayOf(
                stationScopeId.toString(),
                partyId.toString()
            )
        ).use { cursor ->
            val rows = cursorToJsonArray(cursor)
            if (rows.length() == 0) {
                JSONObject().apply {
                    put("found", false)
                    put("message", "لا توجد عملية شراء سابقة لهذا العميل")
                }
            } else {
                JSONObject().apply {
                    put("found", true)
                    put("sale", rows.getJSONObject(0))
                }
            }
        }
    }

    fun getDeliveriesPage(data: JSONObject, stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لقراءة التوصيلات" }
        val limit = data.optInt("limit", 50).coerceIn(1, 100)
        val offset = data.optInt("offset", 0).coerceAtLeast(0)
        val where = mutableListOf("s.station_id = ?", "d.is_deleted = 0", "s.is_deleted = 0")
        val args = mutableListOf(stationScopeId.toString())
        data.optString("search").trim().takeIf { it.isNotEmpty() }?.let { q -> val like = "%$q%"; where += "(s.sale_code LIKE ? OR s.invoice_number LIKE ? OR COALESCE(p.commercial_name,'') LIKE ? OR COALESCE(d.location,'') LIKE ?)"; repeat(4) { args += like } }
        data.optString("status").trim().takeIf { it.isNotEmpty() }?.let { where += "d.status = ?"; args += it }
        data.optLong("driver_id", 0L).takeIf { it > 0L }?.let { where += "d.driver_id = ?"; args += it.toString() }
        data.optLong("vehicle_id", 0L).takeIf { it > 0L }?.let { where += "d.vehicle_id = ?"; args += it.toString() }
        data.optString("from_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(d.delivery_date) >= date(?)"; args += it }
        data.optString("to_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(d.delivery_date) <= date(?)"; args += it }
        val whereSql = where.joinToString(" AND ")
        val db = readableDatabase
        val searchIndex = where.indexOfFirst { it.contains("p.commercial_name") }
        val finalCountSql = if (searchIndex != -1) "SELECT COUNT(*) FROM deliveries d JOIN sales_transactions s ON s.id = d.sale_id LEFT JOIN parties p ON p.id = d.party_id WHERE $whereSql" else "SELECT COUNT(*) FROM deliveries d JOIN sales_transactions s ON s.id = d.sale_id WHERE $whereSql"
        val total = db.rawQuery(finalCountSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
        val sortColumn = when (data.optString("sort_by")) { "delivery_date" -> "d.delivery_date"; "total_amount" -> "d.total_amount"; "status" -> "d.status"; else -> "d.id" }
        val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
        val rows = db.rawQuery("""SELECT d.id AS delivery_id, d.sale_id, s.sale_code, s.invoice_number, d.party_id, COALESCE(p.commercial_name, p.commercial_name_ar, '') AS customer_name, d.vehicle_id, d.driver_id, d.delivery_date, d.quantity, d.fuel_type, d.price_per_liter, d.total_amount, d.status, d.location, d.notes, d.created_at FROM deliveries d JOIN sales_transactions s ON s.id = d.sale_id LEFT JOIN parties p ON p.id = d.party_id WHERE $whereSql ORDER BY $sortColumn $direction LIMIT $limit OFFSET $offset""", args.toTypedArray()).use { cursorToJsonArray(it) }
        return module008Page(rows, total, limit, offset)
    }

    fun getFuelSalesPage(data: JSONObject, stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لقراءة مبيعات الوقود" }
        val limit = data.optInt("limit", 50).coerceIn(1, 100)
        val offset = data.optInt("offset", 0).coerceAtLeast(0)
        val where = mutableListOf("s.station_id = ?", "fs.is_deleted = 0", "s.is_deleted = 0")
        val args = mutableListOf(stationScopeId.toString())
        data.optString("search").trim().takeIf { it.isNotEmpty() }?.let { q -> val like = "%$q%"; where += "(s.sale_code LIKE ? OR s.invoice_number LIKE ? OR COALESCE(f.fuel_name,'') LIKE ? OR COALESCE(f.fuel_name_ar,'') LIKE ?)"; repeat(4) { args += like } }
        data.optLong("fuel_type_id", 0L).takeIf { it > 0L }?.let { where += "fs.fuel_type_id = ?"; args += it.toString() }
        data.optLong("pump_id", 0L).takeIf { it > 0L }?.let { where += "fs.pump_id = ?"; args += it.toString() }
        data.optLong("shift_id", 0L).takeIf { it > 0L }?.let { where += "fs.shift_id = ?"; args += it.toString() }
        data.optString("payment_method").trim().takeIf { it.isNotEmpty() }?.let { where += "fs.payment_method = ?"; args += it }
        data.optString("from_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(fs.sale_date) >= date(?)"; args += it }
        data.optString("to_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(fs.sale_date) <= date(?)"; args += it }
        val whereSql = where.joinToString(" AND ")
        val db = readableDatabase
        val searchIndex = where.indexOfFirst { it.contains("f.fuel_name") }
        val finalCountSql = if (searchIndex != -1) "SELECT COUNT(*) FROM fuel_sales fs JOIN sales_transactions s ON s.id = fs.sale_id LEFT JOIN fuel_types f ON f.id = fs.fuel_type_id WHERE $whereSql" else "SELECT COUNT(*) FROM fuel_sales fs JOIN sales_transactions s ON s.id = fs.sale_id WHERE $whereSql"
        val total = db.rawQuery(finalCountSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
        val sortColumn = when (data.optString("sort_by")) { "sale_date" -> "fs.sale_date"; "quantity" -> "fs.quantity"; "total_amount" -> "fs.total_amount"; else -> "fs.id" }
        val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
        val pageArgs = args.toMutableList().apply { add(limit.toString()); add(offset.toString()) }
        val rows = db.rawQuery("""SELECT fs.id AS fuel_sale_id, fs.sale_id, s.sale_code, s.invoice_number, fs.shift_id, fs.pump_id, fs.fuel_type_id, COALESCE(f.fuel_name, f.fuel_name_ar, '') AS fuel_name, fs.quantity, fs.price_per_liter, fs.total_amount, fs.payment_method, fs.customer_id, fs.vehicle_plate, fs.sale_date, fs.sale_time, fs.notes, fs.created_at FROM fuel_sales fs JOIN sales_transactions s ON s.id = fs.sale_id LEFT JOIN fuel_types f ON f.id = fs.fuel_type_id WHERE $whereSql ORDER BY $sortColumn $direction LIMIT ? OFFSET ?""", pageArgs.toTypedArray()).use { cursorToJsonArray(it) }
        return module008Page(rows, total, limit, offset)
    }

    fun getSalesTransactions(stationId: Int, limit: Int = 200, offset: Int = 0): JSONArray {
        require(stationId > 0) { "معرف المحطة مطلوب لقراءة المبيعات" }
        val safeLimit = limit.coerceIn(1, 1000)
        val safeOffset = offset.coerceAtLeast(0)
        val arr = JSONArray()
        val db = readableDatabase
        db.rawQuery(
            """SELECT s.id, s.sale_code, s.station_id, s.shift_id, s.customer_party_id,
                      s.liters, s.price_per_liter, s.subtotal, s.discount_amount, s.tax_amount,
                      s.gross_amount, s.net_amount, s.payment_method, s.payment_status,
                      s.paid_amount, s.remaining_amount, s.is_credit, s.due_date,
                      s.invoice_number, s.status, s.created_at, s.delivery_location,
                      s.delivery_time, s.order_type, p.commercial_name AS customer_name
               FROM sales_transactions s
               LEFT JOIN parties p ON s.customer_party_id = p.id
               WHERE s.station_id=? AND s.is_deleted=0 ORDER BY s.id DESC LIMIT ? OFFSET ?""",
            arrayOf(stationId.toString(), safeLimit.toString(), safeOffset.toString())
        ).use { cursor ->
            while (cursor.moveToNext()) {
                arr.put(saleCursorToJson(cursor).apply {
                    put("customer_name", cursor.getString(cursor.getColumnIndexOrThrow("customer_name")))
                })
            }
        }
        return arr
    }

    fun getSaleTransactionById(id: Int, stationScopeId: Int): JSONObject? {
        require(id > 0 && stationScopeId > 0) { "معرف البيع والمحطة مطلوبان" }
        val db = readableDatabase

        return db.rawQuery(
            """SELECT id, sale_code, station_id, shift_id, customer_party_id,
                      liters, price_per_liter, subtotal, discount_amount, tax_amount,
                      gross_amount, net_amount, payment_method, payment_status,
                      paid_amount, remaining_amount, is_credit, due_date,
                      invoice_number, status, created_at, delivery_location,
                      delivery_time, order_type
               FROM sales_transactions
               WHERE id=? AND station_id=? AND is_deleted=0""",
            arrayOf(id.toString(), stationScopeId.toString())
        ).use { cursor ->

            if (cursor.moveToFirst()) {
                saleCursorToJson(cursor)
            } else {
                null
            }
        }
    }

    private fun saleCursorToJson(c: Cursor): JSONObject {
        return JSONObject().apply {
            put("sale_id", c.getInt(c.getColumnIndexOrThrow("id")))
            put("sale_code", c.getString(c.getColumnIndexOrThrow("sale_code")))
            put("station_id", c.getInt(c.getColumnIndexOrThrow("station_id")))
            put("shift_id", c.getInt(c.getColumnIndexOrThrow("shift_id")))
            put("customer_party_id", c.getInt(c.getColumnIndexOrThrow("customer_party_id")))
            put("liters", c.getDouble(c.getColumnIndexOrThrow("liters")))
            put("price_per_liter", c.getDouble(c.getColumnIndexOrThrow("price_per_liter")))
            put("subtotal", c.getDouble(c.getColumnIndexOrThrow("subtotal")))
            put("discount_amount", c.getDouble(c.getColumnIndexOrThrow("discount_amount")))
            put("tax_amount", c.getDouble(c.getColumnIndexOrThrow("tax_amount")))
            put("gross_amount", c.getDouble(c.getColumnIndexOrThrow("gross_amount")))
            put("net_amount", c.getDouble(c.getColumnIndexOrThrow("net_amount")))
            put("payment_method", c.getString(c.getColumnIndexOrThrow("payment_method")))
            put("payment_status", c.getString(c.getColumnIndexOrThrow("payment_status")))
            put("paid_amount", c.getDouble(c.getColumnIndexOrThrow("paid_amount")))
            put("remaining_amount", c.getDouble(c.getColumnIndexOrThrow("remaining_amount")))
            put("is_credit", c.getInt(c.getColumnIndexOrThrow("is_credit")))
            put("due_date", c.getString(c.getColumnIndexOrThrow("due_date")))
            put("invoice_number", c.getString(c.getColumnIndexOrThrow("invoice_number")))
            put("status", c.getString(c.getColumnIndexOrThrow("status")))
            put("created_at", c.getString(c.getColumnIndexOrThrow("created_at")))
            put("delivery_location", c.getString(c.getColumnIndexOrThrow("delivery_location")))
            put("delivery_time", c.getString(c.getColumnIndexOrThrow("delivery_time")))
            put("order_type", c.getString(c.getColumnIndexOrThrow("order_type")))
        }
    }

    // ========================================================================
    // دوال الطلبات والتوصيلات (جزء منها)
    // ========================================================================

    fun addOrder(data: JSONObject, stationScopeId: Int, cashierId: Long): Long {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        require(cashierId > 0) { "معرف المستخدم غير صالح" }
        val customerPartyId = data.optLong("party_id", 0L).takeIf { it > 0L }?.toInt()
        val liters = data.optDouble("quantity", 0.0)
        require(liters.isFinite() && liters > 0.0) { "كمية الطلب يجب أن تكون أكبر من صفر" }
        val fuelTypeId = data.optLong("fuel_type_id", 0L).toInt()
        require(fuelTypeId > 0) { "نوع الوقود مطلوب للطلب" }
        val db = writableDatabase
        val pricePerLiter = if (data.has("price_per_liter") && !data.isNull("price_per_liter")) data.optDouble("price_per_liter", Double.NaN) else db.rawQuery(
            "SELECT default_sale_price FROM fuel_types WHERE id = ? AND is_deleted = 0 AND is_active = 1",
            arrayOf(fuelTypeId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else Double.NaN }
        require(pricePerLiter.isFinite() && pricePerLiter >= 0.0) { "سعر الوقود غير متاح أو غير صالح" }
        val subtotal = liters * pricePerLiter
        val totalAmount = data.optDouble("total_amount", subtotal)
        require(totalAmount.isFinite() && totalAmount >= 0.0) { "إجمالي الطلب غير صالح" }
        val paymentMethod = when (data.optString("payment_method", "credit")) {
            "بطاقة", "credit_card" -> "credit_card"
            "تحويل", "bank_transfer" -> "bank_transfer"
            "شيك", "cheque" -> "cheque"
            "نقداً", "cash" -> "cash"
            else -> "credit"
        }
        dbLock.lock()
        return try {
            insertSaleTransaction(
                stationId = stationScopeId,
                shiftId = getCurrentShift(stationScopeId)?.optLong("shift_id", 0L)?.toInt() ?: throw IllegalStateException("لا توجد وردية مفتوحة للمحطة الحالية"),
                customerPartyId = customerPartyId,
                fuelTypeId = fuelTypeId,
                pumpId = null,
                nozzleId = null,
                liters = liters,
                pricePerLiter = pricePerLiter,
                subtotal = subtotal,
                discountAmount = data.optDouble("discount", 0.0),
                taxAmount = 0.0,
                grossAmount = totalAmount,
                netAmount = totalAmount,
                paymentMethod = paymentMethod,
                isCredit = paymentMethod == "credit",
                dueDate = data.optString("due_date", null),
                cashierId = cashierId.toInt(),
                notes = data.optString("notes", ""),
                deliveryLocation = data.optString("delivery_location", data.optString("location", "")),
                deliveryTime = data.optString("delivery_time", ""),
                orderType = "order",
                paidAmount = data.optDouble("amount_paid", if (paymentMethod == "credit") 0.0 else totalAmount)
            )
        } finally { dbLock.unlock() }
    }

    fun getOrders(status: String?, stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val selection = if (status != null) "station_id = ? AND status = ? AND order_type != 'retail'" else "station_id = ? AND order_type != 'retail'"
            val selectionArgs = if (status != null) arrayOf(stationScopeId.toString(), status) else arrayOf(stationScopeId.toString())
            db.query("sales_transactions", null, selection, selectionArgs, null, null, "created_at DESC")
                .use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

    fun addDelivery(data: JSONObject, stationScopeId: Int, cashierId: Long): Long {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        require(cashierId > 0) { "معرف المستخدم غير صالح" }
        val partyId = data.optLong("party_id", 0L).takeIf { it > 0L }?.toInt()
        val vehicleId = data.optLong("vehicle_id", 0L).takeIf { it > 0L }?.toInt()
        val driverId = data.optLong("driver_id", 0L).takeIf { it > 0L }?.toInt()
        val liters = data.optDouble("quantity", 0.0)
        require(liters.isFinite() && liters > 0.0) { "كمية التوصيل يجب أن تكون أكبر من صفر" }
        val shiftId = getCurrentShift(stationScopeId)?.optLong("shift_id", 0L)?.toInt()
            ?: throw IllegalStateException("لا توجد وردية مفتوحة للمحطة الحالية")
        val db = writableDatabase
        val fuelTypeId = data.optLong("fuel_type_id", 0L).toInt().takeIf { it > 0 }
            ?: data.optString("fuel_type", "").trim().takeIf { it.isNotEmpty() }?.let { fuelCode ->
                db.rawQuery("SELECT id FROM fuel_types WHERE (fuel_code = ? OR fuel_name = ? OR fuel_name_ar = ?) AND is_deleted = 0 AND is_active = 1 LIMIT 1", arrayOf(fuelCode, fuelCode, fuelCode)).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
            } ?: 0
        require(fuelTypeId > 0) { "نوع الوقود مطلوب للتوصيل" }
        val pricePerLiter = if (data.has("price_per_liter") && !data.isNull("price_per_liter")) data.optDouble("price_per_liter", Double.NaN) else db.rawQuery(
            "SELECT default_sale_price FROM fuel_types WHERE id = ? AND is_deleted = 0 AND is_active = 1",
            arrayOf(fuelTypeId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else Double.NaN }
        require(pricePerLiter.isFinite() && pricePerLiter >= 0.0) { "سعر الوقود غير متاح أو غير صالح" }
        val totalAmount = data.optDouble("total_amount", liters * pricePerLiter)
        require(totalAmount.isFinite() && totalAmount >= 0.0) { "إجمالي التوصيل غير صالح" }
        val deliveryDate = data.optString("delivery_date", getCurrentDate()).trim()
        require(deliveryDate.isNotEmpty()) { "تاريخ التوصيل مطلوب" }
        val status = data.optString("status", "pending").trim()
        require(status in setOf("pending", "assigned", "out_for_delivery", "delivered", "failed", "cancelled")) { "حالة التوصيل غير صحيحة" }
        if (vehicleId != null) db.rawQuery("SELECT id FROM vehicles WHERE id = ? AND station_id = ? AND is_deleted = 0 AND status = 'active'", arrayOf(vehicleId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المركبة خارج نطاق المحطة أو غير نشطة" } }
        if (driverId != null) db.rawQuery("SELECT id FROM drivers WHERE id = ? AND (station_id = ? OR station_id IS NULL) AND is_deleted = 0 AND status = 'active'", arrayOf(driverId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "السائق خارج نطاق المحطة أو غير نشط" } }

        dbLock.lock()
        return try {
            db.beginTransaction()
            try {
                val saleId = insertSaleTransactionInternal(db,
                    stationId = stationScopeId,
                    shiftId = shiftId,
                    customerPartyId = partyId,
                    fuelTypeId = fuelTypeId,
                    pumpId = null,
                    nozzleId = null,
                    liters = liters,
                    pricePerLiter = pricePerLiter,
                    subtotal = liters * pricePerLiter,
                    discountAmount = 0.0,
                    taxAmount = 0.0,
                    grossAmount = totalAmount,
                    netAmount = totalAmount,
                    paymentMethod = "credit",
                    isCredit = true,
                    dueDate = data.optString("due_date", null),
                    cashierId = cashierId.toInt(),
                    notes = data.optString("notes", ""),
                    deliveryLocation = data.optString("location", ""),
                    deliveryTime = data.optString("delivery_time", ""),
                    orderType = "delivery",
                    paidAmount = data.optDouble("amount_paid", 0.0),
                    manageTransaction = false
                )
                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("sale_id", saleId)
                    if (partyId != null) put("party_id", partyId)
                    put("shift_id", shiftId)
                    if (vehicleId != null) put("vehicle_id", vehicleId)
                    if (driverId != null) put("driver_id", driverId)
                    put("delivery_date", deliveryDate)
                    put("quantity", liters)
                    put("fuel_type", fuelTypeId.toString())
                    put("price_per_liter", pricePerLiter)
                    put("total_amount", totalAmount)
                    put("status", status)
                    put("location", data.optString("location", ""))
                    put("notes", data.optString("notes", ""))
                    put("created_at", getCurrentDateTime())
                    put("updated_at", getCurrentDateTime())
                }
                db.insertOrThrow("deliveries", null, cv)
                db.setTransactionSuccessful()
                saleId
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun getDeliveries(stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            db.rawQuery(
                """SELECT d.*, s.sale_code, s.delivery_location, s.delivery_time, s.created_at as sale_date
                   FROM deliveries d
                   INNER JOIN sales_transactions s ON d.sale_id = s.id
                   WHERE d.is_deleted = 0 AND s.station_id = ?
                   ORDER BY d.created_at DESC""",
                arrayOf(stationScopeId.toString())
            ).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

    fun getTodayDeliveries(stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val today = getCurrentDate()
            db.rawQuery(
                """SELECT d.*, s.sale_code, s.delivery_location, s.delivery_time
                   FROM deliveries d
                   INNER JOIN sales_transactions s ON d.sale_id = s.id
                   WHERE d.delivery_date = ? AND d.is_deleted = 0 AND s.station_id = ?
                   ORDER BY d.created_at DESC""",
                arrayOf(today, stationScopeId.toString())
            ).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

    // ========================================================================
    // دوال مبيعات الوقود
    // ========================================================================

    fun addFuelSale(data: JSONObject, stationScopeId: Int, cashierId: Long): Long {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        require(cashierId > 0) { "معرف المستخدم غير صالح" }
        val liters = data.optDouble("quantity", 0.0)
        val pricePerLiter = data.optDouble("price_per_liter", Double.NaN)
        require(liters.isFinite() && liters > 0.0) { "كمية الوقود يجب أن تكون أكبر من صفر" }
        require(pricePerLiter.isFinite() && pricePerLiter >= 0.0) { "سعر الوقود غير صالح" }
        val subtotal = liters * pricePerLiter
        val totalAmount = data.optDouble("total_amount", subtotal)
        require(totalAmount.isFinite() && totalAmount >= 0.0) { "إجمالي مبيعات الوقود غير صالح" }
        val shiftId = getCurrentShift(stationScopeId)?.optLong("shift_id", 0L)?.toInt()
            ?: throw IllegalStateException("لا توجد وردية مفتوحة للمحطة الحالية")
        val customerId = data.optLong("customer_id", 0L).takeIf { it > 0L }?.toInt()
        val pumpId = data.optLong("pump_id", 0L).takeIf { it > 0L }?.toInt()
        val fuelTypeId = data.optLong("fuel_type_id", 0L).toInt()
        require(fuelTypeId > 0) { "نوع الوقود مطلوب" }
        val paymentMethod = when (data.optString("payment_method", "cash").trim()) {
            "آجل", "credit", "credit_sale", "credit_account", "credit_card" -> "credit"
            "بطاقة", "card", "debit_card" -> "credit_card"
            "تحويل", "bank_transfer" -> "bank_transfer"
            "شيك", "cheque" -> "cheque"
            else -> "cash"
        }
        val isCreditSale = data.optBoolean(
            "is_credit",
            paymentMethod == "credit"
        )
        val dueDate = data.optString("due_date", "").trim().ifBlank { null }
        dbLock.lock()
        return try {
            val db = writableDatabase
            val idempotencyKey = data.optString("idempotency_key", "").trim()
            db.beginTransaction()
            try {
                val existingSaleId = findFinancialIdempotency(db, "fuel_sale", stationScopeId, idempotencyKey)
                if (existingSaleId != null) return existingSaleId
                require(reserveFinancialIdempotency(db, "fuel_sale", stationScopeId, idempotencyKey)) { "مفتاح العملية مستخدم مسبقاً" }
                val saleId = insertSaleTransactionInternal(db,
                    stationId = stationScopeId,
                    shiftId = shiftId,
                    customerPartyId = customerId,
                    fuelTypeId = fuelTypeId,
                    pumpId = pumpId,
                    nozzleId = data.optLong("nozzle_id", 0L).takeIf { it > 0L }?.toInt(),
                    liters = liters,
                    pricePerLiter = pricePerLiter,
                    subtotal = subtotal,
                    discountAmount = 0.0,
                    taxAmount = 0.0,
                    grossAmount = totalAmount,
                    netAmount = totalAmount,
                    paymentMethod = paymentMethod,
                    isCredit = isCreditSale,
                    dueDate = dueDate,
                    cashierId = cashierId.toInt(),
                    notes = data.optString("notes", ""),
                    orderType = "fuel",
                    paidAmount = data.optDouble("amount_paid", totalAmount),
                    manageTransaction = false
                )
                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("sale_id", saleId)
                    put("station_id", stationScopeId)
                    put("shift_id", shiftId)
                    if (pumpId != null) put("pump_id", pumpId)
                    put("fuel_type_id", fuelTypeId)
                    put("quantity", liters)
                    put("price_per_liter", pricePerLiter)
                    put("total_amount", totalAmount)
                    put("payment_method", paymentMethod)
                    if (customerId != null) put("customer_id", customerId)
                    put("vehicle_plate", data.optString("vehicle_plate", ""))
                    put("sale_date", data.optString("sale_date", getCurrentDate()))
                    put("sale_time", data.optString("sale_time", getCurrentTime()))
                    put("notes", data.optString("notes", ""))
                    put("status", "completed")
                    put("created_at", getCurrentDateTime())
                    put("updated_at", getCurrentDateTime())
                }
                db.insertOrThrow("fuel_sales", null, cv)
                completeFinancialIdempotency(db, "fuel_sale", stationScopeId, idempotencyKey, saleId)
                db.setTransactionSuccessful()
                saleId
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun getSales(stationScopeId: Int): JSONArray = getSalesTransactions(stationScopeId, 10000)

    fun getTodaySales(stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val today = getCurrentDate()
            db.rawQuery(
                """SELECT s.*, f.fuel_name, p.commercial_name as customer_name
                   FROM sales_transactions s
                   LEFT JOIN fuel_types f ON s.fuel_type_id = f.id
                   LEFT JOIN parties p ON s.customer_party_id = p.id
                   WHERE date(s.created_at) = ? AND s.station_id = ? AND s.is_deleted = 0 AND s.sale_type = 'retail'
                   ORDER BY s.created_at DESC""",
                arrayOf(today, stationScopeId.toString())
            ).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

