    fun getProductByBarcode(barcode: String): JSONObject? = getProductByBarcode(barcode, null)

    fun getProductByBarcode(barcode: String, stationScopeId: Int?): JSONObject? {
        val db = readableDatabase
        val scoped = stationScopeId != null && stationScopeId > 0
        val sql = if (scoped) {
            "SELECT * FROM products WHERE barcode = ? AND station_id = ? AND is_deleted = 0 LIMIT 1"
        } else {
            "SELECT * FROM products WHERE barcode = ? AND is_deleted = 0 LIMIT 1"
        }
        val args = if (scoped) arrayOf(barcode, stationScopeId.toString()) else arrayOf(barcode)
        db.rawQuery(sql, args).use { cursor ->
            if (cursor.moveToFirst()) {
                return JSONObject().apply {
                    put("product_id", cursor.getInt(cursor.getColumnIndexOrThrow("id")))
                    put("product_code", cursor.getString(cursor.getColumnIndexOrThrow("product_code")))
                    put("barcode", cursor.getString(cursor.getColumnIndexOrThrow("barcode")))
                    put("product_name", cursor.getString(cursor.getColumnIndexOrThrow("product_name")))
                    put("product_name_ar", cursor.getString(cursor.getColumnIndexOrThrow("product_name_ar")))
                    put("sale_price", cursor.getDouble(cursor.getColumnIndexOrThrow("sale_price")))
                    put("purchase_price", cursor.getDouble(cursor.getColumnIndexOrThrow("purchase_price")))
                    put("quantity", cursor.getDouble(cursor.getColumnIndexOrThrow("quantity")))
                    put("minimum_stock", cursor.getDouble(cursor.getColumnIndexOrThrow("minimum_stock")))
                    put("has_expiry", cursor.getInt(cursor.getColumnIndexOrThrow("has_expiry")))
                    put("expiry_date", cursor.getString(cursor.getColumnIndexOrThrow("expiry_date")))
                    put("status", cursor.getString(cursor.getColumnIndexOrThrow("status")))
                }
            }
            return null
        }
    }

    fun completeSale(data: JSONObject, stationScopeId: Int, cashierId: Long): JSONObject {
        val result = JSONObject()
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        require(cashierId > 0) { "معرف المستخدم غير صالح" }
        dbLock.lock()
        val db = writableDatabase
        var transactionStarted = false
        try {
            val products = data.optJSONArray("products") ?: throw IllegalArgumentException("بنود البيع مطلوبة")
            require(products.length() > 0) { "لا يمكن إتمام بيع بلا بنود" }
            val shiftId = getCurrentShift(stationScopeId)?.optLong("shift_id", 0L)?.toInt()
                ?: throw IllegalStateException("لا توجد وردية مفتوحة للمحطة الحالية")
            val warehouseId = getOrCreateDefaultWarehouse(db, stationScopeId)

            data.optLong("entity_id", 0L).takeIf { it > 0L }?.let { customerId ->
                db.rawQuery("SELECT id FROM parties WHERE id = ? AND station_id = ? AND is_deleted = 0 AND is_active = 1", arrayOf(customerId.toString(), stationScopeId.toString())).use { cursor ->
                    require(cursor.moveToFirst()) { "العميل خارج نطاق المحطة أو غير نشط" }
                }
            }

            val prepared = mutableListOf<JSONObject>()
            var total = 0.0
            for (i in 0 until products.length()) {
                val item = products.getJSONObject(i)
                val productId = item.optLong("product_id", 0L)
                val quantity = item.optDouble("quantity", 0.0)
                require(productId > 0L) { "المنتج في السطر ${i + 1} غير صالح" }
                require(quantity.isFinite() && quantity > 0.0) { "كمية السطر ${i + 1} غير صالحة" }
                val product = db.rawQuery(
                    "SELECT id, sale_price, product_name FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0 AND status = 'active'",
                    arrayOf(productId.toString(), stationScopeId.toString())
                ).use { cursor ->
                    require(cursor.moveToFirst()) { "المنتج في السطر ${i + 1} خارج نطاق المحطة أو غير نشط" }
                    JSONObject().apply { put("id", cursor.getLong(0)); put("unit_price", cursor.getDouble(1)); put("product_name", cursor.getString(2)) }
                }
                val unitPrice = product.getDouble("unit_price")
                require(unitPrice.isFinite() && unitPrice >= 0.0) { "سعر المنتج غير صالح" }
                val lineTotal = quantity * unitPrice
                require(lineTotal.isFinite() && lineTotal >= 0.0) { "إجمالي السطر غير صالح" }
                total += lineTotal
                prepared += JSONObject().apply { put("product_id", productId); put("quantity", quantity); put("unit_price", unitPrice); put("line_total", lineTotal) }
            }
            require(total.isFinite() && total >= 0.0) { "إجمالي البيع غير صالح" }
            val paymentType = data.optString("payment_type", "cash")
            val paymentMethod = when (paymentType) {
                "آجل", "credit" -> "credit"
                "بطاقة", "credit_card" -> "credit_card"
                "تحويل", "bank_transfer" -> "bank_transfer"
                "شيك", "cheque" -> "cheque"
                else -> "cash"
            }
            val isCredit = paymentMethod == "credit"
            val paidAmount = data.optDouble("amount_paid", if (isCredit) 0.0 else total)
            require(paidAmount.isFinite() && paidAmount >= 0.0) { "المبلغ المدفوع غير صالح" }
            require(isCredit || paidAmount + 1e-9 >= total) { "المبلغ المدفوع أقل من الإجمالي" }
            if (isCredit) require(data.optLong("entity_id", 0L) > 0L) { "العميل مطلوب للبيع الآجل" }

            db.beginTransaction()
            transactionStarted = true
            val idempotencyKey = data.optString("idempotency_key", "").trim()
            val existingSaleId = findFinancialIdempotency(db, "product_sale", stationScopeId, idempotencyKey)
            if (existingSaleId != null) {
                result.put("success", true)
                result.put("sale_id", existingSaleId)
                return result
            }
            require(reserveFinancialIdempotency(db, "product_sale", stationScopeId, idempotencyKey)) { "مفتاح العملية مستخدم مسبقاً" }
            val saleId = insertSaleTransactionInternal(db,
                stationId = stationScopeId,
                shiftId = shiftId,
                customerPartyId = data.optLong("entity_id", 0L).takeIf { it > 0L }?.toInt(),
                fuelTypeId = null,
                pumpId = null,
                nozzleId = null,
                liters = 0.0,
                pricePerLiter = 0.0,
                subtotal = total,
                discountAmount = 0.0,
                taxAmount = 0.0,
                grossAmount = total,
                netAmount = total,
                paymentMethod = paymentMethod,
                isCredit = isCredit,
                dueDate = data.optString("due_date", null),
                cashierId = cashierId.toInt(),
                notes = data.optString("notes", ""),
                orderType = "product",
                paidAmount = paidAmount,
                manageTransaction = false
            )

            prepared.forEachIndexed { index, item ->
                val productId = item.getLong("product_id")
                val quantity = item.getDouble("quantity")
                val unitPrice = item.getDouble("unit_price")
                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("sale_id", saleId)
                    put("line_number", index + 1)
                    put("item_type", "product")
                    put("product_id", productId)
                    put("quantity", quantity)
                    put("unit_price", unitPrice)
                    put("subtotal", quantity * unitPrice)
                    put("line_total", quantity * unitPrice)
                }
                db.insertOrThrow("sale_items", null, cv)
                ensureInventoryBaselineForProduct(db, productId, warehouseId, stationScopeId)
                addStockMovementInternal(db,
                    JSONObject().apply {
                        put("product_id", productId)
                        put("warehouse_id", warehouseId)
                        put("quantity", quantity)
                        put("movement_type", "out")
                        put("reference_type", "sale")
                        put("reference_id", saleId)
                        put("unit_cost", unitPrice)
                    }, stationScopeId, cashierId
                )
            }
            completeFinancialIdempotency(db, "product_sale", stationScopeId, idempotencyKey, saleId)
            db.setTransactionSuccessful()
            result.put("success", true)
            result.put("sale_id", saleId)
            result.put("invoice_number", getSaleTransactionById(saleId.toInt(), stationScopeId)?.optString("invoice_number", "") ?: "")
        } catch (e: Exception) {
            result.put("success", false)
            result.put("error", e.message ?: "فشل إتمام البيع")
        } finally {
            if (transactionStarted) db.endTransaction()
            dbLock.unlock()
        }
        return result
    }

    private fun addStockMovementInternal(
        db: SQLiteDatabase,
        data: JSONObject,
        stationScopeId: Int,
        userId: Long
    ): Long = addStockMovement(data, stationScopeId, userId)

    private fun getOrCreateDefaultWarehouse(db: SQLiteDatabase, stationId: Int): Long {
        db.rawQuery(
            "SELECT id FROM warehouses WHERE station_id = ? AND is_active = 1 ORDER BY is_default DESC, id ASC LIMIT 1",
            arrayOf(stationId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) return cursor.getLong(0) }
        return db.insertOrThrow("warehouses", null, ContentValues().apply {
            put("uuid", UUID.randomUUID().toString())
            put("station_id", stationId)
            put("warehouse_name", "المستودع التشغيلي للمحطة $stationId")
            put("location_details", "يُنشأ تلقائياً لتسجيل حركة المخزون الموثقة")
            put("is_default", 1)
            put("is_active", 1)
        })
    }

    fun ensureOperationalWarehouse(stationScopeId: Int): Long {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        dbLock.lock()
        return try {
            getOrCreateDefaultWarehouse(writableDatabase, stationScopeId)
        } finally {
            dbLock.unlock()
        }
    }

    private fun ensureInventoryBaselineForProduct(db: SQLiteDatabase, productId: Long, warehouseId: Long, stationId: Int) {
        db.rawQuery(
            "SELECT id FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?",
            arrayOf(productId.toString(), warehouseId.toString())
        ).use { cursor -> if (cursor.moveToFirst()) return }
        val baseline = db.rawQuery(
            "SELECT quantity, purchase_price FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0",
            arrayOf(productId.toString(), stationId.toString())
        ).use { cursor ->
            require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة" }
            cursor.getDouble(0) to cursor.getDouble(1)
        }
        db.insertOrThrow("inventory_levels", null, ContentValues().apply {
            put("product_id", productId)
            put("warehouse_id", warehouseId)
            put("quantity_on_hand", baseline.first)
            put("average_cost", baseline.second)
        })
    }

    fun adjustProductStock(productId: Long, targetQuantity: Double, stationScopeId: Int, userId: Long): Double {
        require(productId > 0L) { "معرف المنتج غير صالح" }
        require(targetQuantity.isFinite() && targetQuantity >= 0.0) { "رصيد المخزون غير صالح" }
        require(stationScopeId > 0 && userId > 0L) { "نطاق المستخدم أو المحطة غير صالح" }
        dbLock.lock()
        val db = writableDatabase
        db.beginTransaction()
        return try {
            val warehouseId = getOrCreateDefaultWarehouse(db, stationScopeId)
            ensureInventoryBaselineForProduct(db, productId, warehouseId, stationScopeId)
            val current = db.rawQuery(
                "SELECT COALESCE(SUM(il.quantity_on_hand), 0) FROM inventory_levels il JOIN warehouses w ON w.id = il.warehouse_id WHERE il.product_id = ? AND w.station_id = ? AND w.is_active = 1",
                arrayOf(productId.toString(), stationScopeId.toString())
            ).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val delta = targetQuantity - current
            if (kotlin.math.abs(delta) > 1e-9) {
                val cost = db.rawQuery(
                    "SELECT purchase_price FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0",
                    arrayOf(productId.toString(), stationScopeId.toString())
                ).use { cursor -> require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة" }; cursor.getDouble(0) }
                addStockMovementInternal(db, JSONObject().apply {
                    put("product_id", productId)
                    put("warehouse_id", warehouseId)
                    put("quantity", kotlin.math.abs(delta))
                    put("signed_quantity", delta)
                    put("movement_type", "adjustment")
                    put("reference_type", "product_stock_adjustment")
                    put("unit_cost", cost)
                    put("notes", "تسوية رصيد المنتج من شاشة إدارة المنتجات")
                }, stationScopeId, userId)
            }
            db.setTransactionSuccessful()
            targetQuantity
        } finally {
            db.endTransaction()
            dbLock.unlock()
        }
    }

    fun addStockMovement(data: JSONObject, stationScopeId: Int, userId: Long): Long {
        dbLock.lock()
        return try {
            val db = writableDatabase
            val productId = data.optLong("product_id", 0).toInt()
            val quantity = data.optDouble("quantity", 0.0)
            val movementType = data.optString("movement_type", "in")
            val unitCost = data.optDouble("unit_cost", 0.0)
            val totalCost = quantity * unitCost
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            require(userId > 0) { "معرف المستخدم غير صالح" }
            val warehouseId = data.optLong("warehouse_id", 0L)
            require(warehouseId > 0L) { "المستودع مطلوب" }
            val signedAdjustment = data.optDouble("signed_quantity", 0.0)

            require(productId > 0) { "المنتج مطلوب" }
            require(quantity.isFinite() && quantity > 0.0) { "كمية الحركة يجب أن تكون رقماً أكبر من صفر" }
            require(unitCost.isFinite() && unitCost >= 0.0) { "تكلفة الوحدة غير صالحة" }
            require(movementType in setOf("in", "out", "adjustment", "transfer", "return", "damage")) { "نوع حركة المخزون غير صحيح" }
            db.rawQuery("SELECT id FROM warehouses WHERE id = ? AND station_id = ? AND is_active = 1", arrayOf(warehouseId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المستودع خارج نطاق المحطة أو غير نشط" }
            }
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة أو غير نشط" }
            }
            if (movementType == "adjustment") {
                require(signedAdjustment.isFinite() && signedAdjustment != 0.0) { "التسوية يجب أن تحتوي على كمية موجبة أو سالبة" }
            }

            val ownsTransaction = !db.inTransaction()
            if (ownsTransaction) db.beginTransaction()
            try {
                var currentQty = 0.0
                db.rawQuery(
                    "SELECT quantity_on_hand FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?",
                    arrayOf(productId.toString(), warehouseId.toString())
                ).use { cursor ->
                    if (cursor.moveToFirst()) currentQty = cursor.getDouble(0)
                }

                val quantityBefore = currentQty
                val quantityAfter = when {
                    movementType == "adjustment" -> currentQty + signedAdjustment
                    movementType == "in" || movementType == "return" -> currentQty + quantity
                    else -> currentQty - quantity
                }
                require(quantityAfter >= 0.0) { "لا يمكن خصم كمية أكبر من المخزون المتاح" }

                val cv = ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString())
                    put("movement_code", data.optString("movement_code", "INV-${System.currentTimeMillis()}"))
                    put("product_id", productId)
                    put("station_id", stationScopeId)
                    put("warehouse_id", warehouseId)
                    put("movement_type", movementType)
                    put("movement_subtype", data.optString("movement_subtype", ""))
                    put("quantity_before", quantityBefore)
                    put("quantity_change", if (movementType == "adjustment") signedAdjustment else if (movementType == "in" || movementType == "return") quantity else -quantity)
                    put("quantity_after", quantityAfter)
                    put("unit_cost", unitCost)
                    put("total_cost", totalCost)
                    put("reference_type", data.optString("reference_type", ""))
                    put("reference_id", data.optLong("reference_id", 0))
                    put("reason", data.optString("notes", ""))
                    put("performed_by", userId)
                    put("status", "completed")
                    put("created_at", getCurrentDateTime())
                }
                val id = db.insertOrThrow("inventory_movements", null, cv)
                db.rawQuery(
                    "SELECT id FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?",
                    arrayOf(productId.toString(), warehouseId.toString())
                ).use { exists ->
                    if (exists.moveToFirst()) {
                        db.execSQL(
                            "UPDATE inventory_levels SET quantity_on_hand = ? WHERE product_id = ? AND warehouse_id = ?",
                            arrayOf(quantityAfter, productId, warehouseId)
                        )
                    } else {
                        val cvInv = ContentValues().apply {
                            put("product_id", productId)
                            put("warehouse_id", warehouseId)
                            put("quantity_on_hand", quantityAfter)
                            put("average_cost", unitCost)
                        }
                        require(db.insert("inventory_levels", null, cvInv) > 0) { "تعذر إنشاء مستوى المخزون" }
                    }
                }
                val productTotal = db.rawQuery(
                    "SELECT COALESCE(SUM(il.quantity_on_hand), 0) FROM inventory_levels il JOIN warehouses w ON w.id = il.warehouse_id WHERE il.product_id = ? AND w.station_id = ? AND w.is_active = 1",
                    arrayOf(productId.toString(), stationScopeId.toString())
                ).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
                db.update(
                    "products",
                    ContentValues().apply { put("quantity", productTotal); put("updated_at", getCurrentDateTime()) },
                    "id = ? AND station_id = ?",
                    arrayOf(productId.toString(), stationScopeId.toString())
                )
                logActivity("system", "stock_movement", "$movementType: $quantity للمنتج $productId")
                if (ownsTransaction) db.setTransactionSuccessful()
                id
            } finally {
                if (ownsTransaction) db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun saveStocktakeDetail(data: JSONObject, stationScopeId: Int): Long {
        dbLock.lock()
        return try {
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val stocktakeId = data.optLong("stocktake_id", 0L)
            val productId = data.optLong("product_id", 0L)
            val countedQuantity = data.optDouble("counted_quantity", -1.0)
            require(stocktakeId > 0L && productId > 0L) { "الجرد والمنتج مطلوبان" }
            require(countedQuantity.isFinite() && countedQuantity >= 0.0) { "الكمية المعدودة غير صالحة" }
            val db = writableDatabase
            var warehouseId = 0L
            var stocktakeStatus = ""
            db.rawQuery("SELECT st.warehouse_id, st.status FROM stocktakes st JOIN warehouses w ON w.id = st.warehouse_id WHERE st.id = ? AND w.station_id = ? AND w.is_active = 1 AND st.archived = 0", arrayOf(stocktakeId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "الجرد غير موجود أو خارج نطاق المحطة" }
                warehouseId = cursor.getLong(0); stocktakeStatus = cursor.getString(1) ?: ""
            }
            require(stocktakeStatus == "draft" || stocktakeStatus == "in_progress") { "لا يمكن تعديل تفاصيل جرد غير مفتوح" }
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة أو غير نشط" } }
            db.rawQuery("SELECT id FROM stocktake_details WHERE stocktake_id = ? AND product_id = ? AND archived = 0", arrayOf(stocktakeId.toString(), productId.toString())).use { cursor -> require(!cursor.moveToFirst()) { "يوجد تفصيل نشط لنفس المنتج في هذا الجرد" } }
            val systemQuantity = db.rawQuery("SELECT COALESCE(quantity_on_hand, 0) FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?", arrayOf(productId.toString(), warehouseId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val unitCost = db.rawQuery("SELECT COALESCE(purchase_price, 0) FROM products p WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val values = ContentValues().apply { put("stocktake_id", stocktakeId); put("product_id", productId); put("system_quantity", systemQuantity); put("counted_quantity", countedQuantity); put("variance_value", (countedQuantity - systemQuantity) * unitCost); put("notes", data.optString("notes", "")); put("archived", 0) }
            db.insertOrThrow("stocktake_details", null, values)
        } finally { dbLock.unlock() }
    }

    fun updateStocktakeDetail(detailId: Long, data: JSONObject, stationScopeId: Int): Int {
        dbLock.lock()
        return try {
            require(detailId > 0L && stationScopeId > 0) { "معرف التفاصيل أو المحطة غير صالح" }
            val countedQuantity = data.optDouble("counted_quantity", -1.0)
            require(countedQuantity.isFinite() && countedQuantity >= 0.0) { "الكمية المعدودة غير صالحة" }
            val db = writableDatabase
            var stocktakeId = 0L; var productId = 0L; var warehouseId = 0L; var status = ""
            db.rawQuery("SELECT sd.stocktake_id, sd.product_id, st.warehouse_id, st.status FROM stocktake_details sd JOIN stocktakes st ON st.id = sd.stocktake_id JOIN warehouses w ON w.id = st.warehouse_id JOIN products p ON p.id = sd.product_id WHERE sd.id = ? AND sd.archived = 0 AND st.archived = 0 AND w.station_id = ? AND p.station_id = ? AND p.is_deleted = 0", arrayOf(detailId.toString(), stationScopeId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "تفاصيل الجرد غير موجودة أو خارج نطاق المحطة" }
                stocktakeId = cursor.getLong(0); productId = cursor.getLong(1); warehouseId = cursor.getLong(2); status = cursor.getString(3) ?: ""
            }
            require(status == "draft" || status == "in_progress") { "لا يمكن تعديل تفاصيل جرد غير مفتوح" }
            val systemQuantity = db.rawQuery("SELECT COALESCE(quantity_on_hand, 0) FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?", arrayOf(productId.toString(), warehouseId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val unitCost = db.rawQuery("SELECT COALESCE(purchase_price, 0) FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val values = ContentValues().apply { put("system_quantity", systemQuantity); put("counted_quantity", countedQuantity); put("variance_value", (countedQuantity - systemQuantity) * unitCost); if (data.has("notes")) put("notes", data.optString("notes", "")) }
            db.update("stocktake_details", values, "id = ? AND stocktake_id = ? AND archived = 0", arrayOf(detailId.toString(), stocktakeId.toString()))
        } finally { dbLock.unlock() }
    }

    fun getStocktakeDetails(stocktakeId: Long, stationScopeId: Int): JSONArray {
        require(stocktakeId > 0L && stationScopeId > 0) { "معرف الجرد أو المحطة غير صالح" }
        dbLock.lock()
        return try {
            val db = readableDatabase
            val rows = JSONArray()
            db.rawQuery(
                """SELECT sd.id AS detail_id, sd.stocktake_id, sd.product_id, p.product_code,
                          p.product_name, p.product_name_ar, sd.system_quantity, sd.counted_quantity,
                          (sd.counted_quantity - sd.system_quantity) AS quantity_variance,
                          sd.variance_value, sd.notes
                   FROM stocktake_details sd
                   JOIN stocktakes st ON st.id = sd.stocktake_id
                   JOIN warehouses w ON w.id = st.warehouse_id
                   JOIN products p ON p.id = sd.product_id
                   WHERE sd.stocktake_id = ? AND sd.archived = 0 AND st.archived = 0
                     AND w.station_id = ? AND w.is_active = 1
                     AND p.station_id = ? AND p.is_deleted = 0
                   ORDER BY p.product_name COLLATE NOCASE, sd.id""",
                arrayOf(stocktakeId.toString(), stationScopeId.toString(), stationScopeId.toString())
            ).use { cursor -> while (cursor.moveToNext()) rows.put(cursorToJsonObject(cursor)) }
            rows
        } finally { dbLock.unlock() }
    }

    fun approveStocktake(stocktakeId: Long, stationScopeId: Int, actorId: Long): Int {
        dbLock.lock()
        return try {
            require(stocktakeId > 0L) { "معرف الجرد غير صالح" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            require(actorId > 0L) { "المستخدم المعتمد مطلوب" }
            val db = writableDatabase
            var warehouseId = 0L
            var status = ""
            db.rawQuery("SELECT st.warehouse_id, st.status FROM stocktakes st JOIN warehouses w ON w.id = st.warehouse_id WHERE st.id = ? AND w.station_id = ? AND w.is_active = 1 AND st.archived = 0", arrayOf(stocktakeId.toString(), stationScopeId.toString())).use { cursor ->
                if (!cursor.moveToFirst()) return 0
                warehouseId = cursor.getLong(0)
                status = cursor.getString(1) ?: ""
            }
            if (status == "completed") return 1
            require(status == "draft" || status == "in_progress") { "لا يمكن اعتماد جرد بحالته الحالية" }
            val details = mutableListOf<Triple<Long, Long, Double>>()
            var allDetails = 0
            db.rawQuery("SELECT COUNT(*) FROM stocktake_details WHERE stocktake_id = ? AND archived = 0", arrayOf(stocktakeId.toString())).use { cursor -> if (cursor.moveToFirst()) allDetails = cursor.getInt(0) }
            db.rawQuery("SELECT sd.id, sd.product_id, sd.counted_quantity, COALESCE(p.purchase_price, 0) FROM stocktake_details sd JOIN products p ON p.id = sd.product_id WHERE sd.stocktake_id = ? AND sd.archived = 0 AND p.station_id = ? AND p.is_deleted = 0", arrayOf(stocktakeId.toString(), stationScopeId.toString())).use { cursor ->
                while (cursor.moveToNext()) details += Triple(cursor.getLong(0), cursor.getLong(1), cursor.getDouble(2))
            }
            require(allDetails > 0 && details.size == allDetails) { "تفاصيل الجرد ناقصة أو تحتوي منتجاً خارج نطاق المحطة" }
            db.beginTransaction()
            try {
                var totalVariance = 0.0
                for ((detailId, productId, countedQuantity) in details) {
                    require(countedQuantity >= 0.0) { "الكمية المعدودة غير صالحة" }
                    val currentQuantity = db.rawQuery("SELECT COALESCE(quantity_on_hand, 0) FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?", arrayOf(productId.toString(), warehouseId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
                    val delta = countedQuantity - currentQuantity
                    val unitCost = db.rawQuery("SELECT COALESCE(purchase_price, 0) FROM products p WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة" }; cursor.getDouble(0) }
                    totalVariance += delta * unitCost
                    if (delta != 0.0) {
                        val movementId = addStockMovement(JSONObject().apply {
                            put("product_id", productId)
                            put("warehouse_id", warehouseId)
                            put("movement_type", "adjustment")
                            put("quantity", kotlin.math.abs(delta))
                            put("signed_quantity", delta)
                            put("unit_cost", unitCost)
                            put("reference_type", "stocktake")
                            put("reference_id", stocktakeId)
                            put("notes", "اعتماد فروقات الجرد رقم $stocktakeId")
                        }, stationScopeId, actorId)
                        require(movementId > 0L) { "فشل تسجيل حركة تسوية الجرد" }
                    }
                    db.update("stocktake_details", ContentValues().apply { put("variance_value", delta * unitCost) }, "id = ? AND stocktake_id = ? AND archived = 0", arrayOf(detailId.toString(), stocktakeId.toString()))
                }
                val rows = db.update("stocktakes", ContentValues().apply { put("status", "completed"); put("total_variance", totalVariance) }, "id = ? AND warehouse_id = ? AND archived = 0 AND status IN ('draft','in_progress')", arrayOf(stocktakeId.toString(), warehouseId.toString()))
                require(rows == 1) { "تعذر اعتماد الجرد" }
                db.setTransactionSuccessful()
                1
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun getStockMovements(data: JSONObject, stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val where = mutableListOf("im.is_deleted = 0", "im.station_id = ?")
            val args = mutableListOf<String>(stationScopeId.toString())
            data.optString("start_date").trim().takeIf { it.isNotEmpty() }?.let {
                where += "date(im.created_at) >= date(?)"
                args += it
            }
            data.optString("end_date").trim().takeIf { it.isNotEmpty() }?.let {
                where += "date(im.created_at) <= date(?)"
                args += it
            }
            data.optString("movement_type").trim().takeIf { it in setOf("in", "out", "adjustment", "transfer", "return", "damage") }?.let {
                where += "im.movement_type = ?"
                args += it
            }
            data.optString("status").trim().takeIf { it in setOf("draft", "completed", "cancelled", "reversed") }?.let {
                where += "im.status = ?"
                args += it
            }
            data.optLong("warehouse_id", 0L).takeIf { it > 0L }?.let {
                where += "im.warehouse_id = ?"
                args += it.toString()
            }
            data.optLong("product_id", 0L).takeIf { it > 0L }?.let {
                where += "im.product_id = ?"
                args += it.toString()
            }
            data.optLong("movement_id", 0L).takeIf { it > 0L }?.let {
                where += "im.id = ?"
                args += it.toString()
            }
            data.optString("query").trim().takeIf { it.isNotEmpty() }?.let {
                where += "(p.product_name LIKE ? OR p.product_name_ar LIKE ? OR p.product_code LIKE ? OR p.barcode LIKE ?)"
                val pattern = "%$it%"
                repeat(4) { args += pattern }
            }
            val limit = data.optInt("limit", 50).coerceIn(1, 200)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val sql = """
                SELECT im.*, p.product_name, p.product_name_ar, p.product_code,
                       w.warehouse_name, u.username AS performed_by_name
                FROM inventory_movements im
                LEFT JOIN products p ON im.product_id = p.id
                LEFT JOIN warehouses w ON im.warehouse_id = w.id
                LEFT JOIN users u ON im.performed_by = u.id
                WHERE ${where.joinToString(" AND ")}
                ORDER BY datetime(im.created_at) DESC, im.id DESC
                LIMIT $limit OFFSET $offset
            """.trimIndent()
            db.rawQuery(sql, args.toTypedArray()).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

        fun getLowStockItems(): JSONArray = getLowStockItems(null)
    fun getLowStockItems(stationId: Int?): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val scoped = stationId != null && stationId > 0
            val sql = if (scoped) {
                """SELECT p.id, p.product_code, p.barcode, p.product_name, p.product_name_ar, p.minimum_stock,
                          COALESCE((SELECT SUM(il.quantity_on_hand)
                                    FROM inventory_levels il
                                    INNER JOIN warehouses w ON w.id = il.warehouse_id
                                    WHERE il.product_id = p.id AND w.station_id = ? AND w.is_active = 1), 0) AS quantity_on_hand
                   FROM products p
                   WHERE p.station_id = ? AND p.is_deleted = 0 AND p.status = 'active'
                   AND COALESCE((SELECT SUM(il.quantity_on_hand)
                                 FROM inventory_levels il
                                 INNER JOIN warehouses w ON w.id = il.warehouse_id
                                 WHERE il.product_id = p.id AND w.station_id = ? AND w.is_active = 1), 0) <= p.minimum_stock"""
            } else {
                """SELECT p.id, p.product_code, p.barcode, p.product_name, p.product_name_ar, p.minimum_stock,
                          COALESCE((SELECT SUM(il.quantity_on_hand) FROM inventory_levels il WHERE il.product_id = p.id), 0) AS quantity_on_hand
                   FROM products p
                   WHERE p.is_deleted = 0 AND p.status = 'active'
                   AND COALESCE((SELECT SUM(il.quantity_on_hand) FROM inventory_levels il WHERE il.product_id = p.id), 0) <= p.minimum_stock"""
            }
            val args = if (scoped) arrayOf(stationId.toString(), stationId.toString(), stationId.toString()) else null
            db.rawQuery(sql, args).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }
    fun getStockMovementsPage(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        dbLock.lock()
        return try {
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val db = readableDatabase
            val where = mutableListOf("im.is_deleted = 0", "im.station_id = ?")
            val args = mutableListOf<String>(stationScopeId.toString())
            data.optString("start_date", data.optString("from_date", "")).trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) >= date(?)"; args += it }
            data.optString("end_date", data.optString("to_date", "")).trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) <= date(?)"; args += it }
            data.optString("movement_type").trim().takeIf { it in setOf("in", "out", "adjustment", "transfer", "return", "damage") }?.let { where += "im.movement_type = ?"; args += it }
            data.optString("status").trim().takeIf { it in setOf("draft", "completed", "cancelled", "reversed") }?.let { where += "im.status = ?"; args += it }
            data.optLong("warehouse_id", 0L).takeIf { it > 0L }?.let { where += "im.warehouse_id = ?"; args += it.toString() }
            data.optLong("product_id", 0L).takeIf { it > 0L }?.let { where += "im.product_id = ?"; args += it.toString() }
            data.optLong("movement_id", 0L).takeIf { it > 0L }?.let { where += "im.id = ?"; args += it.toString() }
            val query = data.optString("query", data.optString("search", "")).trim()
            if (query.isNotEmpty()) {
                where += "(im.movement_code LIKE ? OR p.product_code LIKE ? OR p.product_name LIKE ? OR p.product_name_ar LIKE ? OR w.warehouse_name LIKE ?)"
                repeat(5) { args += "%$query%" }
            }
            val whereSql = where.joinToString(" AND ")
            val countSql = "SELECT COUNT(*) FROM inventory_movements im LEFT JOIN products p ON p.id = im.product_id LEFT JOIN warehouses w ON w.id = im.warehouse_id WHERE $whereSql"
            val totalCount = db.rawQuery(countSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
            val pageSize = data.optInt("limit", 20).coerceIn(1, 200)
            val requestedPage = data.optInt("page", 1).coerceAtLeast(1)
            val offset = data.optInt("offset", (requestedPage - 1) * pageSize).coerceAtLeast(0)
            val sortColumn = when (data.optString("sort_by", "date")) {
                "quantity" -> "im.quantity_change"
                "value" -> "im.total_cost"
                "type" -> "im.movement_type"
                "warehouse" -> "w.warehouse_name"
                else -> "datetime(im.created_at)"
            }
            val sortDirection = if (data.optString("sort_dir", "desc").equals("asc", ignoreCase = true)) "ASC" else "DESC"
            val sql = """SELECT im.*, p.product_name, p.product_name_ar, p.product_code, w.warehouse_name, u.username AS performed_by_name
                       FROM inventory_movements im
                       LEFT JOIN products p ON p.id = im.product_id
                       LEFT JOIN warehouses w ON w.id = im.warehouse_id
                       LEFT JOIN users u ON u.id = im.performed_by
                       WHERE $whereSql
                       ORDER BY $sortColumn $sortDirection, im.id DESC LIMIT ? OFFSET ?"""
            val pageArgs = args.toMutableList().apply { add(pageSize.toString()); add(offset.toString()) }
            val rows = db.rawQuery(sql, pageArgs.toTypedArray()).use { cursorToJsonArray(it) }
            val page = (offset / pageSize) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + pageSize - 1) / pageSize
            JSONObject().apply {
                put("rows", rows)
                put("count", rows.length())
                put("total_count", totalCount)
                put("page", page)
                put("page_size", pageSize)
                put("total_pages", totalPages)
                put("has_next", page < totalPages)
                put("has_previous", page > 1)
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun checkLowStock(): JSONArray = getLowStockItems()
    fun transferStockMovement(data: JSONObject, stationScopeId: Int, userId: Long): Long {
        dbLock.lock()
        return try {
            val db = writableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            require(userId > 0L) { "معرف المستخدم غير صالح" }
            val productId = data.optLong("product_id", 0L)
            val sourceWarehouseId = data.optLong("source_warehouse_id", 0L)
            val targetWarehouseId = data.optLong("target_warehouse_id", 0L)
            val quantity = data.optDouble("quantity", 0.0)
            val unitCost = data.optDouble("unit_cost", 0.0)
            val stationId = stationScopeId
            val performedBy = userId
            require(productId > 0L) { "المنتج مطلوب" }
            require(sourceWarehouseId > 0L && targetWarehouseId > 0L && sourceWarehouseId != targetWarehouseId) { "مستودعا المصدر والهدف مطلوبان ويجب أن يكونا مختلفين" }
            require(quantity.isFinite() && quantity > 0.0) { "كمية التحويل يجب أن تكون رقماً أكبر من صفر" }
            require(unitCost.isFinite() && unitCost >= 0.0) { "تكلفة الوحدة غير صالحة" }
            require(performedBy > 0L) { "المستخدم المنفذ مطلوب" }
            db.rawQuery("SELECT COUNT(*) FROM warehouses WHERE id IN (?, ?) AND station_id = ? AND is_active = 1", arrayOf(sourceWarehouseId.toString(), targetWarehouseId.toString(), stationId.toString())).use { cursor ->
                require(cursor.moveToFirst() && cursor.getInt(0) == 2) { "المستودع المصدر أو الهدف خارج نطاق المحطة" }
            }
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة أو غير نشط" }
            }

            db.beginTransaction()
            try {
                fun currentQuantity(warehouseId: Long): Double = db.rawQuery(
                    "SELECT quantity_on_hand FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?",
                    arrayOf(productId.toString(), warehouseId.toString())
                ).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
                fun nextMovementCode(suffix: String): String = "TRF-${System.currentTimeMillis()}-${UUID.randomUUID().toString().take(8)}-$suffix"
                fun insertMovement(warehouseId: Long, before: Double, after: Double, subtype: String, from: Long, to: Long): Long {
                    val values = ContentValues().apply {
                        put("uuid", UUID.randomUUID().toString())
                        put("movement_code", nextMovementCode(subtype.take(3)))
                        put("product_id", productId)
                        put("station_id", stationId)
                        put("warehouse_id", warehouseId)
                        put("movement_type", "transfer")
                        put("movement_subtype", subtype)
                        put("quantity_before", before)
                        put("quantity_change", if (subtype == "transfer_out") -quantity else quantity)
                        put("quantity_after", after)
                        put("unit_cost", unitCost)
                        put("total_cost", quantity * unitCost)
                        put("from_location", from.toString())
                        put("to_location", to.toString())
                        put("reference_code", data.optString("reference_code", ""))
                        put("reason", data.optString("notes", "تحويل مخزون"))
                        put("performed_by", performedBy)
                        put("created_by", performedBy)
                        put("status", "completed")
                        put("created_at", getCurrentDateTime())
                    }
                    val id = db.insertOrThrow("inventory_movements", null, values)
                    return id
                }
                fun updateLevel(warehouseId: Long, quantityAfter: Double) {
                    val existing = db.rawQuery("SELECT id FROM inventory_levels WHERE product_id = ? AND warehouse_id = ?", arrayOf(productId.toString(), warehouseId.toString())).use { it -> it.moveToFirst() }
                    if (existing) {
                        db.execSQL("UPDATE inventory_levels SET quantity_on_hand = ?, average_cost = ? WHERE product_id = ? AND warehouse_id = ?", arrayOf(quantityAfter, unitCost, productId, warehouseId))
                    } else {
                        db.execSQL("INSERT INTO inventory_levels(product_id, warehouse_id, quantity_on_hand, average_cost) VALUES (?, ?, ?, ?)", arrayOf(productId, warehouseId, quantityAfter, unitCost))
                    }
                }

                val sourceBefore = currentQuantity(sourceWarehouseId)
                val targetBefore = currentQuantity(targetWarehouseId)
                require(sourceBefore >= quantity) { "الرصيد في المستودع المصدر غير كافٍ" }
                val sourceId = insertMovement(sourceWarehouseId, sourceBefore, sourceBefore - quantity, "transfer_out", sourceWarehouseId, targetWarehouseId)
                insertMovement(targetWarehouseId, targetBefore, targetBefore + quantity, "transfer_in", sourceWarehouseId, targetWarehouseId)
                updateLevel(sourceWarehouseId, sourceBefore - quantity)
                updateLevel(targetWarehouseId, targetBefore + quantity)
                db.setTransactionSuccessful()
                logActivity("system", "stock_transfer", "تحويل $quantity من المستودع $sourceWarehouseId إلى $targetWarehouseId للمنتج $productId")
                sourceId
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun archiveStockMovement(movementId: Long, userId: Long, stationScopeId: Int): Int {
        dbLock.lock()
        return try {
            require(movementId > 0L) { "معرّف الحركة غير صالح" }
            require(userId > 0L) { "المستخدم المنفذ مطلوب" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val values = ContentValues().apply {
                put("is_deleted", 1)
                put("deleted_at", getCurrentDateTime())
                put("deleted_by", userId)
                put("updated_at", getCurrentDateTime())
                put("updated_by", userId)
            }
            writableDatabase.update("inventory_movements", values, "id = ? AND station_id = ? AND is_deleted = 0", arrayOf(movementId.toString(), stationScopeId.toString()))
        } finally {
            dbLock.unlock()
        }
    }

    fun getInventoryMovementStats(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val where = mutableListOf("im.is_deleted = 0", "im.station_id = ?")
            val args = mutableListOf<String>(stationScopeId.toString())
            data.optString("start_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) >= date(?)"; args += it }
            data.optString("end_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) <= date(?)"; args += it }
            data.optLong("warehouse_id", 0L).takeIf { it > 0L }?.let { where += "im.warehouse_id = ?"; args += it.toString() }
            data.optLong("product_id", 0L).takeIf { it > 0L }?.let { where += "im.product_id = ?"; args += it.toString() }
            data.optString("movement_type").trim().takeIf { it in setOf("in", "out", "adjustment", "transfer", "return", "damage") }?.let { where += "im.movement_type = ?"; args += it }
            data.optString("status").trim().takeIf { it in setOf("draft", "completed", "cancelled", "reversed") }?.let { where += "im.status = ?"; args += it }
            val query = data.optString("query", data.optString("search", "")).trim()
            if (query.isNotEmpty()) {
                where += "(im.movement_code LIKE ? OR p.product_code LIKE ? OR p.product_name LIKE ? OR p.product_name_ar LIKE ?)"
                repeat(4) { args += "%$query%" }
            }
            val sql = """
                SELECT COUNT(*) AS total_movements,
                       COALESCE(SUM(im.total_cost), 0) AS total_value,
                       COALESCE(SUM(CASE WHEN date(im.created_at) = date('now') THEN 1 ELSE 0 END), 0) AS today_movements,
                       COALESCE(SUM(CASE WHEN im.status = 'draft' THEN 1 ELSE 0 END), 0) AS pending_count,
                       COALESCE(SUM(CASE WHEN im.movement_type IN ('in', 'return') THEN 1 ELSE 0 END), 0) AS inbound_count,
                       COALESCE(SUM(CASE WHEN im.movement_type IN ('out', 'damage') THEN 1 ELSE 0 END), 0) AS outbound_count,
                       COALESCE(SUM(CASE WHEN im.movement_type = 'transfer' THEN 1 ELSE 0 END), 0) AS transfer_count,
                       COALESCE(SUM(CASE WHEN im.movement_type = 'adjustment' THEN 1 ELSE 0 END), 0) AS adjustment_count
                FROM inventory_movements im
                LEFT JOIN products p ON p.id = im.product_id
                WHERE ${where.joinToString(" AND ")}
            """.trimIndent()
            db.rawQuery(sql, args.toTypedArray()).use { cursor ->
                if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun getInventoryReport(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val reportType = data.optString("report_type", "summary").ifBlank { "summary" }
            val warehouseId = data.optLong("warehouse_id", 0L)
            val categoryId = data.optLong("category_id", 0L)
            val statusFilter = data.optString("status").trim()
            val rows = JSONArray()
            if (data.optLong("warehouse_id", 0L) > 0L) {
                val requestedWarehouseId = data.optLong("warehouse_id")
                db.rawQuery("SELECT id FROM warehouses WHERE id = ? AND station_id = ? AND is_active = 1", arrayOf(requestedWarehouseId.toString(), stationScopeId.toString())).use { cursor ->
                    require(cursor.moveToFirst()) { "المستودع خارج نطاق المحطة أو غير نشط" }
                }
            }
            val categoryTotals = linkedMapOf<String, Double>()
            val movementSeries = JSONArray()
            val pageSize = data.optInt("limit", 200).coerceIn(1, 1000)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            var totalCount = 0
            var aggregateLoaded = false
            var aggregateTotalQuantity = 0.0
            var aggregateTotalValue = 0.0
            var aggregateLowStock = 0
            var aggregateCriticalStock = 0
            var aggregateWarehouseCount = 0
            if (reportType == "movement") {
                val where = mutableListOf("im.is_deleted = 0", "im.station_id = ?")
                val args = mutableListOf<String>(stationScopeId.toString())
                data.optString("start_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) >= date(?)"; args += it }
                data.optString("end_date").trim().takeIf { it.isNotEmpty() }?.let { where += "date(im.created_at) <= date(?)"; args += it }
                if (warehouseId > 0L) { where += "im.warehouse_id = ?"; args += warehouseId.toString() }
                if (categoryId > 0L) { where += "p.category_id = ?"; args += categoryId.toString() }
                data.optString("movement_type").trim().takeIf { it in setOf("in", "out", "adjustment", "transfer", "return", "damage") }?.let { where += "im.movement_type = ?"; args += it }
                val search = data.optString("search", "").trim()
                if (search.isNotBlank()) {
                    where += "(im.movement_code LIKE ? OR p.product_code LIKE ? OR p.product_name LIKE ? OR p.product_name_ar LIKE ? OR w.warehouse_name LIKE ?)"
                    repeat(5) { args += "%$search%" }
                }
                val searchIndex = where.indexOfFirst { it.contains("p.product_code") }
                val countSql = if (searchIndex != -1) "SELECT COUNT(*) FROM inventory_movements im LEFT JOIN products p ON im.product_id=p.id LEFT JOIN warehouses w ON im.warehouse_id=w.id WHERE ${where.joinToString(" AND ")}" else "SELECT COUNT(*) FROM inventory_movements im WHERE ${where.joinToString(" AND ")}"
                db.rawQuery(countSql, args.toTypedArray()).use { if (it.moveToFirst()) totalCount = it.getInt(0) }
                db.rawQuery("SELECT COALESCE(SUM(im.quantity_change),0), COALESCE(SUM(im.total_cost),0), COUNT(DISTINCT im.warehouse_id) FROM inventory_movements im LEFT JOIN products p ON im.product_id=p.id LEFT JOIN warehouses w ON im.warehouse_id=w.id WHERE ${where.joinToString(" AND ")}", args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) { aggregateTotalQuantity = cursor.getDouble(0); aggregateTotalValue = cursor.getDouble(1); aggregateWarehouseCount = cursor.getInt(2); aggregateLoaded = true } }
                val sql = """
                    SELECT im.id AS movement_id, im.movement_code, im.created_at AS movement_date,
                           im.movement_type, im.movement_subtype, im.product_id,
                           p.product_code, p.product_name, p.product_name_ar,
                           c.category_name, w.warehouse_name, im.quantity_change AS quantity,
                           im.unit_cost, im.total_cost AS total_value, im.status,
                           im.reason, im.remarks, im.performed_by, u.username AS performed_by_name
                    FROM inventory_movements im
                    LEFT JOIN products p ON im.product_id = p.id
                    LEFT JOIN product_categories c ON p.category_id = c.id
                    LEFT JOIN warehouses w ON im.warehouse_id = w.id
                    LEFT JOIN users u ON im.performed_by = u.id
                    WHERE ${where.joinToString(" AND ")}
                    ORDER BY datetime(im.created_at) DESC, im.id DESC
                    LIMIT ? OFFSET ?
                """.trimIndent()
                val pageArgs = args.toMutableList().apply { add(pageSize.toString()); add(offset.toString()) }
                db.rawQuery(sql, pageArgs.toTypedArray()).use { cursor ->
                    while (cursor.moveToNext()) rows.put(cursorToJsonObject(cursor))
                }
                db.rawQuery(
                    """SELECT date(im.created_at) AS day, COUNT(*) AS movement_count,
                              COALESCE(SUM(im.total_cost), 0) AS total_value
                       FROM inventory_movements im
                       LEFT JOIN products p ON im.product_id = p.id
                       WHERE im.is_deleted = 0 AND im.station_id = ?
                       GROUP BY date(im.created_at)
                       ORDER BY day ASC LIMIT 90""",
                    arrayOf(stationScopeId.toString())
                ).use { cursor -> while (cursor.moveToNext()) movementSeries.put(cursorToJsonObject(cursor)) }
            } else {
                val levelArgs = mutableListOf<String>()
                val levelSource = if (warehouseId > 0L) {
                    levelArgs += warehouseId.toString()
                    levelArgs += stationScopeId.toString()
                    "LEFT JOIN inventory_levels il ON p.id = il.product_id AND il.warehouse_id = ? LEFT JOIN warehouses w ON w.id = il.warehouse_id AND w.station_id = ?"
                } else {
                    levelArgs += stationScopeId.toString()
                    "LEFT JOIN (SELECT il.product_id, SUM(il.quantity_on_hand) AS quantity_on_hand, AVG(il.average_cost) AS average_cost, MAX(il.last_count_date) AS last_count_date FROM inventory_levels il JOIN warehouses sw ON sw.id = il.warehouse_id WHERE sw.station_id = ? AND sw.is_active = 1 GROUP BY il.product_id) il ON p.id = il.product_id LEFT JOIN warehouses w ON 1 = 0"
                }
                val where = mutableListOf("p.is_deleted = 0", "p.status = 'active'", "p.station_id = ?")
                val args = levelArgs.toMutableList().apply { add(stationScopeId.toString()) }
                if (categoryId > 0L) { where += "p.category_id = ?"; args += categoryId.toString() }
                data.optLong("product_id", 0L).takeIf { it > 0L }?.let { where += "p.id = ?"; args += it.toString() }
                val search = data.optString("search", "").trim()
                if (search.isNotBlank()) {
                    where += "(p.product_code LIKE ? OR p.barcode LIKE ? OR p.product_name LIKE ? OR p.product_name_ar LIKE ? OR c.category_name LIKE ?)"
                    repeat(5) { args += "%$search%" }
                }
                when {
                    reportType == "below_min" -> where += "COALESCE(il.quantity_on_hand, p.quantity, 0) <= p.minimum_stock"
                    statusFilter == "critical" -> where += "COALESCE(il.quantity_on_hand, p.quantity, 0) <= 0"
                    statusFilter == "low" -> where += "COALESCE(il.quantity_on_hand, p.quantity, 0) > 0 AND COALESCE(il.quantity_on_hand, p.quantity, 0) <= p.minimum_stock"
                    statusFilter == "active" -> where += "COALESCE(il.quantity_on_hand, p.quantity, 0) > p.minimum_stock"
                }
                val countSql = "SELECT COUNT(*) FROM products p LEFT JOIN product_categories c ON p.category_id=c.id $levelSource WHERE ${where.joinToString(" AND ")}"
                db.rawQuery(countSql, args.toTypedArray()).use { if (it.moveToFirst()) totalCount = it.getInt(0) }
                val aggregateSql = "SELECT COALESCE(SUM(COALESCE(il.quantity_on_hand, p.quantity, 0)),0), COALESCE(SUM(COALESCE(il.quantity_on_hand, p.quantity, 0) * COALESCE(il.average_cost, p.purchase_price, 0)),0), COALESCE(SUM(CASE WHEN COALESCE(il.quantity_on_hand, p.quantity, 0) <= p.minimum_stock AND COALESCE(il.quantity_on_hand, p.quantity, 0) > 0 THEN 1 ELSE 0 END),0), COALESCE(SUM(CASE WHEN COALESCE(il.quantity_on_hand, p.quantity, 0) <= 0 THEN 1 ELSE 0 END),0) FROM products p LEFT JOIN product_categories c ON p.category_id=c.id $levelSource WHERE ${where.joinToString(" AND ")}"
                db.rawQuery(aggregateSql, args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) { aggregateTotalQuantity = cursor.getDouble(0); aggregateTotalValue = cursor.getDouble(1); aggregateLowStock = cursor.getInt(2); aggregateCriticalStock = cursor.getInt(3); aggregateWarehouseCount = if (warehouseId > 0L) 1 else db.rawQuery("SELECT COUNT(*) FROM warehouses WHERE station_id = ? AND is_active = 1", arrayOf(stationScopeId.toString())).use { wCursor -> if (wCursor.moveToFirst()) wCursor.getInt(0) else 0 }; aggregateLoaded = true } }
                val sortColumn = when (data.optString("sort_by", "product_name")) {
                    "quantity" -> "quantity"
                    "purchase_price" -> "purchase_price"
                    else -> "p.product_name"
                }
                val sortDirection = if (data.optString("sort_dir", "asc").equals("desc", ignoreCase = true)) "DESC" else "ASC"
                val sql = """
                    SELECT p.id AS product_id, p.product_code, p.barcode, p.product_name, p.product_name_ar,
                           p.category_id, c.category_name, w.warehouse_name,
                           COALESCE(il.quantity_on_hand, p.quantity, 0) AS quantity,
                           COALESCE(il.average_cost, p.purchase_price, 0) AS purchase_price,
                           p.sale_price, p.minimum_stock, p.maximum_stock, p.reorder_quantity,
                           il.last_count_date,
                           CASE WHEN COALESCE(il.quantity_on_hand, p.quantity, 0) <= 0 THEN 'critical'
                                WHEN COALESCE(il.quantity_on_hand, p.quantity, 0) <= p.minimum_stock THEN 'low'
                                ELSE 'active' END AS status
                    FROM products p
                    LEFT JOIN product_categories c ON p.category_id = c.id
                    $levelSource
                    WHERE ${where.joinToString(" AND ")}
                    ORDER BY $sortColumn $sortDirection, p.id ASC
                    LIMIT ? OFFSET ?
                """.trimIndent()
                val pageArgs = args.toMutableList().apply { add(pageSize.toString()); add(offset.toString()) }
                db.rawQuery(sql, pageArgs.toTypedArray()).use { cursor ->
                    while (cursor.moveToNext()) {
                        val item = cursorToJsonObject(cursor)
                        val itemStatus = item.optString("status", "active")
                        if (statusFilter.isNotEmpty() && itemStatus != statusFilter) continue
                        if (reportType == "below_min" && itemStatus != "low" && itemStatus != "critical") continue
                        rows.put(item)
                        val category = item.optString("category_name", "أخرى").ifBlank { "أخرى" }
                        val value = item.optDouble("quantity", 0.0) * item.optDouble("purchase_price", 0.0)
                        categoryTotals[category] = (categoryTotals[category] ?: 0.0) + value
                    }
                }
            }

            var totalQuantity = 0.0
            var totalValue = 0.0
            var lowStock = 0
            var criticalStock = 0
            val warehouses = mutableSetOf<String>()
            for (i in 0 until rows.length()) {
                val item = rows.optJSONObject(i) ?: continue
                totalQuantity += item.optDouble("quantity", item.optDouble("quantity_change", 0.0))
                totalValue += item.optDouble("total_value", item.optDouble("quantity", 0.0) * item.optDouble("purchase_price", 0.0))
                when (item.optString("status")) { "low" -> lowStock++; "critical" -> criticalStock++ }
                item.optString("warehouse_name").takeIf { it.isNotBlank() }?.let { warehouses.add(it) }
            }
            if (aggregateLoaded) {
                totalQuantity = aggregateTotalQuantity
                totalValue = aggregateTotalValue
                lowStock = aggregateLowStock
                criticalStock = aggregateCriticalStock
            }
            val stats = JSONObject().apply {
                put("total_items", totalCount)
                put("total_quantity", totalQuantity)
                put("total_value", totalValue)
                put("low_stock", lowStock)
                put("critical_stock", criticalStock)
                put("warehouse_count", if (aggregateLoaded) aggregateWarehouseCount else warehouses.size)
                put("category_count", categoryTotals.size)
                put("inventory_health_score", if (totalCount == 0) 0 else (100.0 - ((criticalStock * 60.0 + lowStock * 30.0) / totalCount)).coerceIn(0.0, 100.0))
            }
            val categories = JSONArray()
            categoryTotals.forEach { (name, value) -> categories.put(JSONObject().put("category_name", name).put("total_value", value)) }
            val page = (offset / pageSize) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + pageSize - 1) / pageSize
            JSONObject().apply {
                put("report_type", reportType)
                put("rows", rows)
                put("count", rows.length())
                put("total_count", totalCount)
                put("page", page)
                put("page_size", pageSize)
                put("total_pages", totalPages)
                put("has_next", page < totalPages)
                put("has_previous", page > 1)
                put("stats", stats)
                put("categories", categories)
                put("movement_series", movementSeries)
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun getInventoryProductDetails(productId: Long, stationScopeId: Int): JSONObject? {
        dbLock.lock()
        return try {
            val db = readableDatabase
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val product = db.rawQuery(
                """SELECT p.id AS product_id, p.product_code, p.barcode, p.product_name, p.product_name_ar,
                          p.purchase_price, p.sale_price, p.minimum_stock, p.maximum_stock, p.reorder_quantity,
                          p.status, c.category_name, COALESCE(SUM(il.quantity_on_hand), p.quantity, 0) AS quantity
                   FROM products p
                   LEFT JOIN product_categories c ON p.category_id = c.id
                   LEFT JOIN inventory_levels il ON p.id = il.product_id AND EXISTS (SELECT 1 FROM warehouses iw WHERE iw.id = il.warehouse_id AND iw.station_id = ? AND iw.is_active = 1)
                   WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0

                   GROUP BY p.id""",
                arrayOf(stationScopeId.toString(), productId.toString(), stationScopeId.toString())
            ).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else null } ?: return null
            val movements = JSONArray()
            db.rawQuery(
                """SELECT im.id AS movement_id, im.movement_code, im.created_at AS movement_date,
                          im.movement_type, im.quantity_change AS quantity, im.unit_cost, im.total_cost,
                          im.status, im.reason, w.warehouse_name, u.username AS performed_by_name
                   FROM inventory_movements im
                   LEFT JOIN warehouses w ON im.warehouse_id = w.id
                   LEFT JOIN users u ON im.performed_by = u.id
                                             WHERE im.product_id = ? AND im.station_id = ? AND im.is_deleted = 0

                   ORDER BY datetime(im.created_at) DESC, im.id DESC LIMIT 50""",
                arrayOf(productId.toString(), stationScopeId.toString())
            ).use { cursor -> while (cursor.moveToNext()) movements.put(cursorToJsonObject(cursor)) }
            product.put("movements", movements)
            product
        } finally {
            dbLock.unlock()
        }
    }

    fun getProductMovementTrend(productId: Long, days: Int = 30, stationScopeId: Int): JSONObject {
        dbLock.lock()
        return try {
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val db = readableDatabase
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة أو غير نشط" }
            }
            val safeDays = days.coerceIn(1, 365)
            val labels = JSONArray()
            val inbound = JSONArray()
            val outbound = JSONArray()
            val counts = JSONArray()
            readableDatabase.rawQuery(
                """SELECT date(created_at) AS day,
                          COALESCE(SUM(CASE WHEN movement_type IN ('in', 'return') THEN ABS(quantity_change) ELSE 0 END), 0) AS inbound,
                          COALESCE(SUM(CASE WHEN movement_type IN ('out', 'damage') THEN ABS(quantity_change) ELSE 0 END), 0) AS outbound,
                          COUNT(*) AS movement_count
                   FROM inventory_movements
                   WHERE product_id = ? AND station_id = ? AND is_deleted = 0 AND date(created_at) >= date('now', ?)
                   GROUP BY date(created_at) ORDER BY day ASC""".trimIndent(),
                arrayOf(productId.toString(), stationScopeId.toString(), "-${safeDays} days")
            ).use { cursor ->
                while (cursor.moveToNext()) {
                    labels.put(cursor.getString(cursor.getColumnIndexOrThrow("day")))
                    inbound.put(cursor.getDouble(cursor.getColumnIndexOrThrow("inbound")))
                    outbound.put(cursor.getDouble(cursor.getColumnIndexOrThrow("outbound")))
                    counts.put(cursor.getInt(cursor.getColumnIndexOrThrow("movement_count")))
                }
            }
            JSONObject().apply { put("labels", labels); put("inbound", inbound); put("outbound", outbound); put("values", counts) }
        } finally {
            dbLock.unlock()
        }
    }


    fun createStockAlert(productId: Long, threshold: Double, stationScopeId: Int, createdBy: Long): Long {
        dbLock.lock()
        return try {
            val db = writableDatabase
            require(productId > 0L) { "المنتج غير صالح" }
            require(threshold >= 0.0 && threshold.isFinite()) { "الحد الأدنى غير صالح" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            require(createdBy > 0L) { "المستخدم المنشئ غير صالح" }
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة أو غير نشط" }
            }
            val currentQuantity = db.rawQuery("""SELECT COALESCE(SUM(il.quantity_on_hand), 0) FROM inventory_levels il JOIN warehouses w ON w.id = il.warehouse_id WHERE il.product_id = ? AND w.station_id = ? AND w.is_active = 1""", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor -> if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
            val cv = ContentValues().apply {
                put("uuid", UUID.randomUUID().toString())
                put("product_id", productId)
                put("station_id", stationScopeId)
                put("alert_type", "low_stock")
                put("alert_level", "warning")
                put("threshold_quantity", threshold)
                put("current_quantity", currentQuantity)
                put("is_resolved", 0)
                put("created_at", getCurrentDateTime())
                put("created_by", createdBy)
            }
            db.insert("stock_alerts", null, cv)
        } finally {
            dbLock.unlock()
        }
    }

