    // ========================================================================
    // إحصائيات لوحة التحكم (تم تحديثها بالكامل لتكون دقيقة ومحسوبة فعلياً)
    // ========================================================================

    /**
     * الحصول على إحصائيات لوحة التحكم للمحطة المحددة.
     * جميع القيم محسوبة باستعلامات SQL حقيقية وتراعي station_id.
     * @param stationId معرف المحطة (افتراضي 1)
     * @return JSONObject يحتوي على جميع الإحصائيات المطلوبة
     */
    private fun getSalesAmountBetween(stationId: Int, fromDate: String, toDate: String): Double {
        readableDatabase.rawQuery(
            "SELECT COALESCE(SUM(net_amount),0) FROM sales_transactions WHERE station_id=? AND date(created_at) BETWEEN date(?) AND date(?) AND is_deleted=0",
            arrayOf(stationId.toString(), fromDate, toDate)
        ).use { cursor -> return if (cursor.moveToFirst()) cursor.getDouble(0) else 0.0 }
    }

    private fun parseDateOnlyStrict(value: String): Date? {
        return try {
            SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { isLenient = false }.parse(value)
        } catch (_: Exception) { null }
    }

    private fun shiftDate(dateText: String, days: Int): String {
        val parsed = parseDateOnlyStrict(dateText) ?: error("تاريخ غير صالح: $dateText")
        val calendar = Calendar.getInstance().apply { time = parsed }
        calendar.add(Calendar.DAY_OF_YEAR, days)
        return SimpleDateFormat("yyyy-MM-dd", Locale.US).format(calendar.time)
    }

    fun getDashboardStats(stationId: Int, params: JSONObject = JSONObject()): JSONObject {
        val stats = JSONObject()
        val db = readableDatabase

        // 1. إجمالي المنتجات النشطة في المحطة
        db.rawQuery(
            "SELECT COUNT(*) FROM products WHERE station_id = ? AND is_deleted = 0 AND status = 'active'",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("total_products", cursor.getInt(0))
        }

        // 2. المبيعات اليومية (صافي المبلغ)
        db.rawQuery(
            "SELECT COALESCE(SUM(net_amount),0) FROM sales_transactions WHERE station_id=? AND date(created_at)=date('now') AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("daily_sales", cursor.getDouble(0))
        }

        // 3. العملاء النشطون في المحطة (من خلال المبيعات)
        db.rawQuery(
            "SELECT COUNT(DISTINCT p.id) FROM parties p " +
                    "JOIN sales_transactions s ON s.customer_party_id = p.id " +
                    "WHERE s.station_id = ? AND p.is_active = 1 AND p.is_deleted = 0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("active_customers", cursor.getInt(0))
        }

        // 4. المنتجات المنتهية قريباً (خلال 30 يوم) في المحطة
        db.rawQuery(
            "SELECT COUNT(*) FROM products WHERE station_id = ? AND has_expiry=1 AND expiry_date BETWEEN date('now') AND date('now', '+30 days') AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("expiry_soon", cursor.getInt(0))
        }

        // 5. المنتجات منخفضة المخزون في المحطة
        db.rawQuery(
            """
            SELECT COUNT(*) FROM products p
            LEFT JOIN inventory_levels il ON p.id = il.product_id
            LEFT JOIN warehouses w ON il.warehouse_id = w.id
            WHERE p.station_id = ? AND p.is_deleted=0 AND p.status='active'
            AND (il.quantity_on_hand <= p.minimum_stock OR il.quantity_on_hand IS NULL)
            AND (w.station_id = ? OR w.station_id IS NULL)
            """.trimIndent(),
            arrayOf(stationId.toString(), stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("low_stock", cursor.getInt(0))
        }

        // 6. الفواتير المستحقة (خلال أسبوع) في المحطة
        db.rawQuery(
            """SELECT COUNT(*) FROM sales_transactions
               WHERE station_id=? AND remaining_amount > 0
               AND date(due_date) BETWEEN date('now') AND date('now', '+7 days')
               AND is_deleted=0""",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("due_invoices", cursor.getInt(0))
        }

        // 7. كمية المنتجات المرتجعة اليوم في المحطة
        db.rawQuery(
            """SELECT COALESCE(SUM(quantity_change),0) FROM inventory_movements
               WHERE station_id=? AND movement_type='return' AND date(created_at)=date('now') AND is_deleted=0""",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("returned_products_today", cursor.getDouble(0))
        }

        // 8. كمية المنتجات التالفة اليوم في المحطة (مع station_id)
        db.rawQuery(
            "SELECT COALESCE(SUM(quantity),0) FROM damaged_products WHERE station_id=? AND date(report_date)=date('now') AND status='approved'",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("damaged_products_today", cursor.getDouble(0))
        }

        // 9. مديونية العملاء (المبالغ المتبقية للفواتير الآجلة) في المحطة
        db.rawQuery(
            "SELECT COALESCE(SUM(remaining_amount),0) FROM sales_transactions WHERE station_id=? AND is_credit=1 AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("customer_debts", cursor.getDouble(0))
        }

        // 10. مديونية الموردين المرتبطين بالمحطة (من خلال عمليات التعبئة)
        db.rawQuery(
            "SELECT COALESCE(SUM(p.current_balance),0) FROM parties p " +
                    "JOIN tank_refills tr ON tr.supplier_id = p.id " +
                    "WHERE tr.station_id = ? AND p.party_type_id IN (SELECT id FROM party_types WHERE type_code = 'SUPPLIER' AND is_deleted=0) AND p.is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("supplier_debts", cursor.getDouble(0))
        }

        // 11. قيمة المخزون في المحطة (من خلال المنتجات والمستودعات)
        db.rawQuery(
            """
            SELECT COALESCE(SUM(il.quantity_on_hand * p.purchase_price),0)
            FROM inventory_levels il
            JOIN products p ON il.product_id = p.id
            JOIN warehouses w ON il.warehouse_id = w.id
            WHERE p.station_id = ? AND w.station_id = ? AND p.is_deleted=0
            """.trimIndent(),
            arrayOf(stationId.toString(), stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("inventory_value", cursor.getDouble(0))
        }

        // 12. المهام المعلقة من جدول tasks الفعلي
        db.rawQuery(
            "SELECT COUNT(*) FROM tasks WHERE is_deleted=0 AND is_archived=0 AND is_resolved=0",
            null
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("pending_tasks", cursor.getInt(0))
        }

        // 13. حساب اتجاه المبيعات من فترتين متكافئتين فعليتين في SQLite
        val today = getCurrentDate()
        val requestedFrom = params.optString("from_date", "").trim()
        val requestedTo = params.optString("to_date", "").trim()
        val currentEnd = if (requestedTo.isNotBlank()) requestedTo else today
        val currentStart = if (requestedFrom.isNotBlank()) requestedFrom else currentEnd
        val currentStartDate = parseDateOnlyStrict(currentStart) ?: error("تاريخ بداية غير صالح: $currentStart")
        val currentEndDate = parseDateOnlyStrict(currentEnd) ?: error("تاريخ نهاية غير صالح: $currentEnd")
        require(!currentStartDate.after(currentEndDate)) { "تاريخ البداية يجب أن يسبق أو يساوي تاريخ النهاية" }
        val periodDays = (((currentEndDate.time - currentStartDate.time) / 86400000L).toInt() + 1).coerceAtLeast(1)
        val previousEnd = shiftDate(currentStart, -1)
        val previousStart = shiftDate(previousEnd, -(periodDays - 1))
        val todaySales = getSalesAmountBetween(stationId, currentStart, currentEnd)
        val yesterdaySales = getSalesAmountBetween(stationId, previousStart, previousEnd)
        val salesTrendObj = JSONObject().apply {
            put("current_period", todaySales)
            put("previous_period", yesterdaySales)
            put("difference", todaySales - yesterdaySales)
            if (yesterdaySales > 0) {
                val percent = ((todaySales - yesterdaySales) / yesterdaySales) * 100
                put("percentage_change", Math.round(percent * 100.0) / 100.0)
                put("trend_direction", if (percent > 0) "up" else if (percent < 0) "down" else "neutral")
            } else {
                put("percentage_change", JSONObject.NULL)
                put("trend_direction", if (todaySales > 0) "up" else "neutral")
            }
            put("current_from", currentStart)
            put("current_to", currentEnd)
            put("previous_from", previousStart)
            put("previous_to", previousEnd)
            put("trend_label", "مقارنة بالفترة السابقة المكافئة")
        }
        stats.put("sales_trend_data", salesTrendObj)
        // للحفاظ على التوافق القديم مؤقتاً
        stats.put("sales_trend", if (salesTrendObj.isNull("percentage_change")) "غير متاح" else if (salesTrendObj.getDouble("percentage_change") > 0) "+${salesTrendObj.getDouble("percentage_change")}%" else "${salesTrendObj.getDouble("percentage_change")}%")

        // 14. اتجاه عدد المنتجات: لقطة حالية وسابقة عند نهايتي الفترتين المتكافئتين
        val currentProducts = getActiveProductsCountAtDate(stationId, currentEnd)
        val previousProducts = getActiveProductsCountAtDate(stationId, previousEnd)
        val productsTrendObj = JSONObject().apply {
            put("current_period", currentProducts)
            put("previous_period", previousProducts)
            put("difference", currentProducts - previousProducts)
            if (previousProducts > 0) {
                val percent = ((currentProducts - previousProducts).toDouble() / previousProducts) * 100
                put("percentage_change", Math.round(percent * 100.0) / 100.0)
                put("trend_direction", if (percent > 0) "up" else if (percent < 0) "down" else "neutral")
            } else {
                put("percentage_change", JSONObject.NULL)
                put("trend_direction", if (currentProducts > 0) "up" else "neutral")
            }
            put("current_from", currentStart)
            put("current_to", currentEnd)
            put("previous_from", previousStart)
            put("previous_to", previousEnd)
            put("trend_label", "مقارنة بالفترة السابقة المكافئة")
        }
        stats.put("products_trend_data", productsTrendObj)
        // للحفاظ على التوافق القديم مؤقتاً
        stats.put("products_trend", if (productsTrendObj.isNull("percentage_change")) "غير متاح" else if (productsTrendObj.getDouble("percentage_change") > 0) "+${productsTrendObj.getDouble("percentage_change")}%" else "${productsTrendObj.getDouble("percentage_change")}%")

        // الاحتفاظ بالمفاتيح القديمة لتوافق مع أي كود آخر (مع تحديثها لتراعي المحطة)
        // إجمالي المبيعات والليترات وعدد المعاملات اليوم
        db.rawQuery(
            "SELECT COALESCE(SUM(net_amount),0), COALESCE(SUM(liters),0), COUNT(*) FROM sales_transactions WHERE station_id=? AND date(created_at) = date('now') AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                stats.put("total_sales", cursor.getDouble(0))
                stats.put("total_liters", cursor.getDouble(1))
                stats.put("transactions_today", cursor.getInt(2))
            }
        }

        // إجمالي الكمية المتبقية في الخزانات للمحطة
        db.rawQuery(
            "SELECT COALESCE(SUM(current_quantity),0) FROM tanks WHERE station_id=? AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("total_remaining", cursor.getDouble(0))
        }

        // إجمالي المبالغ المستحقة (للعملاء) في المحطة
        db.rawQuery(
            "SELECT COALESCE(SUM(remaining_amount),0) FROM sales_transactions WHERE station_id=? AND payment_status IN ('pending','partial') AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) stats.put("total_due", cursor.getDouble(0))
        }

        // إجمالي العملاء (جميع العملاء في المحطة)
        db.rawQuery(
            "SELECT COUNT(DISTINCT p.id) FROM parties p JOIN sales_transactions s ON s.customer_party_id = p.id WHERE s.station_id=? AND p.is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                val totalCustomers = cursor.getInt(0)
                stats.put("total_customers", totalCustomers)

                // اتجاه العملاء: عدد العملاء الفريدين داخل كل فترة متكافئة
                val currentCustomers = getCustomersCountBetween(stationId, currentStart, currentEnd)
                val previousCustomers = getCustomersCountBetween(stationId, previousStart, previousEnd)
                val customersTrendObj = JSONObject().apply {
                    put("current_period", currentCustomers)
                    put("previous_period", previousCustomers)
                    put("difference", currentCustomers - previousCustomers)
                    if (previousCustomers > 0) {
                        val percent = ((currentCustomers - previousCustomers).toDouble() / previousCustomers) * 100
                        put("percentage_change", Math.round(percent * 100.0) / 100.0)
                        put("trend_direction", if (percent > 0) "up" else if (percent < 0) "down" else "neutral")
                    } else {
                        put("percentage_change", JSONObject.NULL)
                        put("trend_direction", if (currentCustomers > 0) "up" else "neutral")
                    }
                    put("current_from", currentStart)
                    put("current_to", currentEnd)
                    put("previous_from", previousStart)
                    put("previous_to", previousEnd)
                    put("trend_label", "مقارنة بالفترة السابقة المكافئة")
                }
                stats.put("customers_trend_data", customersTrendObj)
            }
        }

        // عدد ومبلغ الفواتير المتأخرة في المحطة
        db.rawQuery(
            "SELECT COUNT(*), COALESCE(SUM(remaining_amount),0) FROM sales_transactions WHERE station_id=? AND is_credit=1 AND date(due_date) < date('now') AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                stats.put("overdue_count", cursor.getInt(0))
                stats.put("overdue_amount", cursor.getDouble(1))
            }
        }

        // نسبة امتلاء خزانات المحطة — تُحسب من الكمية الحالية والسعة الفعلية في SQLite.
        // نحتفظ بالمفتاح occupancy_rate للتوافق مع الشاشات القديمة، مع إضافة مفاتيح صريحة جديدة.
        db.rawQuery(
            "SELECT COALESCE(SUM(current_quantity), 0), COALESCE(SUM(capacity_liters), 0), COUNT(*) FROM tanks WHERE station_id=? AND is_deleted=0",
            arrayOf(stationId.toString())
        ).use { cursor ->
            if (cursor.moveToFirst()) {
                val currentTankQuantity = cursor.getDouble(0)
                val totalTankCapacity = cursor.getDouble(1)
                val tankCount = cursor.getInt(2)
                val fillRate = if (totalTankCapacity > 0.0) {
                    ((currentTankQuantity / totalTankCapacity) * 100.0).coerceIn(0.0, 100.0)
                } else {
                    0.0
                }
                stats.put("total_tank_quantity", currentTankQuantity)
                stats.put("total_tank_capacity", totalTankCapacity)
                stats.put("tank_count", tankCount)
                stats.put("occupancy_rate", Math.round(fillRate * 100.0) / 100.0)
                stats.put("occupancy_rate_source", "tanks.current_quantity/tanks.capacity_liters")
            }
        }

        return stats
    }

    /**
     * يقوم بتجميع حالة صحة مزودي الذكاء الاصطناعي بناءً على السجلات الفعلية في جدول sms_ai_runs
     */
    fun getAiHealthStatusQuery(): JSONObject {
        val result = JSONObject()
        val arr = JSONArray()
        val db = readableDatabase

        var availableCount = 0
        var totalCooldowns = 0

        // جلب جميع المزودين الفريدين مع إحصائياتهم
        val query = """
            SELECT
                provider,
                MAX(model) as model,
                COUNT(*) as total_runs,
                SUM(CASE WHEN error_type IS NULL AND fallback_reason IS NULL THEN 1 ELSE 0 END) as success_count,
                SUM(CASE WHEN error_type IS NOT NULL OR fallback_reason IS NOT NULL THEN 1 ELSE 0 END) as failure_count,
                MAX(created_at) as last_run_time
            FROM sms_ai_runs
            GROUP BY provider
        """.trimIndent()

        db.rawQuery(query, null).use { cursor ->
            while (cursor.moveToNext()) {
                val provider = cursor.getString(0) ?: "unknown"
                val model = cursor.getString(1) ?: "unknown"
                val totalRuns = cursor.getInt(2)
                val successCount = cursor.getInt(3)
                val failureCount = cursor.getInt(4)

                // حساب الصحة (Circuit Breaker logic)
                val isCooldown = failureCount > 3 && successCount == 0 // نفس منطق Orchestrator
                val healthScore = if (totalRuns == 0) 0.5 else successCount.toDouble() / totalRuns.toDouble()

                if (!isCooldown) availableCount++
                if (isCooldown) totalCooldowns++

                arr.put(JSONObject().apply {
                    put("id", provider) // نستخدم provider كـ id مؤقت
                    put("provider", provider)
                    put("model", model)
                    put("enabled", true) // نفترض أنه مفعل إذا كان له سجلات
                    put("is_cooldown", isCooldown)
                    put("health_score", healthScore)
                    put("failures", failureCount)
                    put("successes", successCount)
                })
            }
        }

        result.put("providers", arr)
        result.put("available_count", availableCount)
        result.put("cooldown_count", totalCooldowns)
        result.put("system_status", if (availableCount > 0) "HEALTHY" else "DEGRADED")

        return result
    }

