    fun logActivity(operator: String, action: String, description: String, stationId: Int = 0, userId: Long = 0L, targetTable: String = "", targetId: Long = 0L): Long {
        dbLock.lock()
        return try {
            val db = writableDatabase
            val cv = ContentValues().apply {
                put("uuid", UUID.randomUUID().toString())
                put("user_id", if (userId > 0L) userId else 0L)
                put("action", action)
                put("description", description)
                if (stationId > 0) put("station_id", stationId)
                if (targetTable.isNotEmpty()) put("target_table", targetTable)
                if (targetId > 0L) put("target_id", targetId)
                put("created_at", getCurrentDateTime())
            }
            db.insert("user_activity_log", null, cv)
        } finally {
            dbLock.unlock()
        }
    }

