            "invoice_templates" -> OperationalTableSpec(
                table = "invoice_templates",
                columns = listOf("template_code", "template_name", "description", "station_id", "template_html", "template_css", "variables", "is_default", "is_active", "created_by"),
                required = listOf("template_code", "template_name"),
                searchColumns = listOf("template_code", "template_name", "description"),
                softDeleted = false,
                hasUpdatedAt = true,
                hasStatus = true,
                numericColumns = listOf("station_id")
            )
            else -> null
        }

    private fun putOperationalValue(values: ContentValues, key: String, value: Any?) {
        if (value == null || value == JSONObject.NULL) return
        when (value) {
            is Boolean -> values.put(key, if (value) 1 else 0)
            is Int -> values.put(key, value)
            is Long -> values.put(key, value)
            is Double -> values.put(key, value)
            is Float -> values.put(key, value)
            is Number -> values.put(key, value.toDouble())
            else -> values.put(key, value.toString())
        }
    }

    private fun operationalHasUuid(table: String): Boolean = table !in setOf("bad_debts", "price_history", "stocktakes", "stocktake_details", "cash_deposits", "employee_payments", "depreciation")

    private fun operationalHasCreatedAt(table: String): Boolean = table !in setOf("bad_debts", "price_history", "price_list_items", "stocktakes", "stocktake_details", "cash_deposits", "employee_payments", "depreciation")

    private fun parseAttendanceDate(value: String): Date? {
        val text = value.trim()
        if (text.isBlank()) return null
        val formats = listOf("yyyy-MM-dd'T'HH:mm:ss", "yyyy-MM-dd'T'HH:mm", "yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd")
        for (pattern in formats) {
            try {
                val position = ParsePosition(0)
                val parsed = SimpleDateFormat(pattern, Locale.US).apply { isLenient = false }.parse(text, position)
                if (parsed != null && position.index == text.length) return parsed
            } catch (_: Exception) {
                // Try the next supported SQLite/WebView date representation.
            }
        }
        return null
    }

    private fun validateAttendanceRecord(data: JSONObject, existingId: Long? = null) {
        val employeeId = data.optLong("employee_id", 0L)
        val attendanceDate = data.optString("attendance_date", "").trim()
        require(employeeId > 0L) { "الحقل employee_id مطلوب للحضور" }
        require(attendanceDate.isNotBlank() && parseAttendanceDate(attendanceDate) != null) { "تاريخ الحضور غير صالح" }
        val checkInText = data.optString("check_in", "").trim()
        val checkOutText = data.optString("check_out", "").trim()
        val checkIn = if (checkInText.isBlank()) null else parseAttendanceDate(checkInText)
        val checkOut = if (checkOutText.isBlank()) null else parseAttendanceDate(checkOutText)
        require(checkInText.isBlank() || checkIn != null) { "وقت الحضور غير صالح" }
        require(checkOutText.isBlank() || checkOut != null) { "وقت الانصراف غير صالح" }
        if (checkIn != null && checkOut != null) require(!checkOut.before(checkIn)) { "وقت الانصراف لا يمكن أن يسبق وقت الحضور" }
        val numericFields = listOf("work_hours", "overtime_hours", "late_minutes", "early_leave_minutes")
        numericFields.forEach { key ->
            val raw = if (data.has(key) && !data.isNull(key)) data.optString(key, "").trim() else ""
            if (raw.isNotBlank()) {
                val number = raw.toDoubleOrNull() ?: throw IllegalArgumentException("قيمة رقمية غير صالحة: $key")
                require(number >= 0.0) { "القيمة لا يمكن أن تكون سالبة: $key" }
            }
        }
        val workHoursRaw = if (data.has("work_hours") && !data.isNull("work_hours")) data.optString("work_hours", "").trim() else ""
        if (workHoursRaw.isNotBlank()) require(workHoursRaw.toDoubleOrNull()?.let { it <= 24.0 } == true) { "ساعات العمل لا يمكن أن تتجاوز 24 ساعة" }
        val status = data.optString("status", "").trim()
        if (status.isNotBlank()) require(status in setOf("present", "absent", "late", "early_leave", "on_leave", "holiday")) { "حالة حضور غير مدعومة" }
        val shiftId = data.optLong("shift_id", 0L)
        val args = mutableListOf(employeeId.toString(), attendanceDate)
        val shiftClause = if (shiftId > 0L) { args += shiftId.toString(); " AND shift_id = ?" } else " AND (shift_id IS NULL OR shift_id = 0)"
        val exclusion = if (existingId != null) { args += existingId.toString(); " AND id <> ?" } else ""
        readableDatabase.rawQuery("SELECT id FROM attendance WHERE employee_id = ? AND attendance_date = ?$shiftClause AND is_deleted = 0$exclusion LIMIT 1", args.toTypedArray()).use { cursor -> require(!cursor.moveToFirst()) { "يوجد سجل حضور مكرر للموظف والوردية والتاريخ نفسه" } }
    }

    private fun logEmployeeAudit(employeeId: Long, action: String, actorId: Long, oldJson: String?, newJson: String?, reason: String) {
        writableDatabase.insert("employee_audit_log", null, ContentValues().apply { put("uuid", UUID.randomUUID().toString()); put("employee_id", employeeId); put("action", action); put("reason", reason); put("old_row_json", oldJson); put("new_row_json", newJson); if (actorId > 0) put("performed_by", actorId) })
    }

    fun getOperationalRecord(screenKey: String, id: Long): JSONObject? = operationalRowJson(screenKey, id)?.let { JSONObject(it) }

    private fun operationalRowJson(screenKey: String, id: Long): String? {
        val spec = operationalSpec(screenKey) ?: return null
        readableDatabase.query(spec.table, null, "id = ?", arrayOf(id.toString()), null, null, null).use { cursor -> return if (cursor.moveToFirst()) cursorToJsonObject(cursor).toString() else null }
    }

    private fun changedOperationalColumns(oldJson: String?, newJson: String?): String {
        val old = runCatching { oldJson?.let { JSONObject(it) } }.getOrNull() ?: JSONObject()
        val new = runCatching { newJson?.let { JSONObject(it) } }.getOrNull() ?: JSONObject()
        val keys = linkedSetOf<String>(); old.keys().forEach { keys += it }; new.keys().forEach { keys += it }
        return keys.filter { key -> old.optString(key, "") != new.optString(key, "") }.joinToString(",")
    }

    private fun logOperationalAudit(screenKey: String, action: String, id: Long, actorId: Long, oldJson: String?, newJson: String?, reason: String = ""): Long {
        val description = buildString { append("$action $screenKey #$id"); if (reason.isNotBlank()) append("؛ السبب: $reason") }
        val values = ContentValues().apply {
            put("uuid", UUID.randomUUID().toString()); put("user_id", actorId); put("action", action); put("action_category", "attendance")
            put("description", description); put("description_ar", description); put("target_table", screenKey); put("target_id", id)
            put("old_row_json", oldJson); put("new_row_json", newJson); put("old_values", oldJson); put("new_values", newJson)
            put("changed_columns", changedOperationalColumns(oldJson, newJson)); put("request_id", UUID.randomUUID().toString()); put("is_success", 1); put("created_at", getCurrentDateTime())
        }
        return writableDatabase.insert("user_activity_log", null, values)
    }

    private fun operationalPreparedData(screenKey: String, input: JSONObject, actorId: Long): JSONObject {
        val data = JSONObject(input.toString())
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        fun defaultString(key: String, prefix: String) {
            if (!data.has(key) || data.optString(key).isBlank()) data.put(key, "$prefix-${System.currentTimeMillis()}")
        }
        when (screenKey) {
            "stations" -> defaultString("station_code", "ST")
            "vehicles" -> defaultString("vehicle_code", "VEH")
            "drivers" -> defaultString("driver_code", "DRV")
            "fuel_types" -> defaultString("fuel_code", "FUEL")
            "price_lists" -> defaultString("list_code", "PL")
            "tanks" -> defaultString("tank_code", "TANK")
            "tank_refills" -> defaultString("refill_code", "REFILL")
            "pumps" -> defaultString("pump_code", "PUMP")
            "meter_readings" -> defaultString("reading_code", "MR")
            "calibration_records" -> defaultString("calibration_code", "CAL")
            "maintenance_requests" -> defaultString("request_code", "MRQ")
            "maintenance_schedule" -> defaultString("schedule_code", "MS")
            "documents" -> defaultString("document_code", "DOC")
            "printer_profiles" -> defaultString("profile_code", "PRN")
            "receipt_templates", "invoice_templates" -> defaultString("template_code", "TPL")
            "payroll" -> {
                defaultString("payroll_code", "PAY")
                // Optional workflow actors must be NULL until their dedicated workflow assigns a real user.
                // Persisting an empty string or zero violates the users(id) foreign-key contract.
                listOf("calculated_by", "approved_by", "paid_by", "created_by", "updated_by", "deleted_by").forEach { key ->
                    if (data.has(key) && (data.isNull(key) || data.optString(key).trim().isEmpty() || data.optLong(key, 0L) <= 0L)) data.remove(key)
                }
            }
            "cash_boxes" -> defaultString("box_code", "BOX")
            "shifts" -> defaultString("shift_code", "SHIFT")
            "sales_transactions" -> defaultString("sale_code", "SALE")
            "payments" -> defaultString("payment_code", "PAY")
            "expenses" -> defaultString("expense_code", "EXP")
            "employees" -> defaultString("employee_code", "EMP")
            "fixed_assets" -> defaultString("asset_code", "AST")
            "price_history" -> if (!data.has("created_by") && actorId > 0) data.put("created_by", actorId)
            "vehicle_locations" -> if (data.has("location_time") && !data.isNull("location_time")) {
                val locationTime = data.optString("location_time", "").trim()
                if (locationTime.isNotBlank()) {
                    val parsed = parseAttendanceDate(locationTime) ?: throw IllegalArgumentException("التاريخ غير صالح: location_time")
                    data.put("location_time", SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.US).format(parsed))
                }
            }
        }
        if (actorId > 0) {
            if (spec.columns.contains("created_by") && (!data.has("created_by") || data.optLong("created_by", 0) <= 0)) data.put("created_by", actorId)
            if (spec.columns.contains("reported_by") && (!data.has("reported_by") || data.optLong("reported_by", 0) <= 0)) data.put("reported_by", actorId)
            if (spec.columns.contains("read_by") && (!data.has("read_by") || data.optLong("read_by", 0) <= 0)) data.put("read_by", actorId)
            if (spec.columns.contains("performed_by") && (!data.has("performed_by") || data.optLong("performed_by", 0) <= 0)) data.put("performed_by", actorId)
            if (spec.columns.contains("uploaded_by") && (!data.has("uploaded_by") || data.optLong("uploaded_by", 0) <= 0)) data.put("uploaded_by", actorId)
        }
        if (operationalHasUuid(spec.table) && !data.has("uuid")) data.put("uuid", UUID.randomUUID().toString())
        return data
    }

    private fun requireOperationalData(spec: OperationalTableSpec, data: JSONObject) {
        spec.required.forEach { key ->
            val value = if (data.has(key) && !data.isNull(key)) data.optString(key).trim() else ""
            require(value.isNotBlank() && value != "0") { "الحقل مطلوب: $key" }
        }
    }

    private fun validateFleetNumber(data: JSONObject, key: String, minimum: Double = 0.0, maximum: Double? = null) {
        if (!data.has(key) || data.isNull(key)) return
        val raw = data.optString(key, "").trim()
        val value = raw.toDoubleOrNull() ?: throw IllegalArgumentException("قيمة رقمية غير صالحة: $key")
        require(value.isFinite() && value >= minimum && (maximum == null || value <= maximum)) { "القيمة خارج النطاق أو غير صالحة: $key" }
    }
    private fun validateFleetDate(data: JSONObject, key: String) {
        if (!data.has(key) || data.isNull(key)) return
        val value = data.optString(key, "").trim()
        require(value.isNotBlank() && parseAttendanceDate(value) != null) { "التاريخ غير صالح: $key" }
    }
    private fun validateFleetRecord(screenKey: String, data: JSONObject) {
        when (screenKey) {
            "vehicles" -> listOf("year", "engine_capacity", "tank_capacity", "current_odometer", "last_odometer", "avg_consumption").forEach { validateFleetNumber(data, it) }
            "drivers" -> validateFleetNumber(data, "salary")
            "vehicle_locations" -> {
                validateFleetNumber(data, "latitude", -90.0, 90.0)
                validateFleetNumber(data, "longitude", -180.0, 180.0)
                listOf("speed", "fuel_level", "odometer", "accuracy").forEach { validateFleetNumber(data, it) }
                validateFleetNumber(data, "altitude", -Double.MAX_VALUE)
                validateFleetDate(data, "location_time")
            }
            "vehicle_trips" -> {
                listOf("distance_km", "fuel_consumed", "fuel_cost", "start_odometer", "end_odometer").forEach { validateFleetNumber(data, it) }
                validateFleetDate(data, "trip_date")
                if (data.has("start_odometer") && data.has("end_odometer") && !data.isNull("start_odometer") && !data.isNull("end_odometer")) {
                    val start = data.optString("start_odometer", "").trim().toDoubleOrNull()
                    val end = data.optString("end_odometer", "").trim().toDoubleOrNull()
                    require(start != null && end != null && end >= start) { "عداد نهاية الرحلة لا يمكن أن يسبق عداد بدايتها" }
                }
            }
            "vehicle_expenses" -> {
                validateFleetNumber(data, "amount", Double.MIN_VALUE)
                validateFleetNumber(data, "odometer_reading")
                validateFleetDate(data, "expense_date")
            }
            "vehicle_maintenance" -> {
                listOf("cost", "odometer_at_maintenance", "next_due_odometer").forEach { validateFleetNumber(data, it) }
                validateFleetDate(data, "maintenance_date")
                validateFleetDate(data, "next_due_date")
                val maintenanceDate = data.optString("maintenance_date", "").trim()
                val nextDueDate = data.optString("next_due_date", "").trim()
                if (maintenanceDate.isNotBlank() && nextDueDate.isNotBlank()) require(nextDueDate >= maintenanceDate) { "موعد الصيانة القادمة لا يمكن أن يسبق تاريخ الصيانة" }
                if (data.has("odometer_at_maintenance") && data.has("next_due_odometer") && !data.isNull("odometer_at_maintenance") && !data.isNull("next_due_odometer")) {
                    val current = data.optString("odometer_at_maintenance", "").trim().toDoubleOrNull()
                    val next = data.optString("next_due_odometer", "").trim().toDoubleOrNull()
                    require(current != null && next != null && next >= current) { "عداد الصيانة القادمة لا يمكن أن يسبق عداد الصيانة الحالية" }
                }
            }
            "vehicle_insurance" -> {
                validateFleetNumber(data, "premium")
                validateFleetDate(data, "start_date")
                validateFleetDate(data, "end_date")
                if (data.has("is_active") && !data.isNull("is_active")) {
                    val active = data.optInt("is_active", -1)
                    require(active == 0 || active == 1) { "حالة التأمين يجب أن تكون 0 أو 1" }
                }
                val startDate = data.optString("start_date", "").trim()
                val endDate = data.optString("end_date", "").trim()
                if (startDate.isNotBlank() && endDate.isNotBlank()) require(endDate >= startDate) { "نهاية التأمين لا يمكن أن تسبق بدايته" }
            }
        }
    }
    private fun validateModule006Record(screenKey: String, data: JSONObject, db: SQLiteDatabase? = null, stationId: Int = data.optInt("station_id", 0)) {
        fun number(key: String, minimum: Double = 0.0, maximum: Double? = null): Double? {
            if (!data.has(key) || data.isNull(key)) return null
            val value = data.optString(key, "").trim().toDoubleOrNull() ?: throw IllegalArgumentException("قيمة رقمية غير صالحة: $key")
            require(value.isFinite() && value >= minimum && (maximum == null || value <= maximum)) { "القيمة خارج النطاق: $key" }
            return value
        }
        fun date(key: String) { if (data.has(key) && !data.isNull(key)) require(parseAttendanceDate(data.optString(key).trim()) != null) { "التاريخ غير صالح: $key" } }
        when (screenKey) {
            "tanks" -> {
                val capacity = number("capacity_liters")
                val minimum = number("minimum_level")
                val maximum = number("maximum_level")
                val current = number("current_quantity")
                require(capacity == null || capacity > 0.0) { "سعة الخزان يجب أن تكون أكبر من صفر" }
                require(maximum == null || capacity == null || maximum <= capacity) { "الحد الأعلى يتجاوز سعة الخزان" }
                require(minimum == null || maximum == null || maximum >= minimum) { "الحد الأعلى أقل من الحد الأدنى" }
                require(current == null || capacity == null || current <= capacity) { "كمية الخزان تتجاوز السعة" }
                listOf("usable_capacity", "dead_volume").forEach { number(it) }
                date("installation_date"); date("sensor_calibration_date"); date("last_inspection_date"); date("next_inspection_date")
            }
            "pumps" -> {
                listOf("max_flow_rate", "meter_start", "meter_current", "maintenance_interval").forEach { number(it) }
                val start = number("meter_start")
                val current = number("meter_current")
                require(start == null || current == null || current >= start) { "قراءة المضخة الحالية أقل من البداية" }
                date("installation_date"); date("last_maintenance"); date("next_maintenance")
            }
            "meter_readings" -> {
                val opening = number("opening_reading")
                val closing = number("closing_reading")
                val sold = number("sold_liters")
                require(opening == null || closing == null || closing >= opening) { "القراءة الختامية أقل من الافتتاحية" }
                require(opening == null || closing == null || sold == null || kotlin.math.abs((closing - opening) - sold) < 0.01) { "كمية البيع لا تطابق فرق القراءات" }
                listOf("system_sold_liters", "difference", "difference_percent", "tolerance_limit", "adjustment_amount").forEach { number(it) }
                date("reading_date")
                val period = data.optString("period", "").trim()
                if (period.isNotEmpty()) require(period in setOf("morning", "evening", "night", "daily")) { "الفترة غير صالحة" }
                val status = data.optString("status", "").trim()
                if (status.isNotEmpty()) require(status in setOf("draft", "verified", "approved", "rejected")) { "حالة القراءة غير صالحة" }
            }
            "tank_refills" -> {
                val delivered = number("delivered_quantity")
                val actual = number("actual_quantity")
                listOf("ordered_quantity", "quantity_difference", "tank_level_before", "tank_level_after", "fuel_density", "fuel_temperature", "unit_price", "total_amount", "transport_cost", "discount", "tax_amount", "net_amount").forEach { number(it) }
                require(delivered != null && delivered > 0.0) { "كمية التعبئة يجب أن تكون أكبر من صفر" }
                require(actual == null || actual > 0.0) { "الكمية الفعلية يجب أن تكون أكبر من صفر" }
                val status = data.optString("status", "").trim()
                if (status.isNotEmpty()) require(status in setOf("pending", "in_progress", "completed", "rejected", "cancelled")) { "حالة التعبئة غير صالحة" }
                date("order_date"); date("expected_date"); date("arrival_date")
            }
            "tank_level_log" -> {
                listOf("opening_level", "closing_level", "measured_level", "calculated_level", "difference", "fuel_temperature", "fuel_density", "volume_at_15c", "refills_total", "sales_total", "evaporation_loss").forEach { number(it) }
                date("reading_date")
            }
            "fuel_quality_tests" -> {
                listOf("density", "temperature", "water_content", "sulfur_content", "viscosity", "flash_point", "cetane_number").forEach { number(it) }
                val result = data.optString("result", "").trim()
                if (result.isNotEmpty()) require(result in setOf("pass", "fail", "warning")) { "نتيجة الفحص غير صالحة" }
                date("test_date")
            }
            "calibration_records" -> {
                listOf("before_value", "after_value", "error_value", "correction_percent", "calibration_factor").forEach { number(it) }
                date("calibration_date"); date("next_calibration_date")
                val status = data.optString("status", "").trim()
                if (status.isNotEmpty()) require(status in setOf("scheduled", "in_progress", "completed", "failed")) { "حالة المعايرة غير صالحة" }
            }
        }
    }

    private fun requireTankFuelMatch(db: SQLiteDatabase, tankId: Long, fuelTypeId: Long, stationId: Int): JSONObject {
        require(tankId > 0L && fuelTypeId > 0L && stationId > 0) { "الخزان ونوع الوقود والمحطة مطلوبة" }
        val tank = db.rawQuery("SELECT id, fuel_type_id, current_quantity, capacity_liters FROM tanks WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(tankId.toString(), stationId.toString())).use { cursor ->
            require(cursor.moveToFirst()) { "الخزان غير موجود ضمن محطة المستخدم" }
            JSONObject().apply { put("id", cursor.getLong(0)); put("fuel_type_id", cursor.getLong(1)); put("current_quantity", cursor.getDouble(2)); put("capacity_liters", cursor.getDouble(3)) }
        }
        require(tank.optLong("fuel_type_id") == fuelTypeId) { "نوع الوقود لا يطابق نوع وقود الخزان" }
        return tank
    }

    fun saveTankRefillRecord(input: JSONObject, stationScopeId: Int, actorId: Long): Long {
        require(stationScopeId > 0 && actorId > 0L) { "المحطة والمستخدم مطلوبان" }
        dbLock.lock()
        return try {
            val db = writableDatabase
            val data = operationalPreparedData("tank_refills", input, actorId).apply { put("station_id", stationScopeId); put("created_by", actorId); put("received_by", actorId) }
            requireOperationalData(operationalSpec("tank_refills")!!, data)
            validateModule006Record("tank_refills", data, db, stationScopeId)
            val tank = requireTankFuelMatch(db, data.optLong("tank_id"), data.optLong("fuel_type_id"), stationScopeId)
            val added = if (data.has("actual_quantity") && !data.isNull("actual_quantity")) data.optDouble("actual_quantity") else data.optDouble("delivered_quantity")
            require(added.isFinite() && added > 0.0) { "كمية التعبئة غير صالحة" }
            val before = tank.optDouble("current_quantity")
            val status = data.optString("status", "completed").ifBlank { "completed" }
            val applied = if (status == "completed") added else 0.0
            val after = before + applied
            require(after <= tank.optDouble("capacity_liters")) { "التعبئة تتجاوز سعة الخزان" }
            data.put("tank_level_before", before); data.put("tank_level_after", after); data.put("actual_quantity", added); data.put("quantity_difference", added - data.optDouble("delivered_quantity")); data.put("status", status)
            val values = ContentValues()
            for (key in operationalSpec("tank_refills")!!.columns) if (data.has(key)) putOperationalValue(values, key, data.opt(key))
            putOperationalValue(values, "uuid", data.optString("uuid")); values.put("created_at", getCurrentDateTime()); values.put("updated_at", getCurrentDateTime())
            db.beginTransaction()
            try {
                val id = db.insertOrThrow("tank_refills", null, values)
                val updated = db.update("tanks", ContentValues().apply { put("current_quantity", after); put("updated_at", getCurrentDateTime()) }, "id=? AND station_id=? AND is_deleted=0", arrayOf(data.optLong("tank_id").toString(), stationScopeId.toString()))
                require(updated == 1) { "تعذر تحديث كمية الخزان" }
                db.setTransactionSuccessful()
                id
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun updateTankRefillRecord(id: Long, input: JSONObject, stationScopeId: Int, actorId: Long): Int {
        require(id > 0L && stationScopeId > 0 && actorId > 0L) { "بيانات تحديث التعبئة غير صالحة" }
        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
                val old = db.rawQuery("SELECT tank_id, fuel_type_id, actual_quantity, delivered_quantity, status FROM tank_refills WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "سجل التعبئة غير موجود ضمن المحطة" }; JSONObject().apply { put("tank_id", cursor.getLong(0)); put("fuel_type_id", cursor.getLong(1)); put("actual_quantity", cursor.getDouble(2)); put("delivered_quantity", cursor.getDouble(3)); put("status", cursor.getString(4)) } }
                val data = JSONObject(input.toString()).apply {
                    put("station_id", stationScopeId)
                    put("tank_id", optLong("tank_id", old.optLong("tank_id")))
                    put("fuel_type_id", optLong("fuel_type_id", old.optLong("fuel_type_id")))
                    put("actual_quantity", if (has("actual_quantity")) optDouble("actual_quantity") else old.optDouble("actual_quantity"))
                    put("delivered_quantity", if (has("delivered_quantity")) optDouble("delivered_quantity") else old.optDouble("delivered_quantity"))
                    put("status", optString("status", old.optString("status", "completed")).ifBlank { old.optString("status", "completed") })
                }
                validateModule006Record("tank_refills", data, db, stationScopeId)
                val tank = requireTankFuelMatch(db, data.optLong("tank_id"), data.optLong("fuel_type_id"), stationScopeId)
                val oldApplied = if (old.optString("status") == "completed") old.optDouble("actual_quantity") else 0.0
                val newQty = data.optDouble("actual_quantity")
                val newApplied = if (data.optString("status") == "completed") newQty else 0.0
                val after = tank.optDouble("current_quantity") - oldApplied + newApplied
                require(after >= 0.0 && after <= tank.optDouble("capacity_liters")) { "كمية الخزان الناتجة خارج النطاق" }
                data.put("tank_level_before", after - newApplied); data.put("tank_level_after", after); data.put("quantity_difference", newQty - data.optDouble("delivered_quantity")); data.put("updated_by", actorId)
                val values = ContentValues()
                for (key in operationalSpec("tank_refills")!!.columns) if (data.has(key)) putOperationalValue(values, key, data.opt(key))
                values.put("updated_at", getCurrentDateTime())
                val rows = db.update("tank_refills", values, "id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), stationScopeId.toString()))
                require(rows == 1) { "تعذر تحديث سجل التعبئة" }
                require(db.update("tanks", ContentValues().apply { put("current_quantity", after); put("updated_at", getCurrentDateTime()) }, "id=? AND station_id=? AND is_deleted=0", arrayOf(data.optLong("tank_id").toString(), stationScopeId.toString())) == 1) { "تعذر تحديث كمية الخزان" }
                db.setTransactionSuccessful(); rows
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun deleteTankRefillRecord(id: Long, stationScopeId: Int): Int {
        require(id > 0L && stationScopeId > 0) { "بيانات حذف التعبئة غير صالحة" }
        dbLock.lock()
        return try {
            val db = writableDatabase
            db.beginTransaction()
            try {
                val old = db.rawQuery("SELECT tank_id, actual_quantity, status FROM tank_refills WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "سجل التعبئة غير موجود ضمن المحطة" }; arrayOf(cursor.getLong(0), java.lang.Double.doubleToRawLongBits(cursor.getDouble(1)), cursor.getString(2)) }
                val tankId = old[0] as Long; val qty = if ((old[2] as String) == "completed") java.lang.Double.longBitsToDouble(old[1] as Long) else 0.0
                val current = db.rawQuery("SELECT current_quantity FROM tanks WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(tankId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الخزان غير موجود ضمن المحطة" }; cursor.getDouble(0) }
                require(current >= qty) { "لا يمكن عكس التعبئة لأن كمية الخزان الحالية أقل من الكمية المسجلة" }
                require(db.update("tanks", ContentValues().apply { put("current_quantity", current - qty); put("updated_at", getCurrentDateTime()) }, "id=? AND station_id=? AND is_deleted=0", arrayOf(tankId.toString(), stationScopeId.toString())) == 1) { "تعذر عكس كمية الخزان" }
                val rows = db.update("tank_refills", ContentValues().apply { put("is_deleted", 1); put("deleted_at", getCurrentDateTime()) }, "id=? AND station_id=? AND is_deleted=0", arrayOf(id.toString(), stationScopeId.toString()))
                db.setTransactionSuccessful(); rows
            } finally { db.endTransaction() }
        } finally { dbLock.unlock() }
    }

    private fun requireModule006RelationsInStation(db: SQLiteDatabase, screenKey: String, data: JSONObject, stationId: Int) {
        require(stationId > 0) { "معرف المحطة مطلوب" }
        when (screenKey) {
            "tanks" -> if (data.has("fuel_type_id")) db.rawQuery("SELECT 1 FROM fuel_types WHERE id=? AND is_deleted=0", arrayOf(data.optLong("fuel_type_id").toString())).use { cursor -> require(cursor.moveToFirst()) { "نوع الوقود غير موجود" } }
            "pumps" -> if (data.has("tank_id")) db.rawQuery("SELECT 1 FROM tanks WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(data.optLong("tank_id").toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الخزان خارج نطاق المحطة" } }
            "meter_readings" -> {
                val pumpId = data.optLong("pump_id", 0L)
                val nozzleId = data.optLong("nozzle_id", 0L)
                if (pumpId > 0L && nozzleId > 0L) {
                    db.rawQuery("SELECT 1 FROM pump_nozzles n JOIN pumps p ON p.id=n.pump_id WHERE n.id=? AND n.pump_id=? AND p.station_id=? AND n.is_deleted=0 AND p.is_deleted=0", arrayOf(nozzleId.toString(), pumpId.toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الفوهة لا تتبع المضخة المحددة أو خارج نطاق المحطة" } }
                } else if (pumpId > 0L) {
                    db.rawQuery("SELECT 1 FROM pumps WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(pumpId.toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المضخة خارج نطاق المحطة" } }
                } else if (nozzleId > 0L) {
                    db.rawQuery("SELECT 1 FROM pump_nozzles n JOIN pumps p ON p.id=n.pump_id WHERE n.id=? AND p.station_id=? AND n.is_deleted=0 AND p.is_deleted=0", arrayOf(nozzleId.toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الفوهة خارج نطاق المحطة" } }
                }
            }
            "tank_level_log" -> if (data.has("tank_id")) db.rawQuery("SELECT 1 FROM tanks WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(data.optLong("tank_id").toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الخزان خارج نطاق المحطة" } }
            "fuel_quality_tests" -> if (data.has("refill_id")) db.rawQuery("SELECT 1 FROM tank_refills WHERE id=? AND station_id=? AND is_deleted=0", arrayOf(data.optLong("refill_id").toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "عملية التعبئة خارج نطاق المحطة" } }
        }
    }

    private fun requireCalibrationEntityInStation(db: SQLiteDatabase, data: JSONObject, stationId: Int, existingId: Long? = null) {
        require(stationId > 0) { "معرف المحطة مطلوب لسجل المعايرة" }
        var entityType = data.optString("entity_type", "").trim().lowercase(Locale.US)
        var entityId = data.optLong("entity_id", 0L)
        if ((entityType.isBlank() || entityId <= 0L) && existingId != null) {
            db.rawQuery("SELECT entity_type, entity_id FROM calibration_records WHERE id = ? AND station_id = ?", arrayOf(existingId.toString(), stationId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "سجل المعايرة خارج نطاق المحطة" }
                if (entityType.isBlank()) entityType = cursor.getString(0).trim().lowercase(Locale.US)
                if (entityId <= 0L) entityId = cursor.getLong(1)
            }
        }
        require(entityId > 0L) { "معرف الكيان مطلوب لسجل المعايرة" }
        val targetExists = when (entityType) {
            "tank", "tanks" -> db.rawQuery("SELECT id FROM tanks WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(entityId.toString(), stationId.toString())).use { it.moveToFirst() }
            "pump", "pumps" -> db.rawQuery("SELECT id FROM pumps WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(entityId.toString(), stationId.toString())).use { it.moveToFirst() }
            "nozzle", "nozzles", "pump_nozzle", "pump_nozzles" -> db.rawQuery("SELECT n.id FROM pump_nozzles n JOIN pumps p ON p.id = n.pump_id WHERE n.id = ? AND p.station_id = ? AND n.is_deleted = 0 AND p.is_deleted = 0", arrayOf(entityId.toString(), stationId.toString())).use { it.moveToFirst() }
            else -> false
        }
        require(targetExists) { "كيان المعايرة غير موجود أو خارج نطاق المحطة" }
    }

    private fun calibrationStationPredicate(stationId: Int): String = "station_id = ${stationId} AND (EXISTS (SELECT 1 FROM tanks scope_ct WHERE lower(calibration_records.entity_type) IN ('tank', 'tanks') AND scope_ct.id = calibration_records.entity_id AND scope_ct.station_id = ${stationId} AND scope_ct.is_deleted = 0) OR EXISTS (SELECT 1 FROM pumps scope_cp WHERE lower(calibration_records.entity_type) IN ('pump', 'pumps') AND scope_cp.id = calibration_records.entity_id AND scope_cp.station_id = ${stationId} AND scope_cp.is_deleted = 0) OR EXISTS (SELECT 1 FROM pump_nozzles scope_cn JOIN pumps scope_cp2 ON scope_cp2.id = scope_cn.pump_id WHERE lower(calibration_records.entity_type) IN ('nozzle', 'nozzles', 'pump_nozzle', 'pump_nozzles') AND scope_cn.id = calibration_records.entity_id AND scope_cp2.station_id = ${stationId} AND scope_cn.is_deleted = 0 AND scope_cp2.is_deleted = 0))"

    private fun fleetStationPredicate(screenKey: String, stationId: Int): String? {
        require(stationId > 0) { "معرف المحطة غير صالح" }
        return when (screenKey) {
            "vehicles" -> "EXISTS (SELECT 1 FROM parties scope_party WHERE scope_party.id = vehicles.party_id AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            "drivers" -> "drivers.station_id = ${stationId} AND (drivers.party_id IS NULL OR EXISTS (SELECT 1 FROM parties scope_party WHERE scope_party.id = drivers.party_id AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)) AND (drivers.vehicle_id IS NULL OR EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = drivers.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0))"
            "vehicle_locations" -> "EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = vehicle_locations.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            "vehicle_trips" -> "EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = vehicle_trips.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            "vehicle_expenses" -> "EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = vehicle_expenses.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            "vehicle_maintenance" -> "EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = vehicle_maintenance.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            "vehicle_insurance" -> "EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = vehicle_insurance.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ${stationId} AND scope_party.is_deleted = 0)"
            else -> null
        }
    }

    private fun requireVehicleInStation(db: SQLiteDatabase, vehicleId: Long, stationId: Int) {
        require(vehicleId > 0L && stationId > 0) { "معرف المركبة والمحطة مطلوبان" }
        val owned = db.rawQuery("SELECT 1 FROM vehicles v JOIN parties p ON p.id = v.party_id WHERE v.id=? AND v.is_deleted=0 AND p.station_id=? AND p.is_deleted=0 LIMIT 1", arrayOf(vehicleId.toString(), stationId.toString())).use { it.moveToFirst() }
        require(owned) { "المركبة غير موجودة ضمن محطة المستخدم" }
    }

    private fun requireDriverInStation(db: SQLiteDatabase, driverId: Long, stationId: Int) {
        require(driverId > 0L && stationId > 0) { "معرف السائق والمحطة مطلوبان" }
        val owned = db.rawQuery("""
            SELECT 1 FROM drivers d
            WHERE d.id=? AND d.is_deleted=0 AND d.station_id=?
              AND (d.party_id IS NULL OR EXISTS (SELECT 1 FROM parties p WHERE p.id=d.party_id AND p.station_id=? AND p.is_deleted=0))
              AND (d.vehicle_id IS NULL OR EXISTS (SELECT 1 FROM vehicles v JOIN parties p ON p.id=v.party_id WHERE v.id=d.vehicle_id AND v.is_deleted=0 AND p.station_id=? AND p.is_deleted=0))
            LIMIT 1
        """.trimIndent(), arrayOf(driverId.toString(), stationId.toString(), stationId.toString(), stationId.toString())).use { it.moveToFirst() }
        require(owned) { "السائق غير موجود ضمن محطة المستخدم" }
    }

    private fun requireFleetRelationsInStation(db: SQLiteDatabase, screenKey: String, data: JSONObject, stationId: Int) {
        if (stationId <= 0) return
        when (screenKey) {
            "vehicles" -> requirePartyInStation(db, data.optLong("party_id", 0L), stationId)
            "drivers" -> {
                val partyId = data.optLong("party_id", 0L)
                val vehicleId = data.optLong("vehicle_id", 0L)
                if (partyId > 0L) requirePartyInStation(db, partyId, stationId)
                if (vehicleId > 0L) requireVehicleInStation(db, vehicleId, stationId)
            }
            "vehicle_locations", "vehicle_trips", "vehicle_expenses", "vehicle_maintenance", "vehicle_insurance" -> {
                requireVehicleInStation(db, data.optLong("vehicle_id", 0L), stationId)
                if (screenKey == "vehicle_trips") {
                    val driverId = data.optLong("driver_id", 0L)
                    if (driverId > 0L) requireDriverInStation(db, driverId, stationId)
                }
            }
        }
    }

    private fun fleetDataForExisting(db: SQLiteDatabase, screenKey: String, input: JSONObject, existingId: Long): JSONObject {
        val data = JSONObject(input.toString())
        val relationColumns = when (screenKey) {
            "vehicles" -> listOf("party_id", "vehicle_code")
            "drivers" -> listOf("party_id", "vehicle_id", "driver_code")
            "vehicle_locations", "vehicle_expenses", "vehicle_maintenance", "vehicle_insurance" -> listOf("vehicle_id")
            "vehicle_trips" -> listOf("vehicle_id", "driver_id", "start_odometer", "end_odometer")
            else -> emptyList()
        }
        val missing = relationColumns.filter { !data.has(it) }
        if (missing.isEmpty()) return data
        val spec = operationalSpec(screenKey) ?: return data
        val softDeleteClause = if (spec.softDeleted) " AND is_deleted=0" else ""
        db.rawQuery("SELECT ${missing.joinToString(", ")} FROM ${spec.table} WHERE id=?$softDeleteClause LIMIT 1", arrayOf(existingId.toString())).use { cursor ->
            if (cursor.moveToFirst()) {
                missing.forEachIndexed { index, column ->
                    if (!cursor.isNull(index)) {
                        val value: Any = when {
                            column.endsWith("_code") -> cursor.getString(index)
                            column in setOf("start_odometer", "end_odometer") -> cursor.getDouble(index)
                            else -> cursor.getLong(index)
                        }
                        data.put(column, value)
                    }
                }
            }
        }
        return data
    }

    fun getShiftRecordsTyped(params: JSONObject = JSONObject()): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val where = mutableListOf<String>()
            val args = mutableListOf<String>()
            where += "sh.is_deleted = 0"
            val stationId = params.optLong("station_id", 0L)
            if (stationId > 0L) {
                where += "sh.station_id =?"
                args += stationId.toString()
            }
            val search = params.optString("search", "").trim()
            if (search.isNotBlank()) {
                where += """
                    ( sh.shift_code LIKE? OR sh.shift_type LIKE? OR sh.status LIKE? OR st.station_name LIKE? OR st.station_name_ar LIKE? OR manager.full_name LIKE? OR manager.full_name_ar LIKE? OR cashier.full_name LIKE? OR cashier.full_name_ar LIKE? )
                    """.trimIndent()
                repeat(9) { args += "%$search%" }
            }
            val status = params.optString("status", "").trim()
            if (status.isNotBlank()) {
                when (status) {
                    "open", "closed", "cancelled" -> {
                        where += "sh.status =?"
                        args += status
                    }
                }
            }
            val fromDate = params.optString(
                "from_date", params.optString("start_date", "")
            ).trim()
            val toDate = params.optString(
                "to_date", params.optString("end_date", "")
            ).trim()
            if (fromDate.isNotBlank()) {
                where += "date(sh.shift_date) >= date(?)"
                args += fromDate
            }
            if (toDate.isNotBlank()) {
                where += "date(sh.shift_date) <= date(?)"
                args += toDate
            }
            val limit = params.optInt("limit", 200)
               .coerceIn(1, 500)
            val offset = params.optInt("offset", 0)
               .coerceAtLeast(0)
            val whereSql = if (where.isEmpty()) {
                ""
            } else {
                " WHERE " + where.joinToString(" AND ")
            }
            val query = """
                SELECT sh.*, st.station_name AS station_name, st.station_name_ar AS station_name_ar, manager.username AS manager_username, manager.full_name AS manager_name, manager.full_name_ar AS manager_name_ar, manager.display_name AS manager_display_name, cashier.username AS cashier_username, cashier.full_name AS cashier_name, cashier.full_name_ar AS cashier_name_ar, cashier.display_name AS cashier_display_name FROM shifts sh LEFT JOIN stations st ON st.id = sh.station_id LEFT JOIN users manager ON manager.id = sh.manager_id LEFT JOIN users cashier ON cashier.id = sh.cashier_id $whereSql ORDER BY sh.id DESC LIMIT? OFFSET?
                """.trimIndent()
            val queryArgs = args.toMutableList().apply {
                add(limit.toString())
                add(offset.toString())
            }
            val result = db.rawQuery(
                query, queryArgs.toTypedArray()
            ).use { cursor ->
                cursorToJsonArray(cursor)
            }
            /*
             * حل أسماء العاملين المرتبطين بالوردية.
             *
             * attendant_ids مخزنة كـ JSON داخل جدول shifts.
             * نقوم بجمع كل المعرفات أولاً ثم تنفيذ استعلام
             * واحد فقط لجلب الأسماء بدلاً من تنفيذ استعلام
             * منفصل لكل عامل.
             */
            val attendantIds = linkedSetOf<Long>()
            for (i in 0 until result.length()) {
                val row = result.optJSONObject(i)?: continue
                val rawIds = row.optString(
                    "attendant_ids", "[]"
                )
                try {
                    val idsArray = JSONArray(rawIds)
                    for (j in 0 until idsArray.length()) {
                        val id = idsArray.optLong(j, 0L)
                        if (id > 0L) {
                            attendantIds += id
                        }
                    }
                } catch (_: Exception) {
                    // قيمة قديمة أو غير صالحة؛ لا توقف قراءة الورديات.
                }
            }
            val attendantNames = mutableMapOf<Long, String>()
            val attendantNamesAr = mutableMapOf<Long, String>()
            if (attendantIds.isNotEmpty()) {
                val placeholders = attendantIds.joinToString(",") { "?" }
                val idArgs = attendantIds.map { it.toString() }.toTypedArray()
                db.rawQuery(
                    """
                    SELECT id, employee_code, full_name, full_name_ar, job_title, job_title_ar FROM employees WHERE id IN ($placeholders) AND is_deleted = 0
                    """.trimIndent(),
                    idArgs
                ).use { cursor ->
                    val idIndex = cursor.getColumnIndexOrThrow("id")
                    val employeeCodeIndex = cursor.getColumnIndexOrThrow("employee_code")
                    val fullNameIndex = cursor.getColumnIndexOrThrow("full_name")
                    val fullNameArIndex = cursor.getColumnIndexOrThrow("full_name_ar")
                    val jobTitleArIndex = cursor.getColumnIndexOrThrow("job_title_ar")
                    while (cursor.moveToNext()) {
                        val id = cursor.getLong(idIndex)
                        val employeeCode = if (cursor.isNull(employeeCodeIndex)) "" else cursor.getString(employeeCodeIndex)
                        val fullName = if (cursor.isNull(fullNameIndex)) "" else cursor.getString(fullNameIndex)
                        val fullNameAr = if (cursor.isNull(fullNameArIndex)) "" else cursor.getString(fullNameArIndex)
                        val jobTitleAr = if (cursor.isNull(jobTitleArIndex)) "" else cursor.getString(jobTitleArIndex)
                        attendantNames[id] = listOf(fullName, fullNameAr, employeeCode).firstOrNull { it.isNotBlank() } ?: ""
                        attendantNamesAr[id] = listOf(fullNameAr, fullName, employeeCode).firstOrNull { it.isNotBlank() } ?: ""
                    }
                }
            }
            /*
             * إضافة أسماء العاملين إلى كل سجل.
             */
            for (i in 0 until result.length()) {
                val row = result.optJSONObject(i)?: continue
                val rawIds = row.optString(
                    "attendant_ids", "[]"
                )
                val names = mutableListOf<String>()
                val namesAr = mutableListOf<String>()
                try {
                    val idsArray = JSONArray(rawIds)
                    for (j in 0 until idsArray.length()) {
                        val id = idsArray.optLong(j, 0L)
                        if (id <= 0L) continue
                        attendantNames[id]
                           ?.takeIf { it.isNotBlank() }
                           ?.let { names += it }
                        attendantNamesAr[id]
                           ?.takeIf { it.isNotBlank() }
                           ?.let { namesAr += it }
                    }
                } catch (_: Exception) {
                    // تجاهل القيمة غير الصالحة دون إسقاط السجل.
                }
                row.put(
                    "attendant_names", names.joinToString("، ")
                )
                row.put(
                    "attendant_names_ar", namesAr.joinToString("، ")
                )
            }
            result
        } finally {
            dbLock.unlock()
        }
    }

    fun getOperationalRows(screenKey: String, params: JSONObject = JSONObject()): JSONArray {
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        dbLock.lock()
        return try {
            val db = readableDatabase
            val where = mutableListOf<String>()
            val args = mutableListOf<String>()
            if (spec.softDeleted && !(screenKey in setOf("drivers", "vehicles", "vehicle_maintenance", "vehicle_insurance") && params.optBoolean("include_deleted", false))) where += "is_deleted = 0"
            val stationId = params.optInt("station_id", 0)
            if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_refills", "tank_level_log", "fuel_quality_tests", "calibration_records")) require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
            val fleetScope = if (stationId > 0) fleetStationPredicate(screenKey, stationId) else null
            if (stationId > 0 && screenKey == "calibration_records") {
                where += calibrationStationPredicate(stationId)
            } else if (stationId > 0 && fleetScope != null) {
                where += fleetScope
            } else if (stationId > 0 && spec.columns.contains("station_id")) {
                where += "station_id = ?"
                args += stationId.toString()
            } else if (stationId > 0 && screenKey == "bad_debts") {
                where += "EXISTS (SELECT 1 FROM parties party WHERE party.id = bad_debts.customer_id AND party.station_id = ${stationId} AND party.is_deleted = 0)"
            } else if (stationId > 0 && screenKey == "stocktakes") {
