            if (to.isNotBlank()) { where += "date($dateColumn) <= date(?)"; args += to }
            val whereSql = if (where.isEmpty()) "" else " WHERE " + where.joinToString(" AND ")
            readableDatabase.rawQuery("SELECT COUNT(*) FROM ${spec.table}$whereSql", args.toTypedArray()).use { cursor ->
                if (cursor.moveToFirst()) cursor.getInt(0) else 0
            }
        } finally { dbLock.unlock() }
    }

    fun getOperationalReport(screenKey: String, params: JSONObject = JSONObject()): JSONObject {
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        val rows = getOperationalRows(screenKey, params)
        val totals = JSONObject()
        spec.numericColumns.forEach { key ->
            var total = 0.0
            for (i in 0 until rows.length()) total += rows.optJSONObject(i)?.optDouble(key, 0.0) ?: 0.0
            totals.put(key, total)
        }
        val pageSize = params.optInt("limit", 200).coerceIn(1, 1000)
        val offset = params.optInt("offset", 0).coerceAtLeast(0)
        val totalCount = getOperationalTotalCount(screenKey, params)
        val page = (offset / pageSize) + 1
        val totalPages = if (totalCount == 0) 0 else ((totalCount + pageSize - 1) / pageSize)
        return JSONObject().apply {
            put("rows", rows)
            put("count", rows.length())
            put("total_count", totalCount)
            put("page", page)
            put("page_size", pageSize)
            put("total_pages", totalPages)
            put("has_next", page < totalPages)
            put("has_previous", page > 1)
            put("totals", totals)
            put("source", spec.table)
        }
    }

    private fun vehicleExpenseFilters(params: JSONObject, stationId: Int): Pair<MutableList<String>, MutableList<String>> {
        require(stationId > 0) { "معرف المحطة غير صالح" }
        val where = mutableListOf("EXISTS (SELECT 1 FROM vehicles scope_vehicle JOIN parties scope_party ON scope_party.id = scope_vehicle.party_id WHERE scope_vehicle.id = e.vehicle_id AND scope_vehicle.is_deleted = 0 AND scope_party.station_id = ? AND scope_party.is_deleted = 0)")
        val args = mutableListOf(stationId.toString())
        val vehicleId = params.optLong("vehicle_id", 0L)
        if (vehicleId > 0L) { where += "e.vehicle_id = ?"; args += vehicleId.toString() }
        val expenseType = params.optString("expense_type", "").trim()
        if (expenseType.isNotBlank()) { where += "e.expense_type = ?"; args += expenseType }
        val from = params.optString("from_date", "").trim()
        val to = params.optString("to_date", "").trim()
        if (from.isNotBlank()) { require(parseAttendanceDate(from) != null) { "تاريخ بداية المصروفات غير صالح" }; where += "e.expense_date >= ?"; args += from }
        if (to.isNotBlank()) { require(parseAttendanceDate(to) != null) { "تاريخ نهاية المصروفات غير صالح" }; where += "e.expense_date <= ?"; args += to }
        if (from.isNotBlank() && to.isNotBlank()) require(from <= to) { "تاريخ النهاية لا يمكن أن يسبق تاريخ البداية" }
        fun amount(key: String): Double? {
            val raw = params.optString(key, "").trim()
            if (raw.isBlank()) return null
            return raw.toDoubleOrNull()?.takeIf { it.isFinite() && it >= 0.0 } ?: throw IllegalArgumentException("قيمة $key غير صالحة")
        }
        amount("min_amount")?.let { where += "e.amount >= ?"; args += it.toString() }
        amount("max_amount")?.let { where += "e.amount <= ?"; args += it.toString() }
        val invoiceState = params.optString("invoice_state", "all").trim().lowercase(Locale.US)
        when (invoiceState) {
            "", "all" -> Unit
            "attached" -> where += "NULLIF(TRIM(COALESCE(e.invoice_path, '')), '') IS NOT NULL"
            "missing" -> where += "NULLIF(TRIM(COALESCE(e.invoice_path, '')), '') IS NULL"
            else -> throw IllegalArgumentException("حالة الفاتورة غير مدعومة")
        }
        val search = params.optString("search", "").trim()
        if (search.isNotBlank()) {
            where += "(e.expense_type LIKE ? OR e.description LIKE ? OR v.vehicle_code LIKE ? OR v.plate_number LIKE ? OR v.plate_number_ar LIKE ? OR v.brand LIKE ? OR v.model LIKE ? OR e.invoice_path LIKE ?)"
            repeat(8) { args += "%$search%" }
        }
        return where to args
    }

    /** مساحة عمل مالية لمصروفات مركبات المحطة؛ التجميعات والنطاقات تنفذ في SQLite لا في WebView. */
    fun getVehicleExpenseWorkspace(params: JSONObject = JSONObject(), stationId: Int): JSONObject {
        val (where, args) = vehicleExpenseFilters(params, stationId)
        val whereSql = where.joinToString(" AND ")
        val limit = params.optInt("limit", 60).coerceIn(1, 200)
        val offset = params.optInt("offset", 0).coerceAtLeast(0)
        val tripDates = mutableListOf<String>()
        val tripArgs = mutableListOf<String>()
        val from = params.optString("from_date", "").trim()
        val to = params.optString("to_date", "").trim()
        if (from.isNotBlank()) { tripDates += "t.trip_date >= ?"; tripArgs += from }
        if (to.isNotBlank()) { tripDates += "t.trip_date <= ?"; tripArgs += to }
        val vehicleId = params.optLong("vehicle_id", 0L)
        if (vehicleId > 0L) { tripDates += "t.vehicle_id = ?"; tripArgs += vehicleId.toString() }
        val tripDateSql = if (tripDates.isEmpty()) "" else " AND ${tripDates.joinToString(" AND ")}"
        val vehicleLabel = "COALESCE(NULLIF(TRIM(COALESCE(v.brand, '') || ' ' || COALESCE(v.model, '')), ''), NULLIF(v.vehicle_code, ''), 'مركبة')"
        val detailsSql = """
            SELECT e.id, e.vehicle_id, e.expense_type, e.expense_date, e.amount, e.currency_id, e.odometer_reading, e.description, e.invoice_path, e.created_at,
                   $vehicleLabel AS vehicle_name, COALESCE(NULLIF(v.plate_number_ar, ''), NULLIF(v.plate_number, ''), v.vehicle_code) AS plate_number,
                   COALESCE(NULLIF(c.currency_name_ar, ''), c.currency_name, c.currency_code, '') AS currency_name, COALESCE(c.currency_code, '') AS currency_code, COALESCE(c.symbol, '') AS currency_symbol
            FROM vehicle_expenses e
            JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0
            LEFT JOIN currencies c ON c.id = e.currency_id AND c.is_deleted = 0
            WHERE $whereSql
            ORDER BY e.expense_date DESC, e.id DESC
            LIMIT ? OFFSET ?
        """.trimIndent()
        val summarySql = """
            SELECT COUNT(*) AS record_count, COALESCE(SUM(e.amount), 0) AS total_expenses,
                   COALESCE(SUM(CASE WHEN e.expense_date >= date('now', 'start of month') AND e.expense_date < date('now', 'start of month', '+1 month') THEN e.amount ELSE 0 END), 0) AS current_month_expenses,
                   SUM(CASE WHEN NULLIF(TRIM(COALESCE(e.invoice_path, '')), '') IS NOT NULL THEN 1 ELSE 0 END) AS attached_invoice_count,
                   (SELECT COALESCE(SUM(t.distance_km), 0) FROM vehicle_trips t
                    WHERE t.trip_status <> 'cancelled' AND COALESCE(t.distance_km, 0) > 0
                      AND EXISTS (SELECT 1 FROM vehicles tv JOIN parties tp ON tp.id = tv.party_id WHERE tv.id = t.vehicle_id AND tv.is_deleted = 0 AND tp.station_id = ? AND tp.is_deleted = 0)$tripDateSql) AS total_distance_km
            FROM vehicle_expenses e
            JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0
            WHERE $whereSql
        """.trimIndent()
        val byVehicleSql = """
            SELECT vehicle_totals.*, CASE WHEN vehicle_totals.distance_km > 0 THEN ROUND(vehicle_totals.total_expenses / vehicle_totals.distance_km, 2) END AS cost_per_km
            FROM (
                SELECT e.vehicle_id, $vehicleLabel AS vehicle_name, COALESCE(NULLIF(v.plate_number_ar, ''), NULLIF(v.plate_number, ''), v.vehicle_code) AS plate_number,
                       COALESCE(SUM(e.amount), 0) AS total_expenses, COUNT(*) AS record_count,
                       (SELECT COALESCE(SUM(t.distance_km), 0) FROM vehicle_trips t WHERE t.vehicle_id = e.vehicle_id AND t.trip_status <> 'cancelled' AND COALESCE(t.distance_km, 0) > 0$tripDateSql) AS distance_km
                FROM vehicle_expenses e JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0
                WHERE $whereSql
                GROUP BY e.vehicle_id, v.brand, v.model, v.vehicle_code, v.plate_number_ar, v.plate_number
            ) vehicle_totals
            ORDER BY vehicle_totals.total_expenses DESC, vehicle_totals.vehicle_id ASC LIMIT 12
        """.trimIndent()
        val byTypeSql = "SELECT e.expense_type, COALESCE(SUM(e.amount), 0) AS total_expenses, COUNT(*) AS record_count FROM vehicle_expenses e JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0 WHERE $whereSql GROUP BY e.expense_type ORDER BY total_expenses DESC, e.expense_type ASC LIMIT 12"
        val topExpensesSql = "SELECT e.id, e.vehicle_id, e.expense_type, e.expense_date, e.amount, $vehicleLabel AS vehicle_name, COALESCE(NULLIF(v.plate_number_ar, ''), NULLIF(v.plate_number, ''), v.vehicle_code) AS plate_number FROM vehicle_expenses e JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0 WHERE $whereSql ORDER BY e.amount DESC, e.expense_date DESC, e.id DESC LIMIT 5"
        dbLock.lock()
        return try {
            val db = readableDatabase
            val rows = db.rawQuery(detailsSql, (args + limit.toString() + offset.toString()).toTypedArray()).use(::cursorToJsonArray)
            val summary = db.rawQuery(summarySql, (listOf(stationId.toString()) + tripArgs + args).toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject() }
            val totalDistance = summary.optDouble("total_distance_km", 0.0)
            val totalExpenses = summary.optDouble("total_expenses", 0.0)
            summary.put("cost_per_km", if (totalDistance > 0.0) totalExpenses / totalDistance else JSONObject.NULL)
            val byVehicle = db.rawQuery(byVehicleSql, (tripArgs + args).toTypedArray()).use(::cursorToJsonArray)
            val byType = db.rawQuery(byTypeSql, args.toTypedArray()).use(::cursorToJsonArray)
            val topExpenses = db.rawQuery(topExpensesSql, args.toTypedArray()).use(::cursorToJsonArray)
            summary.put("top_vehicle_name", byVehicle.optJSONObject(0)?.optString("vehicle_name", "") ?: "")
            summary.put("top_expense_type", byType.optJSONObject(0)?.optString("expense_type", "") ?: "")
            val vehicles = db.rawQuery("SELECT v.id, v.vehicle_code, $vehicleLabel AS vehicle_name, COALESCE(NULLIF(v.plate_number_ar, ''), NULLIF(v.plate_number, ''), v.vehicle_code) AS plate_number FROM vehicles v JOIN parties p ON p.id = v.party_id WHERE v.is_deleted = 0 AND p.is_deleted = 0 AND p.station_id = ? ORDER BY vehicle_name COLLATE NOCASE, v.id", arrayOf(stationId.toString())).use(::cursorToJsonArray)
            val expenseTypes = db.rawQuery("SELECT DISTINCT e.expense_type FROM vehicle_expenses e JOIN vehicles v ON v.id = e.vehicle_id JOIN parties p ON p.id = v.party_id WHERE v.is_deleted = 0 AND p.is_deleted = 0 AND p.station_id = ? AND NULLIF(TRIM(e.expense_type), '') IS NOT NULL ORDER BY e.expense_type COLLATE NOCASE", arrayOf(stationId.toString())).use(::cursorToJsonArray)
            val currencies = db.rawQuery("SELECT id, currency_code, COALESCE(NULLIF(currency_name_ar, ''), currency_name, currency_code) AS currency_name, COALESCE(symbol, '') AS symbol, is_default FROM currencies WHERE is_deleted = 0 AND is_active = 1 ORDER BY is_default DESC, currency_code ASC", null).use(::cursorToJsonArray)
            JSONObject().apply {
                put("rows", rows); put("summary", summary); put("by_vehicle", byVehicle); put("by_expense_type", byType); put("top_expenses", topExpenses)
                put("vehicles", vehicles); put("expense_types", expenseTypes); put("currencies", currencies)
                put("page", (offset / limit) + 1); put("page_size", limit); put("total_count", summary.optInt("record_count", 0)); put("has_next", offset + rows.length() < summary.optInt("record_count", 0))
            }
        } finally { dbLock.unlock() }
    }

    fun getVehicleExpenseDetails(expenseId: Long, stationId: Int): JSONObject? {
        require(expenseId > 0L) { "معرف المصروف غير صالح" }
        dbLock.lock()
        return try {
            readableDatabase.rawQuery("""
                SELECT e.id, e.vehicle_id, e.expense_type, e.expense_date, e.amount, e.currency_id, e.odometer_reading, e.description, e.invoice_path, e.created_at,
                       COALESCE(NULLIF(TRIM(COALESCE(v.brand, '') || ' ' || COALESCE(v.model, '')), ''), NULLIF(v.vehicle_code, ''), 'مركبة') AS vehicle_name,
                       COALESCE(NULLIF(v.plate_number_ar, ''), NULLIF(v.plate_number, ''), v.vehicle_code) AS plate_number,
                       COALESCE(NULLIF(c.currency_name_ar, ''), c.currency_name, c.currency_code, '') AS currency_name, COALESCE(c.currency_code, '') AS currency_code, COALESCE(c.symbol, '') AS currency_symbol
                FROM vehicle_expenses e JOIN vehicles v ON v.id = e.vehicle_id AND v.is_deleted = 0
                JOIN parties p ON p.id = v.party_id AND p.station_id = ? AND p.is_deleted = 0
                LEFT JOIN currencies c ON c.id = e.currency_id AND c.is_deleted = 0
                WHERE e.id = ? LIMIT 1
            """.trimIndent(), arrayOf(stationId.toString(), expenseId.toString())).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else null }
        } finally { dbLock.unlock() }
    }

    fun getVehicleExpenseInvoicePath(expenseId: Long, stationId: Int): String? =
        getVehicleExpenseDetails(expenseId, stationId)?.optString("invoice_path", "")?.trim()?.takeIf { it.isNotBlank() }

    /** يعيد حالة الاتصال وآخر قراءة مخزنة للمركبات التي تقع ضمن المحطة فقط. */
    fun getVehicleTrackingStatus(params: JSONObject = JSONObject()): JSONArray {
        val stationId = params.optInt("station_id", 0)
        require(stationId > 0) { "معرف المحطة مطلوب لحالة اتصال المركبات" }
        val vehicleId = params.optLong("vehicle_id", 0L)
        val maxAgeMinutes = params.optInt("max_age_minutes", 15).coerceIn(1, 1440)
        val limit = params.optInt("limit", 500).coerceIn(1, 1000)
        val offset = params.optInt("offset", 0).coerceAtLeast(0)
        val args = mutableListOf<String>()
        val where = StringBuilder("v.is_deleted = 0 AND EXISTS (SELECT 1 FROM parties p_scope WHERE p_scope.id = v.party_id AND p_scope.station_id = ? AND p_scope.is_deleted = 0)")
        args += stationId.toString()
        if (vehicleId > 0L) { where.append(" AND v.id = ?"); args += vehicleId.toString() }
        val sql = """
            SELECT v.id AS vehicle_id, v.vehicle_code, v.plate_number, v.plate_number_ar, v.vehicle_type, v.brand, v.model, v.status AS vehicle_status,
                   device.id AS device_id, device.device_code, device.device_name, device.status AS device_status, device.last_communication,
                   location.location_time AS last_location_time, location.latitude AS last_latitude, location.longitude AS last_longitude,
                   location.speed AS last_speed, location.fuel_level AS last_fuel_level, location.odometer AS last_odometer,
                   CASE WHEN device.id IS NOT NULL AND lower(COALESCE(device.status, '')) = 'active' AND device.last_communication IS NOT NULL
                             AND (julianday('now') - julianday(device.last_communication)) * 1440 <= $maxAgeMinutes THEN 'connected'
                        WHEN location.id IS NOT NULL AND location.location_time IS NOT NULL
                             AND (julianday('now') - julianday(location.location_time)) * 1440 <= $maxAgeMinutes THEN 'recent'
                        WHEN device.id IS NOT NULL OR location.id IS NOT NULL THEN 'stale' ELSE 'none' END AS connection_state,
                   CASE WHEN device.last_communication IS NOT NULL THEN CAST((julianday('now') - julianday(device.last_communication)) * 1440 AS INTEGER)
                        WHEN location.location_time IS NOT NULL THEN CAST((julianday('now') - julianday(location.location_time)) * 1440 AS INTEGER) ELSE NULL END AS age_minutes
            FROM vehicles v
            LEFT JOIN iot_devices device ON device.id = (SELECT d_latest.id FROM iot_devices d_latest WHERE d_latest.entity_id = v.id AND lower(d_latest.entity_type) IN ('vehicle', 'vehicles') ORDER BY d_latest.id DESC LIMIT 1)
            LEFT JOIN vehicle_locations location ON location.id = (SELECT l_latest.id FROM vehicle_locations l_latest WHERE l_latest.vehicle_id = v.id ORDER BY datetime(l_latest.location_time) DESC, l_latest.id DESC LIMIT 1)
            WHERE $where
            ORDER BY CASE connection_state WHEN 'connected' THEN 0 WHEN 'recent' THEN 1 WHEN 'stale' THEN 2 ELSE 3 END, datetime(COALESCE(last_location_time, last_communication)) DESC, v.id ASC
            LIMIT ? OFFSET ?
        """.trimIndent()
        args += limit.toString(); args += offset.toString()
        dbLock.lock()
        return try { readableDatabase.rawQuery(sql, args.toTypedArray()).use { cursorToJsonArray(it) } }
        finally { dbLock.unlock() }
    }

    /** يعيد نقاط GPS المخزنة فقط لمسار مركبة مملوكة للمحطة؛ لا يصطنع تتبعاً حياً. */
    fun getVehicleRouteRecords(params: JSONObject = JSONObject()): JSONArray {
        val stationId = params.optInt("station_id", 0)
        require(stationId > 0) { "معرف المحطة مطلوب لمسار المركبة" }
        val vehicleId = params.optLong("vehicle_id", 0L)
        require(vehicleId > 0L) { "معرف المركبة مطلوب لمسار المركبة" }
        val from = params.optString("from_date", params.optString("start_date", "")).trim()
        val to = params.optString("to_date", params.optString("end_date", "")).trim()
        val limit = params.optInt("limit", 1000).coerceIn(1, 5000)
        dbLock.lock()
        return try {
            val db = readableDatabase
            requireVehicleInStation(db, vehicleId, stationId)
            val where = mutableListOf("vehicle_id = ?")
            val args = mutableListOf(vehicleId.toString())
            if (from.isNotBlank()) { where += "location_time >= ?"; args += from }
            if (to.isNotBlank()) { where += "location_time < ?"; args += nextRouteDateExclusive(to) }
            val sql = "SELECT id, vehicle_id, latitude, longitude, speed, heading, fuel_level, odometer, altitude, accuracy, location_time FROM vehicle_locations WHERE ${where.joinToString(" AND ")} ORDER BY location_time ASC, id ASC LIMIT ?"
            args += limit.toString()
            db.rawQuery(sql, args.toTypedArray()).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    private fun nextRouteDateExclusive(dateText: String): String {
        val format = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { isLenient = false; timeZone = TimeZone.getTimeZone("UTC") }
        val date = format.parse(dateText) ?: throw IllegalArgumentException("تاريخ نهاية المسار غير صالح")
        return format.format(Calendar.getInstance(TimeZone.getTimeZone("UTC"), Locale.US).apply { time = date; add(Calendar.DAY_OF_MONTH, 1) }.time)
    }

    /**
     * يعيد مساحة عمل رحلات المركبات من SQLite فقط. لا ينسخ station_id من WebView:
     * نطاق المحطة يأتي من MainActivity، وكل رحلة تمر عبر المركبة ومالكها ضمن المحطة.
     * الموقع المعاد هو آخر قياس مخزن للمركبة، وليس ادعاءً بأنه موقع حي أو تابع للرحلة نفسها.
     */
    fun getVehicleTripWorkspace(params: JSONObject = JSONObject(), stationId: Int): JSONObject {
        require(stationId > 0) { "معرف المحطة غير صالح" }
        val limit = params.optInt("limit", 20).coerceIn(1, 100)
        val offset = params.optInt("offset", 0).coerceAtLeast(0)
        val allowedSorts = mapOf(
            "trip_date" to "t.trip_date",
            "distance_km" to "t.distance_km",
            "fuel_consumed" to "t.fuel_consumed",
            "fuel_cost" to "t.fuel_cost",
            "created_at" to "t.created_at"
        )
        val sortBy = allowedSorts[params.optString("sort_by", "trip_date").trim()] ?: "t.trip_date"
        val sortDirection = if (params.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
        val where = mutableListOf<String>()
        val args = mutableListOf<String>()
        val joins = """
            FROM vehicle_trips t
            JOIN vehicles v ON v.id = t.vehicle_id AND v.is_deleted = 0
            JOIN parties station_party ON station_party.id = v.party_id
                AND station_party.station_id = ? AND station_party.is_deleted = 0
            LEFT JOIN drivers d ON d.id = t.driver_id AND d.station_id = ? AND d.is_deleted = 0
        """.trimIndent()
        val joinArgs = listOf(stationId.toString(), stationId.toString())

        params.optLong("vehicle_id", 0L).takeIf { it > 0L }?.let {
            where += "t.vehicle_id = ?"; args += it.toString()
        }
        params.optLong("driver_id", 0L).takeIf { it > 0L }?.let {
            where += "t.driver_id = ?"; args += it.toString()
        }
        val fromDate = params.optString("from_date", "").trim()
        val toDate = params.optString("to_date", "").trim()
        if (fromDate.isNotBlank()) { where += "date(t.trip_date) >= date(?)"; args += fromDate }
        if (toDate.isNotBlank()) { where += "date(t.trip_date) <= date(?)"; args += toDate }
        val requestedStatus = params.optString("trip_status", "").trim().lowercase(Locale.US)
        if (requestedStatus.isNotBlank()) {
            require(requestedStatus in setOf("scheduled", "active", "completed", "cancelled")) { "حالة الرحلة غير صالحة" }
            where += "t.trip_status = ?"; args += requestedStatus
        }
        val search = params.optString("search", "").trim()
        if (search.isNotBlank()) {
            where += """(
                t.start_location LIKE ? OR t.end_location LIKE ? OR t.trip_purpose LIKE ? OR t.notes LIKE ?
                OR v.vehicle_code LIKE ? OR v.plate_number LIKE ? OR d.driver_code LIKE ? OR d.full_name LIKE ? OR d.full_name_ar LIKE ?
            )""".trimIndent()
            repeat(9) { args += "%$search%" }
        }
        val whereSql = if (where.isEmpty()) "" else " WHERE " + where.joinToString(" AND ")
        val filterArgs = joinArgs + args

        dbLock.lock()
        return try {
            val pageArgs = (filterArgs + listOf(limit.toString(), offset.toString())).toTypedArray()
            val rows = readableDatabase.rawQuery(
                """
                SELECT t.id, t.vehicle_id, t.driver_id, t.trip_date, t.start_location, t.end_location,
                       t.distance_km, t.fuel_consumed, t.fuel_cost, t.start_odometer, t.end_odometer,
                       t.trip_purpose, t.notes, t.trip_status, t.scheduled_at, t.started_at, t.completed_at,
                       t.cancelled_at, t.status_note, t.created_at, t.updated_at,
                       v.vehicle_code, COALESCE(v.plate_number_ar, v.plate_number, '') AS plate_number,
                       v.current_odometer AS vehicle_current_odometer,
                       COALESCE(d.driver_code, '') AS driver_code,
                       COALESCE(d.full_name_ar, d.full_name, '') AS driver_name,
                       latest.latitude AS last_latitude, latest.longitude AS last_longitude,
                       latest.speed AS last_speed, latest.odometer AS last_odometer,
                       latest.location_time AS last_location_time,
                       CASE WHEN COALESCE(t.fuel_consumed, 0) > 0 THEN ROUND(COALESCE(t.distance_km, 0) / t.fuel_consumed, 2) END AS efficiency_km_per_liter,
                       CASE WHEN t.start_odometer IS NOT NULL AND t.end_odometer IS NOT NULL THEN ROUND(t.end_odometer - t.start_odometer, 2) END AS odometer_delta
                $joins
                LEFT JOIN vehicle_locations latest ON latest.id = (
                    SELECT location.id FROM vehicle_locations location
                    WHERE location.vehicle_id = t.vehicle_id
                    ORDER BY datetime(location.location_time) DESC, location.id DESC LIMIT 1
                )
                $whereSql
                ORDER BY $sortBy $sortDirection, t.id DESC
                LIMIT ? OFFSET ?
                """.trimIndent(), pageArgs
            ).use(::cursorToJsonArray)
            val totalCount = readableDatabase.rawQuery(
                "SELECT COUNT(*) $joins$whereSql", filterArgs.toTypedArray()
            ).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
            val statistics = readableDatabase.rawQuery(
                """
                SELECT COUNT(*) AS total_trips,
                       COUNT(DISTINCT t.vehicle_id) AS vehicles_used,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'scheduled' THEN 1 ELSE 0 END), 0) AS scheduled_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'active' THEN 1 ELSE 0 END), 0) AS active_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'completed' THEN 1 ELSE 0 END), 0) AS completed_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'cancelled' THEN 1 ELSE 0 END), 0) AS cancelled_count,
                       COALESCE(SUM(t.distance_km), 0) AS total_distance_km,
                       COALESCE(SUM(t.fuel_consumed), 0) AS total_fuel_consumed,
                       COALESCE(SUM(t.fuel_cost), 0) AS total_fuel_cost,
                       COALESCE(AVG(CASE WHEN t.fuel_consumed > 0 THEN t.distance_km / t.fuel_consumed END), 0) AS average_efficiency
                $joins$whereSql
                """.trimIndent(), filterArgs.toTypedArray()
            ).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject() }
            val vehicles = readableDatabase.rawQuery(
                """
                SELECT v.id, v.vehicle_code, COALESCE(v.plate_number_ar, v.plate_number, '') AS plate_number,
                       COALESCE(v.current_odometer, 0) AS current_odometer
                FROM vehicles v JOIN parties p ON p.id = v.party_id
                WHERE p.station_id = ? AND p.is_deleted = 0 AND v.is_deleted = 0 AND v.status = 'active'
                ORDER BY v.vehicle_code COLLATE NOCASE ASC
                """.trimIndent(), arrayOf(stationId.toString())
            ).use(::cursorToJsonArray)
            val drivers = readableDatabase.rawQuery(
                """
                SELECT d.id, d.driver_code, COALESCE(d.full_name_ar, d.full_name, '') AS driver_name, d.vehicle_id
                FROM drivers d
                WHERE d.station_id = ? AND d.is_deleted = 0 AND d.status = 'active'
                ORDER BY driver_name COLLATE NOCASE ASC
                """.trimIndent(), arrayOf(stationId.toString())
            ).use(::cursorToJsonArray)
            val totalPages = if (totalCount == 0) 0 else (totalCount + limit - 1) / limit
            JSONObject().apply {
                put("rows", rows)
                put("statistics", statistics)
                put("vehicles", vehicles)
                put("drivers", drivers)
                put("total_count", totalCount)
                put("page", (offset / limit) + 1)
                put("page_size", limit)
                put("total_pages", totalPages)
                put("has_next", offset + rows.length() < totalCount)
                put("has_previous", offset > 0)
                put("source", "vehicle_trips")
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun getVehicleTripDetails(tripId: Long, stationId: Int): JSONObject? {
        require(tripId > 0L && stationId > 0) { "معرف الرحلة أو المحطة غير صالح" }
        dbLock.lock()
        return try {
            readableDatabase.rawQuery(
                """
                SELECT t.id, t.vehicle_id, t.driver_id, t.trip_date, t.start_location, t.end_location,
                       t.distance_km, t.fuel_consumed, t.fuel_cost, t.start_odometer, t.end_odometer,
                       t.trip_purpose, t.notes, t.trip_status, t.scheduled_at, t.started_at, t.completed_at,
                       t.cancelled_at, t.status_note, t.created_at, t.updated_at,
                       v.vehicle_code, COALESCE(v.plate_number_ar, v.plate_number, '') AS plate_number,
                       COALESCE(d.driver_code, '') AS driver_code, COALESCE(d.full_name_ar, d.full_name, '') AS driver_name,
                       latest.latitude AS last_latitude, latest.longitude AS last_longitude, latest.speed AS last_speed,
                       latest.location_time AS last_location_time,
                       CASE WHEN COALESCE(t.fuel_consumed, 0) > 0 THEN ROUND(COALESCE(t.distance_km, 0) / t.fuel_consumed, 2) END AS efficiency_km_per_liter
                FROM vehicle_trips t
                JOIN vehicles v ON v.id = t.vehicle_id AND v.is_deleted = 0
                JOIN parties p ON p.id = v.party_id AND p.station_id = ? AND p.is_deleted = 0
                LEFT JOIN drivers d ON d.id = t.driver_id AND d.station_id = ? AND d.is_deleted = 0
                LEFT JOIN vehicle_locations latest ON latest.id = (
                    SELECT location.id FROM vehicle_locations location
                    WHERE location.vehicle_id = t.vehicle_id
                    ORDER BY datetime(location.location_time) DESC, location.id DESC LIMIT 1
                )
                WHERE t.id = ?
                """.trimIndent(), arrayOf(stationId.toString(), stationId.toString(), tripId.toString())
            ).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else null }
        } finally { dbLock.unlock() }
    }

    fun getVehicleTripTimeline(tripId: Long, stationId: Int): JSONArray {
        require(tripId > 0L && stationId > 0) { "معرف الرحلة أو المحطة غير صالح" }
        dbLock.lock()
        return try {
            readableDatabase.rawQuery(
                """
                SELECT e.id, e.event_type, e.event_note, e.occurred_at, e.created_by, COALESCE(u.full_name, '') AS actor_name
                FROM vehicle_trip_events e
                JOIN vehicle_trips t ON t.id = e.trip_id
                JOIN vehicles v ON v.id = t.vehicle_id AND v.is_deleted = 0
                JOIN parties p ON p.id = v.party_id AND p.station_id = ? AND p.is_deleted = 0
                LEFT JOIN users u ON u.id = e.created_by
                WHERE e.trip_id = ?
                ORDER BY datetime(e.occurred_at) ASC, e.id ASC
                """.trimIndent(), arrayOf(stationId.toString(), tripId.toString())
            ).use(::cursorToJsonArray)
        } finally { dbLock.unlock() }
    }

    fun updateVehicleTripStatus(tripId: Long, requestedStatus: String, note: String, stationId: Int, actorId: Long): JSONObject {
        require(tripId > 0L && stationId > 0) { "معرف الرحلة أو المحطة غير صالح" }
        val target = requestedStatus.trim().lowercase(Locale.US)
        require(target in setOf("scheduled", "active", "completed", "cancelled")) { "حالة الرحلة غير صالحة" }
        dbLock.lock()
        return try {
            val writeDb = writableDatabase
            writeDb.beginTransaction()
            try {
                val current = writeDb.rawQuery(
                    """
                    SELECT t.trip_status FROM vehicle_trips t
                    JOIN vehicles v ON v.id = t.vehicle_id AND v.is_deleted = 0
                    JOIN parties p ON p.id = v.party_id AND p.station_id = ? AND p.is_deleted = 0
                    WHERE t.id = ? LIMIT 1
                    """.trimIndent(), arrayOf(stationId.toString(), tripId.toString())
                ).use { cursor -> if (cursor.moveToFirst()) cursor.getString(0) ?: "scheduled" else throw IllegalArgumentException("الرحلة غير موجودة ضمن المحطة") }
                val transitions = mapOf(
                    "scheduled" to setOf("scheduled", "active", "cancelled"),
                    "active" to setOf("active", "completed", "cancelled"),
                    "completed" to setOf("completed"),
                    "cancelled" to setOf("cancelled", "scheduled")
                )
                require(target in (transitions[current] ?: emptySet())) { "لا يمكن تغيير حالة الرحلة من $current إلى $target" }
                require(target != current) { "الحالة الجديدة مطابقة لحالة الرحلة الحالية" }
                val now = getCurrentDateTime()
                val values = ContentValues().apply {
                    put("trip_status", target); put("status_note", note.trim()); put("updated_at", now)
                    when (target) {
                        "scheduled" -> { put("scheduled_at", now); putNull("started_at"); putNull("completed_at"); putNull("cancelled_at") }
                        "active" -> put("started_at", now)
                        "completed" -> put("completed_at", now)
                        "cancelled" -> put("cancelled_at", now)
                    }
                }
                require(writeDb.update("vehicle_trips", values, "id = ?", arrayOf(tripId.toString())) == 1) { "تعذر تحديث حالة الرحلة" }
                val eventType = when (target) { "active" -> "started"; else -> target }
                writeDb.insertOrThrow("vehicle_trip_events", null, ContentValues().apply {
                    put("uuid", UUID.randomUUID().toString()); put("trip_id", tripId); put("event_type", eventType)
                    put("event_note", note.trim()); put("occurred_at", now); if (actorId > 0L) put("created_by", actorId)
                })
                writeDb.setTransactionSuccessful()
                JSONObject().put("id", tripId).put("trip_status", target).put("changed_at", now)
            } finally { writeDb.endTransaction() }
        } finally { dbLock.unlock() }
    }

    fun getVehicleTripStatistics(params: JSONObject = JSONObject(), stationId: Int): JSONObject {
        require(stationId > 0) { "معرف المحطة غير صالح" }
        val where = mutableListOf<String>()
        val args = mutableListOf(stationId.toString(), stationId.toString())
        params.optLong("vehicle_id", 0L).takeIf { it > 0L }?.let { where += "t.vehicle_id = ?"; args += it.toString() }
        params.optLong("driver_id", 0L).takeIf { it > 0L }?.let { where += "t.driver_id = ?"; args += it.toString() }
        val fromDate = params.optString("from_date", "").trim()
        val toDate = params.optString("to_date", "").trim()
        if (fromDate.isNotBlank()) { where += "date(t.trip_date) >= date(?)"; args += fromDate }
        if (toDate.isNotBlank()) { where += "date(t.trip_date) <= date(?)"; args += toDate }
        val requestedStatus = params.optString("trip_status", "").trim().lowercase(Locale.US)
        if (requestedStatus.isNotBlank()) {
            require(requestedStatus in setOf("scheduled", "active", "completed", "cancelled")) { "حالة الرحلة غير صالحة" }
            where += "t.trip_status = ?"; args += requestedStatus
        }
        val search = params.optString("search", "").trim()
        if (search.isNotBlank()) {
            where += "(t.start_location LIKE ? OR t.end_location LIKE ? OR t.trip_purpose LIKE ? OR t.notes LIKE ? OR v.vehicle_code LIKE ? OR v.plate_number LIKE ? OR d.driver_code LIKE ? OR d.full_name LIKE ? OR d.full_name_ar LIKE ?)"
            repeat(9) { args += "%$search%" }
        }
        val joins = """
            FROM vehicle_trips t
            JOIN vehicles v ON v.id = t.vehicle_id AND v.is_deleted = 0
            JOIN parties station_party ON station_party.id = v.party_id AND station_party.station_id = ? AND station_party.is_deleted = 0
            LEFT JOIN drivers d ON d.id = t.driver_id AND d.station_id = ? AND d.is_deleted = 0
        """.trimIndent()
        val whereSql = if (where.isEmpty()) "" else " WHERE " + where.joinToString(" AND ")
        dbLock.lock()
        return try {
            readableDatabase.rawQuery(
                """
                SELECT COUNT(*) AS total_trips,
                       COUNT(DISTINCT t.vehicle_id) AS vehicles_used,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'scheduled' THEN 1 ELSE 0 END), 0) AS scheduled_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'active' THEN 1 ELSE 0 END), 0) AS active_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'completed' THEN 1 ELSE 0 END), 0) AS completed_count,
                       COALESCE(SUM(CASE WHEN t.trip_status = 'cancelled' THEN 1 ELSE 0 END), 0) AS cancelled_count,
                       COALESCE(SUM(t.distance_km), 0) AS total_distance_km,
                       COALESCE(SUM(t.fuel_consumed), 0) AS total_fuel_consumed,
                       COALESCE(SUM(t.fuel_cost), 0) AS total_fuel_cost,
                       COALESCE(AVG(CASE WHEN t.fuel_consumed > 0 THEN t.distance_km / t.fuel_consumed END), 0) AS average_efficiency
                $joins$whereSql
                """.trimIndent(), args.toTypedArray()
            ).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject() }
        } finally { dbLock.unlock() }
    }

    private fun synchronizeLiveStockAlerts(db: SQLiteDatabase, stationScopeId: Int) {
        val activeLowStock = mutableListOf<JSONObject>()
        db.rawQuery(
            """SELECT p.id AS product_id, p.minimum_stock,
                      COALESCE(il.quantity_on_hand, p.quantity, 0) AS current_quantity
               FROM products p
               LEFT JOIN (
                   SELECT level.product_id, SUM(level.quantity_on_hand) AS quantity_on_hand
                   FROM inventory_levels level
                   JOIN warehouses warehouse ON warehouse.id = level.warehouse_id
                   WHERE warehouse.station_id = ? AND warehouse.is_active = 1
                   GROUP BY level.product_id
               ) il ON il.product_id = p.id
               WHERE p.station_id = ? AND p.is_deleted = 0 AND p.status = 'active'""",
            arrayOf(stationScopeId.toString(), stationScopeId.toString())
        ).use { cursor ->
            while (cursor.moveToNext()) {
                val productId = cursor.getLong(0)
                val threshold = cursor.getDouble(1)
                val quantity = cursor.getDouble(2)
                if (quantity <= threshold) activeLowStock += JSONObject().apply {
                    put("product_id", productId); put("threshold", threshold); put("quantity", quantity)
                }
            }
        }
        val activeProductIds = activeLowStock.map { it.getLong("product_id") }.toSet()
        activeLowStock.forEach { item ->
            val productId = item.getLong("product_id")
            val quantity = item.getDouble("quantity")
            val threshold = item.getDouble("threshold")
            val alertType = if (quantity <= 0.0) "out_of_stock" else "low_stock"
            val alertLevel = if (quantity <= 0.0) "critical" else "warning"
            val existingId = db.rawQuery(
                "SELECT id FROM stock_alerts WHERE station_id = ? AND product_id = ? AND is_resolved = 0 AND alert_type IN ('low_stock','out_of_stock') ORDER BY id DESC LIMIT 1",
                arrayOf(stationScopeId.toString(), productId.toString())
            ).use { cursor -> if (cursor.moveToFirst()) cursor.getLong(0) else 0L }
            val values = ContentValues().apply {
                put("alert_type", alertType)
                put("alert_level", alertLevel)
                put("current_quantity", quantity)
                put("threshold_quantity", threshold)
                put("shortage_quantity", (threshold - quantity).coerceAtLeast(0.0))
                put("is_resolved", 0)
            }
            if (existingId > 0L) {
                db.update("stock_alerts", values, "id = ? AND station_id = ?", arrayOf(existingId.toString(), stationScopeId.toString()))
            } else {
                values.put("uuid", UUID.randomUUID().toString())
                values.put("product_id", productId)
                values.put("station_id", stationScopeId)
                values.put("created_at", getCurrentDateTime())
                db.insertOrThrow("stock_alerts", null, values)
            }
        }
        db.rawQuery(
            "SELECT id, product_id FROM stock_alerts WHERE station_id = ? AND is_resolved = 0 AND alert_type IN ('low_stock','out_of_stock')",
            arrayOf(stationScopeId.toString())
        ).use { cursor ->
            while (cursor.moveToNext()) {
                if (cursor.getLong(1) !in activeProductIds) {
                    db.update("stock_alerts", ContentValues().apply {
                        put("is_resolved", 1)
                        put("resolved_at", getCurrentDateTime())
                        put("resolution_notes", "تمت المعالجة تلقائياً بعد تحديث رصيد المخزون")
                    }, "id = ? AND station_id = ?", arrayOf(cursor.getLong(0).toString(), stationScopeId.toString()))
                }
            }
        }
    }

    fun getStockAlertRecordsContract(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        dbLock.lock()
        return try {
            synchronizeLiveStockAlerts(writableDatabase, stationScopeId)
            val params = JSONObject(data.toString()).apply { put("station_id", stationScopeId) }
            val report = getOperationalReport("stock_alerts", params)
            val db = readableDatabase
            val productNames = mutableMapOf<Long, String>()
            db.rawQuery(
                """SELECT DISTINCT a.product_id, COALESCE(p.product_name_ar, p.product_name, p.product_code, '')
                   FROM stock_alerts a
                   LEFT JOIN products p ON p.id = a.product_id AND p.station_id = ? AND p.is_deleted = 0
                   WHERE a.station_id = ?""",
                arrayOf(stationScopeId.toString(), stationScopeId.toString())
            ).use { cursor -> while (cursor.moveToNext()) productNames[cursor.getLong(0)] = cursor.getString(1) ?: "" }
            val enrichedRows = report.optJSONArray("rows") ?: JSONArray()
            for (index in 0 until enrichedRows.length()) {
                enrichedRows.optJSONObject(index)?.let { row ->
                    row.put("product_name", productNames[row.optLong("product_id", 0L)] ?: "منتج غير متاح")
                }
            }
            val statistics = db.rawQuery(
                """SELECT COUNT(*) AS total_count,
                          COALESCE(SUM(CASE WHEN a.is_resolved = 0 THEN 1 ELSE 0 END), 0) AS unresolved_count,
                          COALESCE(SUM(CASE WHEN a.alert_level = 'critical' AND a.is_resolved = 0 THEN 1 ELSE 0 END), 0) AS critical_count,
                          COALESCE(SUM(CASE WHEN a.alert_type = 'expiry' AND a.is_resolved = 0 THEN 1 ELSE 0 END), 0) AS expiring_count,
                          COALESCE(SUM(CASE WHEN a.alert_type = 'expiry' AND a.is_resolved = 0 THEN COALESCE(p.purchase_price, 0) * COALESCE(a.current_quantity, 0) ELSE 0 END), 0) AS expiring_value,
                          COALESCE((SELECT COUNT(*) FROM stocktake_details sd JOIN stocktakes st ON st.id = sd.stocktake_id JOIN warehouses aw ON aw.id = st.warehouse_id WHERE aw.station_id = ? AND aw.is_active = 1 AND st.archived = 0 AND sd.archived = 0), 0) AS audit_items,
                          COALESCE((SELECT AVG(ABS(sd.variance_value)) FROM stocktake_details sd JOIN stocktakes st ON st.id = sd.stocktake_id JOIN warehouses aw ON aw.id = st.warehouse_id WHERE aw.station_id = ? AND aw.is_active = 1 AND st.archived = 0 AND sd.archived = 0), 0) AS audit_variance
                   FROM stock_alerts a
                   LEFT JOIN products p ON p.id = a.product_id
                   WHERE a.station_id = ?""",
                arrayOf(stationScopeId.toString(), stationScopeId.toString(), stationScopeId.toString())
            ).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject() }
            JSONObject().apply {
                put("rows", enrichedRows)
                put("records", enrichedRows)
                put("total_count", report.optInt("total_count", 0))
                put("page", report.optInt("page", 1))
                put("page_size", report.optInt("page_size", 200))
                put("total_pages", report.optInt("total_pages", 0))
                put("has_next", report.optBoolean("has_next", false))
                put("has_previous", report.optBoolean("has_previous", false))
                put("statistics", statistics)
                put("critical_count", statistics.optInt("critical_count", 0))
                put("expiring_count", statistics.optInt("expiring_count", 0))
                put("expiring_value", statistics.optDouble("expiring_value", 0.0))
                put("audit_items", statistics.optInt("audit_items", 0))
                put("audit_variance", statistics.optDouble("audit_variance", 0.0))
                put("unresolved_count", statistics.optInt("unresolved_count", 0))
            }
        } finally {
            dbLock.unlock()
        }
    }

    private fun validateEmployeeRecord(data: JSONObject) {
        val email = data.optString("email", "").trim()
        require(email.isBlank() || android.util.Patterns.EMAIL_ADDRESS.matcher(email).matches()) { "البريد الإلكتروني غير صالح" }
        val status = data.optString("status", "active").trim()
        require(status in setOf("active", "on_leave", "suspended", "terminated")) { "حالة الموظف غير صالحة" }
        if (status == "terminated") require(data.optString("termination_date", "").isNotBlank()) { "تاريخ انتهاء الخدمة مطلوب للموظف المسرح" }
        val department = data.optString("department", "").trim()
        val job = data.optString("job_title", "").trim()
        require(department.isNotBlank() && job.isNotBlank()) { "القسم والمسمى الوظيفي مطلوبان" }
    }

    fun saveEmployeePerformance(input: JSONObject, actorId: Long): Long {
        val employeeId = input.optLong("employee_id", 0L); require(employeeId > 0L) { "معرف الموظف مطلوب" }
        val month = input.optString("review_month", "").trim(); require(month.matches(Regex("\\d{4}-\\d{2}"))) { "شهر التقييم غير صالح" }
        val score = input.optDouble("score", -1.0); require(score in 1.0..5.0) { "التقييم يجب أن يكون بين 1 و5" }
        dbLock.lock(); return try {
            val values = ContentValues().apply { put("uuid", UUID.randomUUID().toString()); put("employee_id", employeeId); put("review_month", month); put("score", score);
                if (input.has("discipline")) put("discipline", input.optDouble("discipline")); if (input.has("productivity")) put("productivity", input.optDouble("productivity")); if (input.has("teamwork")) put("teamwork", input.optDouble("teamwork"));
                put("goals", input.optString("goals")); put("notes", input.optString("notes")); put("status", input.optString("status", "draft")); if (actorId > 0) put("created_by", actorId); put("updated_at", getCurrentDateTime()) }
            val id = writableDatabase.insertWithOnConflict("employee_performance", null, values, SQLiteDatabase.CONFLICT_REPLACE); require(id > 0) { "تعذر حفظ تقييم الأداء" }; id
        } finally { dbLock.unlock() }
    }

    fun getEmployeePerformance(employeeId: Long = 0L, month: String = ""): JSONArray {
        dbLock.lock(); return try { val where = mutableListOf("1=1"); val args = mutableListOf<String>(); if (employeeId > 0) { where += "employee_id=?"; args += employeeId.toString() }; if (month.isNotBlank()) { where += "review_month=?"; args += month };
            readableDatabase.rawQuery("SELECT * FROM employee_performance WHERE ${where.joinToString(" AND ")} ORDER BY review_month DESC, id DESC", args.toTypedArray()).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    fun saveOperationalRecord(screenKey: String, input: JSONObject, actorId: Long = 0L): Long {
        if (screenKey == "tank_refills") return saveTankRefillRecord(input, input.optInt("station_id", 0), actorId)
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        val data = operationalPreparedData(screenKey, input, actorId)
        if (screenKey == "attendance") validateAttendanceRecord(data)
        if (screenKey == "employees") validateEmployeeRecord(data)
        requireOperationalData(spec, data)
        validateFleetRecord(screenKey, data)
        if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests", "calibration_records")) validateModule006Record(screenKey, data)
        dbLock.lock()
        return try {
            val values = ContentValues()
            for (key in spec.columns) if (data.has(key)) putOperationalValue(values, key, data.opt(key))
            if (operationalHasUuid(spec.table)) putOperationalValue(values, "uuid", data.optString("uuid", UUID.randomUUID().toString()))
            if (operationalHasCreatedAt(spec.table) && !data.has("created_at")) values.put("created_at", getCurrentDateTime())
            if (spec.hasUpdatedAt && !data.has("updated_at")) values.put("updated_at", getCurrentDateTime())
            if (screenKey == "vehicle_trips") {
                val now = getCurrentDateTime()
                values.put("trip_status", "scheduled")
                values.put("scheduled_at", now)
                values.put("updated_at", now)
            }
            val writeDb = writableDatabase
            val stationId = data.optInt("station_id", 0)
            if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests")) require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
            if (screenKey in setOf("vehicles", "drivers", "vehicle_locations", "vehicle_trips", "vehicle_expenses", "vehicle_maintenance", "vehicle_insurance")) {
                require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
                requireFleetRelationsInStation(writeDb, screenKey, data, stationId)
            }
            if (screenKey in setOf("price_lists", "price_history", "price_list_items", "calibration_records")) require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
            if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests")) requireModule006RelationsInStation(writeDb, screenKey, data, stationId)
            if (screenKey == "calibration_records") requireCalibrationEntityInStation(writeDb, data, stationId)
            if (screenKey == "bad_debts" && stationId > 0) requirePartyInStation(writeDb, data.optLong("customer_id", 0L), stationId)
            if (screenKey == "price_history" && stationId > 0) writeDb.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("product_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة" } }
            if (screenKey == "price_list_items" && stationId > 0) writeDb.rawQuery("SELECT id FROM price_lists WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("price_list_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "قائمة الأسعار خارج نطاق المحطة" } }
            if (screenKey == "tank_level_log" && stationId > 0) writeDb.rawQuery("SELECT id FROM tanks WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("tank_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الخزان خارج نطاق المحطة" } }
            if (screenKey == "fuel_quality_tests" && stationId > 0) writeDb.rawQuery("SELECT tr.id FROM tank_refills tr JOIN tanks t ON t.id = tr.tank_id WHERE tr.id = ? AND t.station_id = ? AND t.is_deleted = 0", arrayOf(data.optLong("refill_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "سجل التعبئة خارج نطاق المحطة" } }
            if (screenKey == "stocktakes" && stationId > 0) writeDb.rawQuery("SELECT id FROM warehouses WHERE id = ? AND station_id = ? AND is_active = 1", arrayOf(data.optLong("warehouse_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المستودع خارج نطاق المحطة أو غير نشط" } }
            if (screenKey == "stocktake_details" && stationId > 0) writeDb.rawQuery("SELECT st.id FROM stocktakes st JOIN warehouses w ON w.id = st.warehouse_id WHERE st.id = ? AND w.station_id = ? AND w.is_active = 1 AND st.archived = 0", arrayOf(data.optLong("stocktake_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الجرد خارج نطاق المحطة" } }
            val id = writeDb.insertOrThrow(spec.table, null, values)
            if (id > 0) {
                if (screenKey == "vehicle_trips") {
                    writeDb.insertOrThrow("vehicle_trip_events", null, ContentValues().apply {
                        put("uuid", UUID.randomUUID().toString()); put("trip_id", id); put("event_type", "created")
                        put("event_note", "تم إنشاء سجل الرحلة"); put("occurred_at", getCurrentDateTime())
                        if (actorId > 0L) put("created_by", actorId)
                    })
                }
                if (screenKey == "attendance") logOperationalAudit(screenKey, "create", id, actorId, null, operationalRowJson(screenKey, id))
                else { logActivity("system", "add_${spec.table}", "إضافة سجل في ${spec.table}: $id"); if (screenKey == "employees") logEmployeeAudit(id, "create", actorId, null, operationalRowJson(screenKey, id), "") }
            }
            id
        } finally { dbLock.unlock() }
    }

    fun updateOperationalRecord(screenKey: String, id: Long, input: JSONObject, actorId: Long = 0L): Int {
        if (screenKey == "tank_refills") return updateTankRefillRecord(id, input, input.optInt("station_id", 0), actorId)
        require(id > 0L) { "معرف السجل غير صالح" }
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        val data = operationalPreparedData(screenKey, input, actorId)
        if (screenKey in setOf("vehicles", "drivers") && !input.has(if (screenKey == "vehicles") "vehicle_code" else "driver_code")) {
            data.remove(if (screenKey == "vehicles") "vehicle_code" else "driver_code")
        }
        if (screenKey in setOf("vehicles", "drivers", "vehicle_locations", "vehicle_trips", "vehicle_expenses", "vehicle_maintenance", "vehicle_insurance")) {
            val existing = fleetDataForExisting(readableDatabase, screenKey, input, id)
            existing.keys().forEach { key -> if (!data.has(key)) data.put(key, existing.opt(key)) }
        }
        if (screenKey == "attendance") validateAttendanceRecord(data, id)
        if (screenKey == "employees") validateEmployeeRecord(data)
        validateFleetRecord(screenKey, data)
        if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests", "calibration_records")) validateModule006Record(screenKey, data)
        dbLock.lock()
        return try {
            val oldRow = if (screenKey in setOf("attendance", "employees")) operationalRowJson(screenKey, id) else null
            val values = ContentValues()
            for (key in spec.columns) if (data.has(key) && key != "created_by") putOperationalValue(values, key, data.opt(key))
            if (spec.hasUpdatedAt) values.put("updated_at", getCurrentDateTime())
            val stationId = data.optInt("station_id", 0)
            if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests")) require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
            val fleetScope = if (stationId > 0) fleetStationPredicate(screenKey, stationId) else null
            if (screenKey in setOf("vehicles", "drivers", "vehicle_locations", "vehicle_trips", "vehicle_expenses", "vehicle_maintenance", "vehicle_insurance")) {
                require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
                requireFleetRelationsInStation(writableDatabase, screenKey, data, stationId)
            }
            if (screenKey in setOf("price_lists", "price_history", "price_list_items", "calibration_records")) require(stationId > 0) { "معرف المحطة مطلوب لهذا المسار" }
            if (screenKey in setOf("tanks", "pumps", "meter_readings", "tank_level_log", "fuel_quality_tests")) requireModule006RelationsInStation(writableDatabase, screenKey, data, stationId)
            if (screenKey == "calibration_records") requireCalibrationEntityInStation(writableDatabase, data, stationId, id)
            if (screenKey == "bad_debts" && stationId > 0) requirePartyInStation(writableDatabase, data.optLong("customer_id", 0L), stationId)
            if (screenKey == "price_history" && stationId > 0 && data.has("product_id")) writableDatabase.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("product_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المنتج خارج نطاق المحطة" } }
            if (screenKey == "price_list_items" && stationId > 0 && data.has("price_list_id")) writableDatabase.rawQuery("SELECT id FROM price_lists WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("price_list_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "قائمة الأسعار خارج نطاق المحطة" } }
            if (screenKey == "tank_level_log" && stationId > 0 && data.has("tank_id")) writableDatabase.rawQuery("SELECT id FROM tanks WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(data.optLong("tank_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "الخزان خارج نطاق المحطة" } }
            if (screenKey == "fuel_quality_tests" && stationId > 0 && data.has("refill_id")) writableDatabase.rawQuery("SELECT tr.id FROM tank_refills tr JOIN tanks t ON t.id = tr.tank_id WHERE tr.id = ? AND t.station_id = ? AND t.is_deleted = 0", arrayOf(data.optLong("refill_id", 0L).toString(), stationId.toString())).use { cursor -> require(cursor.moveToFirst()) { "سجل التعبئة خارج نطاق المحطة" } }
            val directScope = spec.columns.contains("station_id") && stationId > 0 && screenKey != "calibration_records" && fleetScope == null
            val relationalScope = stationId > 0 && (screenKey in setOf("bad_debts", "stocktakes", "stocktake_details", "price_history", "price_list_items", "tank_level_log", "fuel_quality_tests", "calibration_records") || fleetScope != null)
            val scope = when {
                fleetScope != null -> " AND $fleetScope"
                directScope -> " AND station_id = ?"
                screenKey == "calibration_records" && relationalScope -> " AND " + calibrationStationPredicate(stationId)
                screenKey == "bad_debts" && relationalScope -> " AND EXISTS (SELECT 1 FROM parties party WHERE party.id = bad_debts.customer_id AND party.station_id = ${stationId} AND party.is_deleted = 0)"
                screenKey == "stocktakes" && relationalScope -> " AND EXISTS (SELECT 1 FROM warehouses scope_w WHERE scope_w.id = stocktakes.warehouse_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1)"
                screenKey == "stocktake_details" && relationalScope -> " AND EXISTS (SELECT 1 FROM stocktakes scope_st JOIN warehouses scope_w ON scope_w.id = scope_st.warehouse_id WHERE scope_st.id = stocktake_details.stocktake_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1 AND scope_st.archived = 0)"
                screenKey == "price_history" && relationalScope -> " AND EXISTS (SELECT 1 FROM products scope_p WHERE scope_p.id = price_history.product_id AND scope_p.station_id = ${stationId} AND scope_p.is_deleted = 0)"
                screenKey == "price_list_items" && relationalScope -> " AND EXISTS (SELECT 1 FROM price_lists scope_pl WHERE scope_pl.id = price_list_items.price_list_id AND scope_pl.station_id = ${stationId} AND scope_pl.is_deleted = 0)"
                screenKey == "tank_level_log" && relationalScope -> " AND EXISTS (SELECT 1 FROM tanks scope_t WHERE scope_t.id = tank_level_log.tank_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                screenKey == "fuel_quality_tests" && relationalScope -> " AND EXISTS (SELECT 1 FROM tank_refills scope_tr JOIN tanks scope_t ON scope_t.id = scope_tr.tank_id WHERE scope_tr.id = fuel_quality_tests.refill_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                else -> ""
            }
            val where = (if (spec.softDeleted) "id = ? AND is_deleted = 0" else "id = ?") + scope
            val whereArgs = if (directScope) arrayOf(id.toString(), stationId.toString()) else arrayOf(id.toString())
            val rows = writableDatabase.update(spec.table, values, where, whereArgs)
            if (rows > 0) {
                if (screenKey == "attendance") logOperationalAudit(screenKey, "update", id, actorId, oldRow, operationalRowJson(screenKey, id))
                else { logActivity("system", "update_${spec.table}", "تحديث سجل ${spec.table}: $id"); if (screenKey == "employees") logEmployeeAudit(id, "update", actorId, oldRow, operationalRowJson(screenKey, id), "") }
            }
            rows
        } finally { dbLock.unlock() }
    }

    fun deleteOperationalRecord(screenKey: String, id: Long, actorId: Long = 0L, stationId: Int? = null): Int {
        if (screenKey == "tank_refills") return deleteTankRefillRecord(id, stationId ?: 0)
        require(id > 0L) { "معرف السجل غير صالح" }
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        dbLock.lock()
        return try {
            val db = writableDatabase
            val oldRow = if (screenKey in setOf("attendance", "employees")) operationalRowJson(screenKey, id) else null
            val fleetScope = if (stationId != null && stationId > 0) fleetStationPredicate(screenKey, stationId) else null
            val scoped = stationId != null && stationId > 0 && spec.columns.contains("station_id") && screenKey != "calibration_records" && fleetScope == null
            val relationallyScoped = stationId != null && stationId > 0 && (screenKey in setOf("bad_debts", "stocktakes", "stocktake_details", "price_history", "price_list_items", "tank_level_log", "fuel_quality_tests", "calibration_records") || fleetScope != null)
            val where = when {
                fleetScope != null -> "id = ? AND $fleetScope"
                scoped -> "id = ? AND station_id = ?"
                screenKey == "calibration_records" && relationallyScoped -> "id = ? AND " + calibrationStationPredicate(stationId!!)
                screenKey == "bad_debts" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM parties party WHERE party.id = bad_debts.customer_id AND party.station_id = ${stationId} AND party.is_deleted = 0)"
                screenKey == "stocktakes" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM warehouses scope_w WHERE scope_w.id = stocktakes.warehouse_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1)"
                screenKey == "stocktake_details" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM stocktakes scope_st JOIN warehouses scope_w ON scope_w.id = scope_st.warehouse_id WHERE scope_st.id = stocktake_details.stocktake_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1 AND scope_st.archived = 0)"
                screenKey == "price_history" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM products scope_p WHERE scope_p.id = price_history.product_id AND scope_p.station_id = ${stationId} AND scope_p.is_deleted = 0)"
                screenKey == "price_list_items" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM price_lists scope_pl WHERE scope_pl.id = price_list_items.price_list_id AND scope_pl.station_id = ${stationId} AND scope_pl.is_deleted = 0)"
                screenKey == "tank_level_log" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM tanks scope_t WHERE scope_t.id = tank_level_log.tank_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                screenKey == "fuel_quality_tests" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM tank_refills scope_tr JOIN tanks scope_t ON scope_t.id = scope_tr.tank_id WHERE scope_tr.id = fuel_quality_tests.refill_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                else -> "id = ?"
            }
            val whereArgs = if (scoped) arrayOf(id.toString(), stationId.toString()) else arrayOf(id.toString())
            val rows = if (spec.softDeleted) db.update(spec.table, ContentValues().apply {
                put("is_deleted", 1)
                if (tableHasColumn(db, spec.table, "deleted_at")) put("deleted_at", getCurrentDateTime())
                if (tableHasColumn(db, spec.table, "deleted_by")) {
                    if (actorId > 0L) put("deleted_by", actorId) else putNull("deleted_by")
                }
                if (spec.hasUpdatedAt) put("updated_at", getCurrentDateTime())
            }, where, whereArgs) else db.delete(spec.table, where, whereArgs)
            if (rows > 0) {
                if (screenKey == "attendance") logOperationalAudit(screenKey, "delete", id, actorId, oldRow, operationalRowJson(screenKey, id))
                else { logActivity("system", "archive_${spec.table}", "أرشفة سجل ${spec.table}: $id"); if (screenKey == "employees") logEmployeeAudit(id, "archive", actorId, oldRow, operationalRowJson(screenKey, id), "أرشفة من شاشة الموظفين") }
            }
            rows
        } finally { dbLock.unlock() }
    }

    fun restoreOperationalRecord(screenKey: String, id: Long, actorId: Long = 0L, stationId: Int? = null): Int {
        require(id > 0L) { "معرف السجل غير صالح" }
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        require(spec.softDeleted) { "هذا المسار لا يدعم الاستعادة" }
        dbLock.lock()
        return try {
            val db = writableDatabase
            val stationScope = stationId != null && stationId > 0
            val fleetScope = if (stationScope) fleetStationPredicate(screenKey, stationId!!) else null
            val directScope = stationScope && spec.columns.contains("station_id") && fleetScope == null
            val where = when {
                fleetScope != null -> "id = ? AND is_deleted = 1 AND $fleetScope"
                directScope -> "id = ? AND is_deleted = 1 AND station_id = ?"
                else -> "id = ? AND is_deleted = 1"
            }
            val args = if (directScope) arrayOf(id.toString(), stationId.toString()) else arrayOf(id.toString())
            val values = ContentValues().apply {
                put("is_deleted", 0)
                if (tableHasColumn(db, spec.table, "deleted_at")) putNull("deleted_at")
                if (tableHasColumn(db, spec.table, "deleted_by")) putNull("deleted_by")
                if (spec.hasUpdatedAt) put("updated_at", getCurrentDateTime())
            }
            val rows = db.update(spec.table, values, where, args)
            if (rows > 0) logActivity("system", "restore_${spec.table}", "استعادة سجل ${spec.table}: $id")
            rows
        } finally { dbLock.unlock() }
    }

    fun resolveOperationalRecord(screenKey: String, id: Long, note: String = "", actorId: Long = 0L, stationId: Int? = null): Int {
        require(id > 0L) { "معرف السجل غير صالح" }
        val spec = operationalSpec(screenKey) ?: error("مسار الشاشة غير مسجل: $screenKey")
        dbLock.lock()
        return try {
            val db = writableDatabase
            val oldRow = if (screenKey == "attendance") operationalRowJson(screenKey, id) else null
            val values = ContentValues()
            val fleetScope = if (stationId != null && stationId > 0) fleetStationPredicate(screenKey, stationId) else null
            val scoped = stationId != null && stationId > 0 && spec.columns.contains("station_id") && screenKey != "calibration_records" && fleetScope == null
            val relationallyScoped = stationId != null && stationId > 0 && (screenKey in setOf("bad_debts", "stocktakes", "stocktake_details", "price_history", "price_list_items", "tank_level_log", "fuel_quality_tests", "calibration_records") || fleetScope != null)
            val where = when {
                fleetScope != null -> "id = ? AND $fleetScope"
                scoped -> "id = ? AND station_id = ?"
                screenKey == "calibration_records" && relationallyScoped -> "id = ? AND " + calibrationStationPredicate(stationId!!)
                screenKey == "bad_debts" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM parties party WHERE party.id = bad_debts.customer_id AND party.station_id = ${stationId} AND party.is_deleted = 0)"
                screenKey == "stocktakes" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM warehouses scope_w WHERE scope_w.id = stocktakes.warehouse_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1)"
                screenKey == "stocktake_details" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM stocktakes scope_st JOIN warehouses scope_w ON scope_w.id = scope_st.warehouse_id WHERE scope_st.id = stocktake_details.stocktake_id AND scope_w.station_id = ${stationId} AND scope_w.is_active = 1 AND scope_st.archived = 0)"
                screenKey == "price_history" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM products scope_p WHERE scope_p.id = price_history.product_id AND scope_p.station_id = ${stationId} AND scope_p.is_deleted = 0)"
                screenKey == "price_list_items" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM price_lists scope_pl WHERE scope_pl.id = price_list_items.price_list_id AND scope_pl.station_id = ${stationId} AND scope_pl.is_deleted = 0)"
                screenKey == "tank_level_log" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM tanks scope_t WHERE scope_t.id = tank_level_log.tank_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                screenKey == "fuel_quality_tests" && relationallyScoped -> "id = ? AND EXISTS (SELECT 1 FROM tank_refills scope_tr JOIN tanks scope_t ON scope_t.id = scope_tr.tank_id WHERE scope_tr.id = fuel_quality_tests.refill_id AND scope_t.station_id = ${stationId} AND scope_t.is_deleted = 0)"
                else -> "id = ?"
            }
            val whereArgs = if (scoped) arrayOf(id.toString(), stationId.toString()) else arrayOf(id.toString())
            when (screenKey) {
                "attendance" -> { if (actorId > 0L) values.put("approved_by", actorId); values.put("approved_at", getCurrentDateTime()); if (note.isNotBlank()) values.put("notes", note) }
                "bad_debts" -> { values.put("resolved", 1); values.put("resolved_date", getCurrentDateTime()) }
                "stock_alerts" -> { values.put("is_resolved", 1); values.put("resolved_at", getCurrentDateTime()); values.put("resolution_notes", note) }
                "maintenance_requests" -> { values.put("status", "completed"); values.put("completed_at", getCurrentDateTime()); values.put("resolution", note) }
                "sync_logs" -> { values.put("status", "success"); values.put("completed_at", getCurrentDateTime()) }
                else -> error("لا توجد عملية اعتماد/حل مدعومة لهذه الشاشة")
            }
            if (spec.hasUpdatedAt) values.put("updated_at", getCurrentDateTime())
            val rows = db.update(spec.table, values, where, whereArgs)
            if (rows > 0 && screenKey == "attendance") logOperationalAudit(screenKey, "approve", id, actorId, oldRow, operationalRowJson(screenKey, id), note)
            rows
        } finally { dbLock.unlock() }
    }

