    fun getSalesByFuelType(): JSONArray {
        val arr = JSONArray()
        val db = readableDatabase
        db.rawQuery("""
            SELECT f.fuel_name, f.fuel_name_ar,
                   COALESCE(SUM(s.liters), 0) as total_liters,
                   COALESCE(SUM(s.net_amount), 0) as total_amount,
                   COUNT(*) as transaction_count
            FROM fuel_types f
            LEFT JOIN sales_transactions s ON s.fuel_type_id = f.id AND s.is_deleted = 0
            WHERE f.is_deleted = 0
            GROUP BY f.id
            ORDER BY total_amount DESC
        """.trimIndent(), null).use { cursor ->
            while (cursor.moveToNext()) {
                arr.put(JSONObject().apply {
                    put("fuel_name", cursor.getString(0))
                    put("fuel_name_ar", cursor.getString(1))
                    put("total_liters", cursor.getDouble(2))
                    put("total_amount", cursor.getDouble(3))
                    put("transaction_count", cursor.getInt(4))
                })
            }
        }
        return arr
    }

    fun getCustomerCount(stationScopeId: Int? = null): Int {
        if (stationScopeId != null) require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        val db = readableDatabase
        val stationClause = if (stationScopeId != null) " AND p.station_id = ?" else ""
        val args = if (stationScopeId != null) arrayOf(stationScopeId.toString()) else null
        db.rawQuery("""
            SELECT COUNT(*) FROM parties p
            WHERE p.is_deleted = 0
              AND p.party_type_id IN (SELECT id FROM party_types WHERE type_code IN ('INDIVIDUAL','COMPANY','GOVERNMENT','TRANSPORT','CONTRACTOR') AND is_deleted=0)
              $stationClause
        """.trimIndent(), args).use { cursor ->
            if (cursor.moveToFirst()) return cursor.getInt(0)
        }
        return 0
    }

    fun getDriverPhonesList(): JSONArray {
        val arr = JSONArray()
        getDriverPhones().forEach { arr.put(it) }
        return arr
    }

