    /**
     * Serverless pagination/filter contract for WebView screens.
     * All values are bound parameters; no SQL identifiers or user input are interpolated.
     */
    fun getSmsMessagesPage(params: JSONObject = JSONObject(), stationScopeId: Int = -1): JSONObject {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val limit = params.optInt("limit", 50).coerceIn(1, 200)
            val offset = params.optInt("offset", 0).coerceAtLeast(0)
            val where = mutableListOf<String>()
            val args = mutableListOf<String>()
            if (stationScopeId > 0) {
                where += "(sm.party_id IS NULL OR sm.party_id IN (SELECT id FROM parties WHERE station_id = ?))"
                args += stationScopeId.toString()
            }

            val status = params.optString("status", "").trim().lowercase(Locale.ROOT)
            val messageType = params.optString("message_type", "").trim().lowercase(Locale.ROOT)
            val dateFrom = params.optString("date_from", "").trim()
            val dateTo = params.optString("date_to", "").trim()
            val search = params.optString("search", "").trim()
            if (search.isNotBlank()) {
                where += "(phone_number LIKE ? OR message_body LIKE ?)"
                val like = "%$search%"
                args += like
                args += like
            }
            if (status == "read") {
                where += "is_read = 1"
            } else if (status == "unread") {
                where += "is_read = 0"
            } else if (status.isNotBlank()) {
                where += "status = ?"
                args += status
            }
            if (messageType.isNotBlank()) {
                where += "message_type = ?"
                args += messageType
            }
            if (dateFrom.isNotBlank()) {
                where += "date(created_at) >= date(?)"
                args += dateFrom
            }
            if (dateTo.isNotBlank()) {
                where += "date(created_at) <= date(?)"
                args += dateTo
            }

            val whereSql = if (where.isEmpty()) "" else " WHERE " + where.joinToString(" AND ")
            val count = db.rawQuery("SELECT COUNT(*) FROM sms_messages$whereSql", args.toTypedArray()).use { cursor ->
                if (cursor.moveToFirst()) cursor.getInt(0) else 0
            }
            val pageArgs = args.toMutableList().apply {
                add(limit.toString())
                add(offset.toString())
            }
            val projection = "sm.id, sm.uuid, sm.phone_number, sm.message_body, sm.message_type, sm.status, sm.is_read, sm.party_id, sm.error_message, sm.retry_count, sm.created_at, sm.updated_at, sm.processed_at"
            val items = db.rawQuery(
                "SELECT $projection, ${smsOwnerNameSelect("sm")} AS owner_name, (SELECT suggested_state FROM sms_cognitive_plans WHERE conversation_id = sm.phone_number ORDER BY created_at DESC LIMIT 1) as cognitive_state FROM sms_messages sm$whereSql ORDER BY sm.created_at DESC, sm.id DESC LIMIT ? OFFSET ?",
                pageArgs.toTypedArray()
            ).use { cursor -> cursorToJsonArray(cursor) }
            JSONObject().apply {
                put("items", items)
                put("total", count)
                put("limit", limit)
                put("offset", offset)
            }
        } finally {
            dbLock.unlock()
        }
    }

