    fun getSmsMessagesByPhone(phone: String, stationScopeId: Int = -1): JSONArray {
        val national = smsNationalPhone(phone)
        dbLock.lock()
        return try {
            val db = readableDatabase
            if (national == null) return JSONArray()
            val phoneExpr = "substr(replace(replace(replace(replace(replace(COALESCE(phone_number, ''), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), -9)"
            val scopeSql = if (stationScopeId > 0) " AND (sm.party_id IS NULL OR sm.party_id IN (SELECT id FROM parties WHERE station_id = $stationScopeId))" else ""
            db.rawQuery(
                "SELECT sm.*, (SELECT suggested_state FROM sms_cognitive_plans WHERE conversation_id = sm.phone_number ORDER BY created_at DESC LIMIT 1) as cognitive_state FROM sms_messages sm WHERE $phoneExpr = ?$scopeSql ORDER BY created_at DESC",
                arrayOf(national)
            ).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

