    fun getSmsStats(stationScopeId: Int = -1): JSONObject {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val stats = JSONObject()
            val scopeSql = if (stationScopeId > 0) " WHERE (party_id IS NULL OR party_id IN (SELECT id FROM parties WHERE station_id = $stationScopeId))" else ""
            val andScopeSql = if (stationScopeId > 0) " AND (party_id IS NULL OR party_id IN (SELECT id FROM parties WHERE station_id = $stationScopeId))" else ""
            db.rawQuery("SELECT COUNT(*) FROM sms_messages$scopeSql", null).use { cursor ->
                stats.put("total", if (cursor.moveToFirst()) cursor.getInt(0) else 0)
            }
            db.rawQuery("SELECT COUNT(*) FROM sms_messages WHERE status = 'sent'$andScopeSql", null).use { cursor ->
                stats.put("sent", if (cursor.moveToFirst()) cursor.getInt(0) else 0)
            }
            db.rawQuery("SELECT COUNT(*) FROM sms_messages WHERE status = 'pending'$andScopeSql", null).use { cursor ->
                stats.put("pending", if (cursor.moveToFirst()) cursor.getInt(0) else 0)
            }
            db.rawQuery("SELECT COUNT(*) FROM sms_messages WHERE status = 'failed'$andScopeSql", null).use { cursor ->
                stats.put("failed", if (cursor.moveToFirst()) cursor.getInt(0) else 0)
            }
            stats
        } finally {
            dbLock.unlock()
        }
    }

