    fun getWarehousesPage(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        dbLock.lock()
        return try {
            val db = readableDatabase
            val conditions = mutableListOf("w.station_id = ?")
            val args = mutableListOf(stationScopeId.toString())
            val status = data.optString("status").trim()
            if (status == "active") conditions += "w.is_active = 1"
            if (status == "inactive") conditions += "w.is_active = 0"
            data.optString("search", data.optString("query", "")).trim().takeIf { it.isNotEmpty() }?.let {
                conditions += "(w.warehouse_name LIKE ? OR w.location_details LIKE ?)"
                val pattern = "%$it%"; args += pattern; args += pattern
            }
            val whereSql = conditions.joinToString(" AND ")
            val totalCount = db.rawQuery("SELECT COUNT(*) FROM warehouses w WHERE $whereSql", args.toTypedArray()).use { if (it.moveToFirst()) it.getInt(0) else 0 }
            val pageSize = data.optInt("limit", 20).coerceIn(1, 200)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val sortColumn = when (data.optString("sort_by", "warehouse_name")) {
                "location_details" -> "w.location_details"
                "is_active" -> "w.is_active"
                "created_at" -> "w.created_at"
                "total_quantity" -> "total_quantity"
                else -> "w.warehouse_name"
            }
            val direction = if (data.optString("sort_dir", "asc").equals("desc", true)) "DESC" else "ASC"
            val rows = db.rawQuery("""
                SELECT w.id, w.uuid, w.station_id, w.warehouse_name, w.location_details, w.is_default, w.is_active, w.created_at,
                       COUNT(DISTINCT il.product_id) AS total_products,
                       COALESCE(SUM(il.quantity_on_hand), 0) AS total_quantity,
                       MAX(im.created_at) AS last_movement
                FROM warehouses w
                LEFT JOIN inventory_levels il ON il.warehouse_id = w.id
                LEFT JOIN inventory_movements im ON im.warehouse_id = w.id AND im.station_id = w.station_id AND im.is_deleted = 0
                WHERE $whereSql
                GROUP BY w.id
                ORDER BY $sortColumn $direction, w.id ASC
                LIMIT ? OFFSET ?
            """.trimIndent(), (args + pageSize.toString() + offset.toString()).toTypedArray()).use { cursorToJsonArray(it) }
            val stats = db.rawQuery("""
                SELECT COUNT(*) AS total_warehouses,
                       COALESCE(SUM(CASE WHEN w.is_active = 1 THEN 1 ELSE 0 END), 0) AS active_warehouses,
                       COALESCE(SUM(CASE WHEN w.is_active = 0 THEN 1 ELSE 0 END), 0) AS inactive_warehouses,
                       COUNT(DISTINCT il.product_id) AS total_products,
                       COALESCE(SUM(il.quantity_on_hand), 0) AS total_quantity
                FROM warehouses w LEFT JOIN inventory_levels il ON il.warehouse_id = w.id
                WHERE w.station_id = ?
            """.trimIndent(), arrayOf(stationScopeId.toString())).use { if (it.moveToFirst()) cursorToJsonObject(it) else JSONObject() }
            val page = (offset / pageSize) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + pageSize - 1) / pageSize
            JSONObject().apply {
                put("rows", rows); put("count", rows.length()); put("total_count", totalCount)
                put("page", page); put("page_size", pageSize); put("total_pages", totalPages)
                put("has_next", page < totalPages); put("has_previous", page > 1); put("stats", stats)
            }
        } finally { dbLock.unlock() }
    }

    fun getWarehouses(stationId: Int? = null): JSONArray {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val sql = if (stationId != null && stationId > 0) {
                "SELECT id, uuid, station_id, warehouse_name, location_details, is_default, is_active, created_at FROM warehouses WHERE station_id = ? AND is_active = 1 ORDER BY warehouse_name"
            } else {
                "SELECT id, uuid, station_id, warehouse_name, location_details, is_default, is_active, created_at FROM warehouses WHERE is_active = 1 ORDER BY warehouse_name"
            }
            val args = if (stationId != null && stationId > 0) arrayOf(stationId.toString()) else null
            db.rawQuery(sql, args).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

    fun getDamagedProductsPage(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        dbLock.lock()
        return try {
            val db = readableDatabase
            val conditions = mutableListOf("dp.station_id = ?", "p.station_id = ?")
            val args = mutableListOf(stationScopeId.toString(), stationScopeId.toString())
            if (!data.optBoolean("include_archived", false)) conditions += "dp.archived = 0"
            data.optString("from_date", data.optString("start_date", "")).trim().takeIf { it.isNotEmpty() }?.let { conditions += "date(dp.report_date) >= date(?)"; args += it }
            data.optString("to_date", data.optString("end_date", "")).trim().takeIf { it.isNotEmpty() }?.let { conditions += "date(dp.report_date) <= date(?)"; args += it }
            data.optLong("product_id", 0L).takeIf { it > 0 }?.let { conditions += "dp.product_id = ?"; args += it.toString() }
            data.optLong("warehouse_id", 0L).takeIf { it > 0 }?.let { conditions += "dp.warehouse_id = ?"; args += it.toString() }
            data.optString("status").trim().takeIf { it in setOf("pending", "approved", "rejected") }?.let { conditions += "dp.status = ?"; args += it }
            data.optString("search", data.optString("query", "")).trim().takeIf { it.isNotEmpty() }?.let {
                conditions += "(dp.reason LIKE ? OR dp.notes LIKE ? OR p.product_code LIKE ? OR p.product_name LIKE ? OR w.warehouse_name LIKE ?)"
                val pattern = "%$it%"; repeat(5) { args += pattern }
            }
            val whereSql = conditions.joinToString(" AND ")
            val totalCount = db.rawQuery("SELECT COUNT(*) FROM damaged_products dp LEFT JOIN products p ON p.id=dp.product_id LEFT JOIN warehouses w ON w.id=dp.warehouse_id WHERE $whereSql", args.toTypedArray()).use { if (it.moveToFirst()) it.getInt(0) else 0 }
            val pageSize = data.optInt("limit", 20).coerceIn(1, 200)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val sortColumn = when (data.optString("sort_by", "report_date")) {
                "quantity" -> "dp.quantity"
                "status" -> "dp.status"
                "product" -> "p.product_name"
                "warehouse" -> "w.warehouse_name"
                else -> "datetime(dp.report_date)"
            }
            val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
            val rows = db.rawQuery("""
                SELECT dp.id, dp.product_id, dp.warehouse_id, dp.tank_id, dp.station_id, dp.quantity, dp.reason, dp.notes,
                       dp.report_date, dp.reported_by, dp.status, dp.approved_by, dp.approved_at, dp.archived, dp.created_at,
                       p.product_code, p.product_name, p.product_name_ar, COALESCE(p.purchase_price,0) AS unit_price,
                       COALESCE(p.purchase_price,0) * dp.quantity AS total_value, w.warehouse_name,
                       ru.full_name AS reported_by_name, au.full_name AS approved_by_name
                FROM damaged_products dp
                LEFT JOIN products p ON p.id=dp.product_id
                LEFT JOIN warehouses w ON w.id=dp.warehouse_id
                LEFT JOIN users ru ON ru.id=dp.reported_by
                LEFT JOIN users au ON au.id=dp.approved_by
                WHERE $whereSql
                ORDER BY $sortColumn $direction, dp.id DESC
                LIMIT ? OFFSET ?
            """.trimIndent(), (args + pageSize.toString() + offset.toString()).toTypedArray()).use { cursorToJsonArray(it) }
            val stats = db.rawQuery("SELECT COUNT(*) AS total_count, COALESCE(SUM(dp.quantity),0) AS total_quantity, COALESCE(SUM(CASE WHEN dp.status='pending' THEN 1 ELSE 0 END),0) AS pending_count, COALESCE(SUM(CASE WHEN dp.status='approved' THEN 1 ELSE 0 END),0) AS approved_count, COALESCE(SUM(CASE WHEN dp.status='rejected' THEN 1 ELSE 0 END),0) AS rejected_count, COALESCE(SUM(dp.quantity * COALESCE(p.purchase_price,0)),0) AS total_value FROM damaged_products dp LEFT JOIN products p ON p.id=dp.product_id LEFT JOIN warehouses w ON w.id=dp.warehouse_id WHERE $whereSql", args.toTypedArray()).use { if (it.moveToFirst()) cursorToJsonObject(it) else JSONObject() }
            val page = (offset / pageSize) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + pageSize - 1) / pageSize
            JSONObject().apply { put("rows", rows); put("count", rows.length()); put("total_count", totalCount); put("page", page); put("page_size", pageSize); put("total_pages", totalPages); put("has_next", page < totalPages); put("has_previous", page > 1); put("stats", stats) }
        } finally { dbLock.unlock() }
    }

    fun getDamagedProducts(data: JSONObject, stationScopeId: Int): JSONArray {
        dbLock.lock()
        return try {
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val db = readableDatabase
            val conditions = mutableListOf<String>("dp.station_id = ?")
            val args = mutableListOf<String>(stationScopeId.toString())
            if (!data.optBoolean("include_archived", false)) {
                conditions += "dp.archived = 0"
            }
            data.optString("start_date").trim().takeIf { it.isNotEmpty() }?.let {
                conditions += "date(dp.report_date) >= date(?)"
                args += it
            }
            data.optString("end_date").trim().takeIf { it.isNotEmpty() }?.let {
                conditions += "date(dp.report_date) <= date(?)"
                args += it
            }
            data.optLong("product_id", 0L).takeIf { it > 0 }?.let {
                conditions += "dp.product_id = ?"
                args += it.toString()
            }
            data.optLong("warehouse_id", 0L).takeIf { it > 0 }?.let {
                conditions += "dp.warehouse_id = ?"
                args += it.toString()
            }
            data.optString("status").trim().takeIf { it in setOf("pending", "approved", "rejected") }?.let {
                conditions += "dp.status = ?"
                args += it
            }
            val where = if (conditions.isEmpty()) "" else " WHERE ${conditions.joinToString(" AND ")}"
            val requestedLimit = data.optInt("limit", 0)
            val limit = if (requestedLimit > 0) requestedLimit.coerceAtMost(1000) else 0
            val limitSql = if (limit > 0) " LIMIT $limit" else ""
            val sql = """
                SELECT dp.id, dp.product_id, dp.warehouse_id, dp.tank_id, dp.station_id,
                       dp.quantity, dp.reason, dp.notes, dp.report_date, dp.reported_by,
                       dp.status, dp.approved_by, dp.approved_at, dp.archived, dp.created_at,
                       p.product_code, p.product_name, p.product_name_ar,
                       COALESCE(p.purchase_price, 0) AS unit_price,
                       COALESCE(p.purchase_price, 0) * dp.quantity AS total_value,
                       w.warehouse_name,
                       t.tank_name,
                       ru.full_name AS reported_by_name,
                       au.full_name AS approved_by_name
                FROM damaged_products dp
                LEFT JOIN products p ON p.id = dp.product_id
                LEFT JOIN warehouses w ON w.id = dp.warehouse_id
                LEFT JOIN tanks t ON t.id = dp.tank_id
                LEFT JOIN users ru ON ru.id = dp.reported_by
                LEFT JOIN users au ON au.id = dp.approved_by
                $where
                ORDER BY datetime(dp.report_date) DESC, dp.id DESC$limitSql
            """.trimIndent()
            db.rawQuery(sql, args.toTypedArray()).use { cursor -> cursorToJsonArray(cursor) }
        } finally {
            dbLock.unlock()
        }
    }

    fun addDamagedProduct(data: JSONObject, stationScopeId: Int, reportedBy: Long): Long {
        dbLock.lock()
        return try {
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            require(reportedBy > 0L) { "المبلّغ مطلوب" }
            val productId = data.optLong("product_id", 0L)
            val quantity = data.optDouble("quantity", 0.0)
            require(productId > 0) { "المنتج مطلوب" }
            require(quantity > 0.0) { "الكمية يجب أن تكون أكبر من صفر" }
            val db = writableDatabase
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج غير موجود أو غير نشط" }
            }
            val values = ContentValues().apply {
                put("product_id", productId)
                if (data.optLong("warehouse_id", 0L) > 0) put("warehouse_id", data.optLong("warehouse_id")) else putNull("warehouse_id")
                if (data.optLong("tank_id", 0L) > 0) put("tank_id", data.optLong("tank_id")) else putNull("tank_id")
                put("station_id", stationScopeId)
                put("quantity", quantity)
                put("reason", data.optString("reason").trim())
                put("notes", data.optString("notes").trim())
                if (data.optString("report_date").trim().isNotEmpty()) put("report_date", data.optString("report_date").trim())
                put("reported_by", reportedBy)
                put("status", "pending")
                put("archived", 0)
            }
            val warehouseId = data.optLong("warehouse_id", 0L)
            if (warehouseId > 0L) db.rawQuery("SELECT id FROM warehouses WHERE id = ? AND station_id = ? AND is_active = 1", arrayOf(warehouseId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المستودع خارج نطاق المحطة أو غير نشط" } }
            val id = db.insert("damaged_products", null, values)
            require(id > 0) { "تعذر حفظ سجل التالف" }
            logActivity("system", "damaged_product_created", "تم إنشاء سجل تالف رقم $id")
            id
        } finally {
            dbLock.unlock()
        }
    }

    fun updateDamagedProduct(id: Long, data: JSONObject, stationScopeId: Int): Int {
        dbLock.lock()
        return try {
            require(id > 0) { "معرف السجل غير صالح" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val productId = data.optLong("product_id", 0L)
            val quantity = data.optDouble("quantity", 0.0)
            require(productId > 0) { "المنتج مطلوب" }
            require(quantity > 0.0) { "الكمية يجب أن تكون أكبر من صفر" }
            val db = writableDatabase
            db.rawQuery("SELECT id FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                require(cursor.moveToFirst()) { "المنتج غير موجود أو غير نشط" }
            }
            val values = ContentValues().apply {
                put("product_id", productId)
                if (data.has("warehouse_id")) {
                    if (data.isNull("warehouse_id")) putNull("warehouse_id") else put("warehouse_id", data.optLong("warehouse_id"))
                }
                if (data.has("tank_id")) {
                    if (data.isNull("tank_id")) putNull("tank_id") else put("tank_id", data.optLong("tank_id"))
                }
                put("quantity", quantity)
                put("reason", data.optString("reason").trim())
                put("notes", data.optString("notes").trim())
                if (data.has("report_date") && data.optString("report_date").trim().isNotEmpty()) {
                    put("report_date", data.optString("report_date").trim())
                }
            }
            val warehouseId = data.optLong("warehouse_id", 0L)
            if (warehouseId > 0L) db.rawQuery("SELECT id FROM warehouses WHERE id = ? AND station_id = ? AND is_active = 1", arrayOf(warehouseId.toString(), stationScopeId.toString())).use { cursor -> require(cursor.moveToFirst()) { "المستودع خارج نطاق المحطة أو غير نشط" } }
            val rows = db.update("damaged_products", values, "id = ? AND station_id = ? AND archived = 0", arrayOf(id.toString(), stationScopeId.toString()))
            if (rows > 0) logActivity("system", "damaged_product_updated", "تم تحديث سجل تالف رقم $id")
            rows
        } finally {
            dbLock.unlock()
        }
    }

    fun updateDamagedProductStatus(id: Long, status: String, approvedBy: Long, stationScopeId: Int): Int {
        dbLock.lock()
        return try {
            require(id > 0) { "معرف السجل غير صالح" }
            require(status in setOf("pending", "approved", "rejected")) { "حالة التالف غير صحيحة" }
            require(approvedBy > 0) { "المستخدم المعتمد مطلوب" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val db = writableDatabase
            var currentStatus = ""
            var productId = 0L
            var quantity = 0.0
            var warehouseId = 0L
            var stationId = 0
            var unitCost = 0.0
            val rowWhere = "dp.id = ? AND dp.station_id = ? AND dp.archived = 0"
            val rowArgs = arrayOf(id.toString(), stationScopeId.toString())
            db.rawQuery(
                "SELECT dp.status, dp.product_id, dp.quantity, dp.warehouse_id, dp.station_id, COALESCE(p.purchase_price, 0) FROM damaged_products dp LEFT JOIN products p ON p.id = dp.product_id WHERE $rowWhere",
                rowArgs
            ).use { cursor ->
                if (!cursor.moveToFirst()) return 0
                currentStatus = cursor.getString(0) ?: "pending"
                productId = cursor.getLong(1)
                quantity = cursor.getDouble(2)
                warehouseId = cursor.getLong(3)
                stationId = cursor.getInt(4)
                unitCost = cursor.getDouble(5)
            }
            if (currentStatus == status) return 1
            if (status == "approved") {
                require(warehouseId > 0) { "المستودع المرتبط بسجل التالف غير صالح" }
                require(stationId > 0) { "المحطة المرتبطة بسجل التالف غير صالحة" }
            }
            require(!(currentStatus == "approved" && status != "approved")) { "لا يمكن التراجع عن اعتماد خصم المخزون" }

            db.beginTransaction()
            try {
                if (status == "approved") {
                    val movement = JSONObject().apply {
                        put("product_id", productId)
                        put("warehouse_id", warehouseId)
                        put("station_id", stationId)
                        put("movement_type", "damage")
                        put("movement_subtype", "damaged_product")
                        put("quantity", quantity)
                        put("unit_cost", unitCost)
                        put("reference_type", "damaged_products")
                        put("reference_id", id)
                        put("notes", "اعتماد سجل التالف رقم $id")
                        put("performed_by", approvedBy)
                    }
                    val movementId = addStockMovement(movement, stationScopeId, approvedBy)
                    require(movementId > 0) { "تعذر تسجيل خصم المخزون" }
                }
                val values = ContentValues().apply {
                    put("status", status)
                    if (status == "pending") {
                        putNull("approved_by")
                        putNull("approved_at")
                    } else {
                        put("approved_by", approvedBy)
                        put("approved_at", getCurrentDateTime())
                    }
                }
                val statusWhere = "id = ? AND station_id = ? AND archived = 0"
                val statusArgs = arrayOf(id.toString(), stationScopeId.toString())
                val rows = db.update("damaged_products", values, statusWhere, statusArgs)
                require(rows > 0) { "تعذر تحديث حالة سجل التالف" }
                logActivity("system", "damaged_product_status", "تم تحديث حالة سجل التالف رقم $id إلى $status")
                db.setTransactionSuccessful()
                rows
            } finally {
                db.endTransaction()
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun archiveDamagedProduct(id: Long, stationScopeId: Int): Int {
        dbLock.lock()
        return try {
            require(id > 0) { "معرف السجل غير صالح" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            val values = ContentValues().apply { put("archived", 1) }
            val archiveWhere = "id = ? AND station_id = ? AND archived = 0"
            val archiveArgs = arrayOf(id.toString(), stationScopeId.toString())
            val rows = writableDatabase.update("damaged_products", values, archiveWhere, archiveArgs)
            if (rows > 0) logActivity("system", "damaged_product_archived", "تمت أرشفة سجل التالف رقم $id")
            rows
        } finally {
            dbLock.unlock()
        }
    }

    fun deleteDamagedProduct(id: Long, stationScopeId: Int): Int = archiveDamagedProduct(id, stationScopeId)

    // ========================================================================
    // دوال المنتجات (Overload)
    // ========================================================================

    fun getProducts(): JSONArray = getProducts(null)

    fun getProducts(stationId: Int?): JSONArray {
        dbLock.lock()
        return try {
            val arr = JSONArray()
            val db = readableDatabase
            val sql = if (stationId != null) {
                "SELECT p.*, c.category_name, u.unit_name, f.fuel_name, COALESCE(il.current_stock, p.quantity, 0) AS current_stock FROM products p LEFT JOIN product_categories c ON p.category_id = c.id LEFT JOIN units u ON p.unit_id = u.id LEFT JOIN fuel_types f ON p.fuel_type_id = f.id LEFT JOIN (SELECT il.product_id, SUM(il.quantity_on_hand) AS current_stock FROM inventory_levels il JOIN warehouses w ON w.id = il.warehouse_id WHERE w.station_id = ? AND w.is_active = 1 GROUP BY il.product_id) il ON il.product_id = p.id WHERE p.station_id=? AND p.is_deleted=0 ORDER BY p.product_name"
            } else {
                "SELECT p.*, c.category_name, u.unit_name, f.fuel_name, COALESCE(il.current_stock, p.quantity, 0) AS current_stock FROM products p LEFT JOIN product_categories c ON p.category_id = c.id LEFT JOIN units u ON p.unit_id = u.id LEFT JOIN fuel_types f ON p.fuel_type_id = f.id LEFT JOIN (SELECT product_id, SUM(quantity_on_hand) AS current_stock FROM inventory_levels GROUP BY product_id) il ON il.product_id = p.id WHERE p.is_deleted=0 ORDER BY p.product_name"
            }
            val args = if (stationId != null) arrayOf(stationId.toString(), stationId.toString()) else null
            db.rawQuery(sql, args).use { cursor ->
                while (cursor.moveToNext()) {
                    arr.put(JSONObject().apply {
                        put("product_id", cursor.getInt(cursor.getColumnIndexOrThrow("id")))
                        put("id", cursor.getInt(cursor.getColumnIndexOrThrow("id")))
                        put("product_code", cursor.getString(cursor.getColumnIndexOrThrow("product_code")))
                        put("barcode", cursor.getString(cursor.getColumnIndexOrThrow("barcode")))
                        put("product_name", cursor.getString(cursor.getColumnIndexOrThrow("product_name")))
                        put("product_name_ar", cursor.getString(cursor.getColumnIndexOrThrow("product_name_ar")))
                        put("description", cursor.getString(cursor.getColumnIndexOrThrow("description")))
                        put("category_id", cursor.getInt(cursor.getColumnIndexOrThrow("category_id")))
                        put("category_name", cursor.getString(cursor.getColumnIndexOrThrow("category_name")))
                        put("unit_id", cursor.getInt(cursor.getColumnIndexOrThrow("unit_id")))
                        put("sale_price", cursor.getDouble(cursor.getColumnIndexOrThrow("sale_price")))
                        put("purchase_price", cursor.getDouble(cursor.getColumnIndexOrThrow("purchase_price")))
                        put("quantity", cursor.getDouble(cursor.getColumnIndexOrThrow("quantity")))
                        put("current_stock", cursor.getDouble(cursor.getColumnIndexOrThrow("current_stock")))
                        put("minimum_stock", cursor.getDouble(cursor.getColumnIndexOrThrow("minimum_stock")))
                        put("min_stock_level", cursor.getDouble(cursor.getColumnIndexOrThrow("minimum_stock")))
                        put("has_expiry", cursor.getInt(cursor.getColumnIndexOrThrow("has_expiry")))
                        put("expiry_date", cursor.getString(cursor.getColumnIndexOrThrow("expiry_date")))
                        put("is_service", cursor.getInt(cursor.getColumnIndexOrThrow("is_service")))
                        put("is_batch_tracked", cursor.getInt(cursor.getColumnIndexOrThrow("is_batch_tracked")))
                        put("is_serialized", cursor.getInt(cursor.getColumnIndexOrThrow("is_serialized")))
                        put("status", cursor.getString(cursor.getColumnIndexOrThrow("status")))
                        put("is_active", cursor.getString(cursor.getColumnIndexOrThrow("status")) == "active")
                    })
                }
            }
            arr
        } finally {
            dbLock.unlock()
        }
    }

    fun getProductsPage(data: JSONObject = JSONObject(), stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة غير صالح" }
        dbLock.lock()
        return try {
            val db = readableDatabase
            val where = mutableListOf("p.station_id = ?", "p.is_deleted = 0")
            val args = mutableListOf(stationScopeId.toString())
            val search = data.optString("search", "").trim()
            if (search.isNotEmpty()) {
                where += "(p.product_code LIKE ? OR p.product_name LIKE ? OR p.product_name_ar LIKE ? OR p.barcode LIKE ? OR p.description LIKE ?)"
                repeat(5) { args += "%$search%" }
            }
            val productId = data.optLong("product_id", 0L)
            if (productId > 0L) { where += "p.id = ?"; args += productId.toString() }
            val productCode = data.optString("product_code", "").trim()
            if (productCode.isNotEmpty()) { where += "p.product_code LIKE ?"; args += "%$productCode%" }
            val categoryId = data.optLong("category_id", 0L)
            if (categoryId > 0L) { where += "p.category_id = ?"; args += categoryId.toString() }
            val status = data.optString("status", "").trim()
            if (status.isNotEmpty()) { require(status in setOf("active", "inactive", "discontinued")) { "حالة المنتج غير صالحة" }; where += "p.status = ?"; args += status }
            val hasExpiry = data.optInt("has_expiry", -1)
            if (hasExpiry == 0 || hasExpiry == 1) { where += "p.has_expiry = ?"; args += hasExpiry.toString() }
            val whereSql = " WHERE " + where.joinToString(" AND ")
            val totalCount = db.rawQuery("SELECT COUNT(*) FROM products p$whereSql", args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
            val stockJoin = " LEFT JOIN (SELECT il.product_id, SUM(il.quantity_on_hand) AS current_stock FROM inventory_levels il JOIN warehouses w ON w.id = il.warehouse_id WHERE w.station_id = ? AND w.is_active = 1 GROUP BY il.product_id) il ON il.product_id = p.id "
            val summaryArgs = mutableListOf(stationScopeId.toString()).apply { addAll(args) }
            val summary = db.rawQuery("SELECT COUNT(*) AS total_count, COALESCE(SUM(CASE WHEN p.status = 'active' THEN 1 ELSE 0 END), 0) AS active_count, COALESCE(AVG(CASE WHEN p.status = 'active' THEN p.sale_price END), 0) AS average_sale_price, COALESCE(SUM(CASE WHEN p.status = 'active' AND COALESCE(il.current_stock, p.quantity, 0) <= p.minimum_stock THEN 1 ELSE 0 END), 0) AS low_stock_count FROM products p$stockJoin$whereSql", summaryArgs.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursorToJsonObject(cursor) else JSONObject() }
            val sortColumn = when (data.optString("sort_by", "id")) {
                "product_code" -> "p.product_code"
                "product_name" -> "p.product_name"
                "sale_price" -> "p.sale_price"
                "purchase_price" -> "p.purchase_price"
                "quantity" -> "p.quantity"
                "status" -> "p.status"
                else -> "p.id"
            }
            val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
            val limit = data.optInt("limit", 50).coerceIn(1, 200)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val pageArgs = mutableListOf(stationScopeId.toString()).apply { addAll(args); add(limit.toString()); add(offset.toString()) }
            val rows = db.rawQuery("SELECT p.*, c.category_name, u.unit_name, f.fuel_name, COALESCE(il.current_stock, p.quantity, 0) AS current_stock FROM products p LEFT JOIN product_categories c ON c.id = p.category_id LEFT JOIN units u ON u.id = p.unit_id LEFT JOIN fuel_types f ON f.id = p.fuel_type_id$stockJoin$whereSql ORDER BY $sortColumn $direction, p.id DESC LIMIT ? OFFSET ?", pageArgs.toTypedArray()).use { cursor -> cursorToJsonArray(cursor) }
            val page = if (totalCount == 0) 0 else (offset / limit) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + limit - 1) / limit
            JSONObject().apply { put("rows", rows); put("count", rows.length()); put("total_count", totalCount); put("page", page); put("page_size", limit); put("total_pages", totalPages); put("has_next", page < totalPages); put("has_previous", page > 1); put("summary", summary); put("source", "products") }
        } finally { dbLock.unlock() }
    }

    fun getProductCategoriesPage(data: JSONObject = JSONObject()): JSONObject {
        dbLock.lock()
        return try {
            val db = readableDatabase
            val where = mutableListOf("c.is_deleted = 0")
            val args = mutableListOf<String>()
            val search = data.optString("search", "").trim()
            if (search.isNotEmpty()) { where += "(c.category_code LIKE ? OR c.category_name LIKE ? OR c.category_name_ar LIKE ? OR c.description LIKE ?)"; repeat(4) { args += "%$search%" } }
            val categoryId = data.optLong("category_id", 0L)
            if (categoryId > 0L) { where += "c.id = ?"; args += categoryId.toString() }
            val status = data.optString("status", "").trim()
            if (status.isNotEmpty()) { require(status == "active" || status == "inactive") { "حالة الفئة غير صالحة" }; where += "c.is_active = ?"; args += if (status == "active") "1" else "0" }
            val whereSql = " WHERE " + where.joinToString(" AND ")
            val totalCount = db.rawQuery("SELECT COUNT(*) FROM product_categories c$whereSql", args.toTypedArray()).use { cursor -> if (cursor.moveToFirst()) cursor.getInt(0) else 0 }
            val sortColumn = when (data.optString("sort_by", "id")) { "category_code" -> "c.category_code"; "category_name" -> "c.category_name"; "display_order" -> "c.display_order"; "product_count" -> "product_count"; else -> "c.id" }
            val direction = if (data.optString("sort_dir", "desc").equals("asc", true)) "ASC" else "DESC"
            val limit = data.optInt("limit", 50).coerceIn(1, 200)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val pageArgs = args.toMutableList().apply { add(limit.toString()); add(offset.toString()) }
            val rows = db.rawQuery("SELECT c.*, (SELECT COUNT(*) FROM products p WHERE p.category_id = c.id AND p.is_deleted = 0) AS product_count FROM product_categories c$whereSql ORDER BY $sortColumn $direction, c.id DESC LIMIT ? OFFSET ?", pageArgs.toTypedArray()).use { cursor -> cursorToJsonArray(cursor) }
            val page = if (totalCount == 0) 0 else (offset / limit) + 1
            val totalPages = if (totalCount == 0) 0 else (totalCount + limit - 1) / limit
            JSONObject().apply { put("rows", rows); put("count", rows.length()); put("total_count", totalCount); put("page", page); put("page_size", limit); put("total_pages", totalPages); put("has_next", page < totalPages); put("has_previous", page > 1); put("source", "product_categories") }
        } finally { dbLock.unlock() }
    }

    fun getProductById(productId: Long, stationScopeId: Int): JSONObject? {
        dbLock.lock()
        return try {
            require(productId > 0L) { "معرف المنتج غير صالح" }
            require(stationScopeId > 0) { "معرف المحطة غير صالح" }
            readableDatabase.rawQuery("SELECT p.*, c.category_name, u.unit_name, f.fuel_name FROM products p LEFT JOIN product_categories c ON p.category_id = c.id LEFT JOIN units u ON p.unit_id = u.id LEFT JOIN fuel_types f ON p.fuel_type_id = f.id WHERE p.id = ? AND p.station_id = ? AND p.is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { cursor ->
                if (!cursor.moveToFirst()) return null
                cursorToJsonObject(cursor).apply { put("product_id", optLong("id", productId)); put("id", optLong("id", productId)); put("current_stock", optDouble("quantity", 0.0)); put("min_stock_level", optDouble("minimum_stock", 0.0)) }
            }
        } finally {
            dbLock.unlock()
        }
    }

