    private fun fuelReportConditions(data: JSONObject, alias: String, includeTankFilter: Boolean = true): Pair<String, MutableList<String>> {
        val conditions = StringBuilder()
        val args = mutableListOf<String>()
        val fromDate = data.optString("from_date", data.optString("start_date", "")).trim()
        val toDate = data.optString("to_date", data.optString("end_date", "")).trim()
        val search = data.optString("search", "").trim()
        val fuelTypeId = data.optLong("fuel_type_id", 0L)
        val tankId = data.optLong("tank_id", 0L)
        if (fromDate.isNotBlank()) { conditions.append(" AND date($alias.created_at) >= date(?)"); args += fromDate }
        if (toDate.isNotBlank()) { conditions.append(" AND date($alias.created_at) <= date(?)"); args += toDate }
        if (fuelTypeId > 0L) { conditions.append(" AND $alias.fuel_type_id = ?"); args += fuelTypeId.toString() }
        if (tankId > 0L) {
            if (includeTankFilter) { conditions.append(" AND $alias.tank_id = ?"); args += tankId.toString() }
            else { conditions.append(" AND 1 = 0") }
        }
        if (search.isNotBlank()) {
            val searchExpr = if (alias == "s") {
                "($alias.sale_code LIKE ? OR $alias.invoice_number LIKE ? OR f.fuel_name LIKE ? OR COALESCE(p.commercial_name, '') LIKE ? OR COALESCE(p.commercial_name_ar, '') LIKE ?)"
            } else {
                "($alias.refill_code LIKE ? OR f.fuel_name LIKE ? OR COALESCE(p.commercial_name, '') LIKE ? OR COALESCE(p.commercial_name_ar, '') LIKE ? OR COALESCE(t.tank_name, '') LIKE ?)"
            }
            conditions.append(" AND $searchExpr")
            val searchCount = if (alias == "s") 5 else 5
            repeat(searchCount) { args += "%$search%" }
        }
        return conditions.toString() to args
    }

    fun getFuelReport(data: JSONObject, stationScopeId: Int): JSONArray {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لتقرير الوقود" }
        dbLock.lock()
        return try {
            val stationId = stationScopeId
            val reportType = data.optString("report_type", "summary")
            val includeSales = reportType == "summary" || reportType == "sales"
            val includeRefills = reportType == "summary" || reportType == "refills"
            val saleFilter = fuelReportConditions(data, "s", includeTankFilter = false)
            val refillFilter = fuelReportConditions(data, "r", includeTankFilter = true)
            val branches = mutableListOf<String>()
            val args = mutableListOf<String>()
            if (includeSales) {
                branches += """
                    SELECT 'sale' as type, s.id, s.sale_code as code, s.created_at as date,
                           s.liters as quantity, s.net_amount as amount, f.fuel_name,
                           COALESCE(p.commercial_name, p.commercial_name_ar) as party_name, '---' as tank_name,
                           s.fuel_type_id as fuel_type_id, NULL as tank_id
                    FROM sales_transactions s
                    LEFT JOIN fuel_types f ON s.fuel_type_id = f.id
                    LEFT JOIN parties p ON s.customer_party_id = p.id
                    WHERE s.station_id = ? AND s.is_deleted = 0 AND s.order_type = 'fuel' ${saleFilter.first}
                """.trimIndent()
                args += stationId.toString(); args += saleFilter.second
            }
            if (includeRefills) {
                branches += """
                    SELECT 'refill' as type, r.id, r.refill_code as code, r.created_at as date,
                           r.delivered_quantity as quantity, 0 as amount, f.fuel_name,
                           COALESCE(p.commercial_name, p.commercial_name_ar) as party_name, t.tank_name,
                           r.fuel_type_id as fuel_type_id, r.tank_id as tank_id
                    FROM tank_refills r
                    LEFT JOIN fuel_types f ON r.fuel_type_id = f.id
                    LEFT JOIN parties p ON r.supplier_id = p.id
                    LEFT JOIN tanks t ON r.tank_id = t.id
                    WHERE r.station_id = ? ${refillFilter.first}
                """.trimIndent()
                args += stationId.toString(); args += refillFilter.second
            }
            if (branches.isEmpty()) return JSONArray()
            val limit = data.optInt("limit", 0).coerceAtLeast(0)
            val offset = data.optInt("offset", 0).coerceAtLeast(0)
            val sql = branches.joinToString(" UNION ALL ") + " ORDER BY date DESC, id DESC" + if (limit > 0) " LIMIT ? OFFSET ?" else ""
            if (limit > 0) { args += limit.toString(); args += offset.toString() }
            readableDatabase.rawQuery(sql, args.toTypedArray()).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    private fun getFuelReportTotalCount(data: JSONObject, stationScopeId: Int): Int {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لعد تقرير الوقود" }
        dbLock.lock()
        return try {
            val stationId = stationScopeId
            val reportType = data.optString("report_type", "summary")
            val includeSales = reportType == "summary" || reportType == "sales"
            val includeRefills = reportType == "summary" || reportType == "refills"
            val saleFilter = fuelReportConditions(data, "s", includeTankFilter = false)
            val refillFilter = fuelReportConditions(data, "r", includeTankFilter = true)
            var total = 0
            if (includeSales) {
                val args = mutableListOf(stationId.toString()); args += saleFilter.second
                readableDatabase.rawQuery("SELECT COUNT(*) FROM sales_transactions s LEFT JOIN fuel_types f ON s.fuel_type_id=f.id LEFT JOIN parties p ON s.customer_party_id=p.id WHERE s.station_id=? AND s.is_deleted=0 AND s.order_type='fuel' ${saleFilter.first}", args.toTypedArray()).use { if (it.moveToFirst()) total += it.getInt(0) }
            }
            if (includeRefills) {
                val args = mutableListOf(stationId.toString()); args += refillFilter.second
                readableDatabase.rawQuery("SELECT COUNT(*) FROM tank_refills r LEFT JOIN fuel_types f ON r.fuel_type_id=f.id LEFT JOIN parties p ON r.supplier_id=p.id LEFT JOIN tanks t ON r.tank_id=t.id WHERE r.station_id=? ${refillFilter.first}", args.toTypedArray()).use { if (it.moveToFirst()) total += it.getInt(0) }
            }
            total
        } finally { dbLock.unlock() }
    }

    fun getFuelReportPage(data: JSONObject, stationScopeId: Int): JSONObject {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لصفحة تقرير الوقود" }
        val limit = data.optInt("limit", 50).coerceIn(1, 1000)
        val offset = data.optInt("offset", 0).coerceAtLeast(0)
        val query = JSONObject(data.toString()).apply { put("limit", limit); put("offset", offset) }
        val rows = getFuelReport(query, stationScopeId)
        val totalCount = getFuelReportTotalCount(query, stationScopeId)
        val page = (offset / limit) + 1
        val totalPages = if (totalCount == 0) 0 else (totalCount + limit - 1) / limit
        return JSONObject().apply {
            put("rows", rows)
            put("count", rows.length())
            put("total_count", totalCount)
            put("page", page)
            put("page_size", limit)
            put("total_pages", totalPages)
            put("has_next", page < totalPages)
            put("has_previous", page > 1)
            put("source", "sales_transactions+tank_refills")
        }
    }

    fun getFuelTransactionDetails(id: Long, type: String, stationScopeId: Int): JSONObject? {
        require(id > 0L) { "معرف المعاملة غير صالح" }
        require(stationScopeId > 0) { "معرف المحطة مطلوب لتفاصيل الوقود" }
        dbLock.lock()
        return try {
            val db = readableDatabase
            when (type.trim().lowercase(Locale.ROOT)) {
                "sale" -> db.rawQuery("""SELECT fs.id, fs.uuid, fs.sale_id, fs.shift_id, fs.pump_id,
                        fs.fuel_type_id, fs.quantity, fs.price_per_liter, fs.total_amount,
                        fs.payment_method, fs.customer_id, fs.vehicle_plate, fs.sale_date,
                        fs.sale_time, fs.notes, fs.created_at, fs.is_deleted
                        FROM fuel_sales fs JOIN sales_transactions st ON st.id = fs.sale_id
                        WHERE fs.sale_id = ? AND st.station_id = ? AND st.is_deleted = 0
                          AND fs.is_deleted = 0 ORDER BY fs.id DESC LIMIT 1""", arrayOf(id.toString(), stationScopeId.toString())).use { cursor ->
                    if (cursor.moveToFirst()) cursorToJsonObject(cursor) else null
                }
                "refill" -> db.rawQuery("SELECT * FROM tank_refills WHERE id = ? AND station_id = ?", arrayOf(id.toString(), stationScopeId.toString())).use { cursor ->
                    if (cursor.moveToFirst()) cursorToJsonObject(cursor) else null
                }
                else -> null
            }
        } finally {
            dbLock.unlock()
        }
    }

    fun getFuelInventoryReconciliation(data: JSONObject, stationScopeId: Int): JSONArray {
        require(stationScopeId > 0) { "معرف المحطة مطلوب لمصالحة الوقود" }
        dbLock.lock()
        return try {
            val stationId = stationScopeId
            val date = data.optString("date", getCurrentDate())
            val sql = """
                SELECT t.id as tank_id, t.tank_name, f.fuel_name,
                       COALESCE(l.opening_level, 0) as opening_level,
                       COALESCE((SELECT SUM(delivered_quantity) FROM tank_refills WHERE tank_id = t.id AND date(created_at) = ?), 0) as refills,
                       COALESCE((SELECT SUM(liters) FROM sales_transactions WHERE fuel_type_id = t.fuel_type_id AND station_id = t.station_id AND date(created_at) = ? AND is_deleted = 0), 0) as sold,
                       COALESCE(l.closing_level, 0) as closing_level,
                       COALESCE(l.measured_level, 0) as measured_level,
                       COALESCE(l.difference, 0) as difference
                FROM tanks t
                LEFT JOIN fuel_types f ON t.fuel_type_id = f.id
                LEFT JOIN tank_level_log l ON t.id = l.tank_id AND date(l.reading_date) = ?
                WHERE t.station_id = ?
            """
            readableDatabase.rawQuery(sql, arrayOf(date, date, date, stationId.toString())).use { cursorToJsonArray(it) }
        } finally {
            dbLock.unlock()
        }
    }


    // MODULE-011: Fixed Assets Typed Methods
    fun getFixedAssetsPage(stationId: Int, limit: Int = 100, offset: Int = 0, status: String? = null, assetType: String? = null, search: String? = null): JSONArray {
        val arr = JSONArray()
        dbLock.lock()
        try {
            val db = readableDatabase
            var selection = "station_id = ? AND is_deleted = 0"
            val args = mutableListOf(stationId.toString())
            
            if (!status.isNullOrEmpty()) { selection += " AND status = ?"; args.add(status) }
            if (!assetType.isNullOrEmpty()) { selection += " AND asset_type = ?"; args.add(assetType) }
            if (!search.isNullOrEmpty()) { selection += " AND (asset_name LIKE ? OR asset_code LIKE ?)"; args.add("%$search%"); args.add("%$search%") }
            
            db.rawQuery("SELECT * FROM fixed_assets WHERE $selection ORDER BY id DESC LIMIT ? OFFSET ?", (args + listOf(limit.toString(), offset.toString())).toTypedArray()).use { c ->
                while (c.moveToNext()) arr.put(cursorRowToJson(c))
            }
        } finally { dbLock.unlock() }
        return arr
    }
    
    fun updateFixedAsset(assetId: Long, stationId: Int, payload: JSONObject, userId: Long): Int {
        dbLock.lock()
        try {
            val db = writableDatabase
            val cv = ContentValues().apply {
                if(payload.has("asset_name")) put("asset_name", payload.optString("asset_name"))
                if(payload.has("asset_type")) put("asset_type", payload.optString("asset_type"))
                if(payload.has("status")) put("status", payload.optString("status"))
                if(payload.has("purchase_date")) put("purchase_date", payload.optString("purchase_date"))
                if(payload.has("purchase_cost")) put("purchase_cost", payload.optDouble("purchase_cost", 0.0))
                if(payload.has("useful_life")) put("useful_life", payload.optInt("useful_life", 0))
                if(payload.has("salvage_value")) put("salvage_value", payload.optDouble("salvage_value", 0.0))
                if(payload.has("location")) put("location", payload.optString("location"))
                if(payload.has("notes")) put("notes", payload.optString("notes"))
                put("updated_at", getCurrentDateTime())
                put("updated_by", userId)
            }
            return db.update("fixed_assets", cv, "id = ? AND station_id = ?", arrayOf(assetId.toString(), stationId.toString()))
        } finally { dbLock.unlock() }
    }
    
    fun getMaintenanceRequestsPage(stationId: Int, limit: Int = 100, offset: Int = 0, status: String? = null, priority: String? = null, search: String? = null): JSONArray {
        val arr = JSONArray()
        dbLock.lock()
        try {
            val db = readableDatabase
            // Join with fixed_assets to enforce station isolation and get asset name
            var query = "SELECT m.*, a.asset_name FROM maintenance_requests m INNER JOIN fixed_assets a ON m.asset_id = a.id WHERE a.station_id = ?"
            val args = mutableListOf(stationId.toString())
            
            if (!status.isNullOrEmpty()) { query += " AND m.status = ?"; args.add(status) }
