    // ========================================================================
    // Dedicated price-list APIs. These complement the generic CRUD layer and
    // provide the joins, item counts, and history shape required by the UI.
    // ========================================================================
    fun getPriceListsWithItemCount(stationScopeId: Int? = null): JSONArray {
        dbLock.lock()
        return try {
            val args = mutableListOf<String>()
            val scope = if (stationScopeId != null) { require(stationScopeId > 0); args += stationScopeId.toString(); " AND pl.station_id = ?" } else ""
            readableDatabase.rawQuery("""
                SELECT pl.*, COUNT(pli.id) AS items_count,
                       pt.type_name_ar AS party_type_name_ar,
                       p.commercial_name_ar AS party_name_ar
                FROM price_lists pl
                LEFT JOIN price_list_items pli ON pli.price_list_id = pl.id
                LEFT JOIN party_types pt ON pl.party_type_id = pt.id
                LEFT JOIN parties p ON pl.party_id = p.id
                WHERE pl.is_deleted = 0$scope
                GROUP BY pl.id
                ORDER BY pl.is_default DESC, pl.valid_from DESC, pl.id DESC
            """, args.toTypedArray()).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    fun getPriceListItems(priceListId: Long, stationScopeId: Int? = null): JSONArray {
        require(priceListId > 0)
        dbLock.lock()
        return try {
            val args = mutableListOf(priceListId.toString())
            val scope = if (stationScopeId != null) { require(stationScopeId > 0); args += stationScopeId.toString(); " AND EXISTS (SELECT 1 FROM price_lists pl WHERE pl.id = pli.price_list_id AND pl.station_id = ? AND pl.is_deleted = 0)" } else ""
            readableDatabase.rawQuery("""
                SELECT pli.*, p.name_ar AS product_name_ar, p.name_en AS product_name, p.product_code
                FROM price_list_items pli
                LEFT JOIN products p ON pli.product_id = p.id
                WHERE pli.price_list_id = ?$scope
                ORDER BY p.name_ar ASC, pli.id ASC
            """, args.toTypedArray()).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    fun getPriceHistory(productId: Long, limit: Int = 50, stationScopeId: Int? = null): JSONArray {
        require(productId > 0)
        val safeLimit = limit.coerceIn(1, 500)
        dbLock.lock()
        return try {
            val args = mutableListOf(productId.toString(), safeLimit.toString())
            val scope = if (stationScopeId != null) { require(stationScopeId > 0); args.add(1, stationScopeId.toString()); " AND EXISTS (SELECT 1 FROM products sp WHERE sp.id = ph.product_id AND sp.station_id = ? AND sp.is_deleted = 0)" } else ""
            val query = """SELECT ph.*, u.name AS created_by_name FROM price_history ph
                LEFT JOIN users u ON ph.created_by = u.id
                WHERE ph.product_id = ? AND ph.archived = 0$scope
                ORDER BY ph.change_date DESC LIMIT ?"""
            val orderedArgs = if (stationScopeId != null) arrayOf(productId.toString(), stationScopeId.toString(), safeLimit.toString()) else arrayOf(productId.toString(), safeLimit.toString())
            readableDatabase.rawQuery(query, orderedArgs).use { cursorToJsonArray(it) }
        } finally { dbLock.unlock() }
    }

    fun insertPriceListItem(data: JSONObject, actorId: Long = 0L, stationScopeId: Int? = null): Long {
        val listId = data.optLong("price_list_id").also { require(it > 0) }
        val productId = data.optLong("product_id").also { require(it > 0) }
        val unitPrice = data.optDouble("unit_price", -1.0).also { require(it >= 0) }
        dbLock.lock()
        return try {
            if (stationScopeId != null) {
                require(stationScopeId > 0)
                writableDatabase.rawQuery("SELECT 1 FROM price_lists WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(listId.toString(), stationScopeId.toString())).use { require(it.moveToFirst()) { "قائمة الأسعار خارج نطاق المحطة" } }
                writableDatabase.rawQuery("SELECT 1 FROM products WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(productId.toString(), stationScopeId.toString())).use { require(it.moveToFirst()) { "المنتج خارج نطاق المحطة" } }
            }
            val values = ContentValues().apply {
                put("uuid", UUID.randomUUID().toString()); put("price_list_id", listId); put("product_id", productId)
                put("unit_price", unitPrice); put("min_quantity", data.optDouble("min_quantity", 1.0)); put("max_quantity", data.optDouble("max_quantity", 0.0).takeIf { it > 0 })
                put("discount_percent", data.optDouble("discount_percent", 0.0)); put("valid_from", data.optString("valid_from").takeIf { it.isNotBlank() }); put("valid_to", data.optString("valid_to").takeIf { it.isNotBlank() }); put("is_active", data.optInt("is_active", 1))
            }
            writableDatabase.insertOrThrow("price_list_items", null, values)
        } finally { dbLock.unlock() }
    }

    fun updatePriceListItem(id: Long, data: JSONObject, stationScopeId: Int? = null): Int {
        require(id > 0)
        dbLock.lock()
        return try {
            if (stationScopeId != null) {
                require(stationScopeId > 0)
                writableDatabase.rawQuery("SELECT 1 FROM price_list_items pli JOIN price_lists pl ON pl.id = pli.price_list_id WHERE pli.id = ? AND pl.station_id = ? AND pl.is_deleted = 0", arrayOf(id.toString(), stationScopeId.toString())).use { require(it.moveToFirst()) { "عنصر قائمة الأسعار خارج نطاق المحطة" } }
            }
            val values = ContentValues().apply { put("unit_price", data.optDouble("unit_price", -1.0)); put("min_quantity", data.optDouble("min_quantity", 1.0)); put("max_quantity", data.optDouble("max_quantity", 0.0).takeIf { it > 0 }); put("discount_percent", data.optDouble("discount_percent", 0.0)); put("valid_from", data.optString("valid_from").takeIf { it.isNotBlank() }); put("valid_to", data.optString("valid_to").takeIf { it.isNotBlank() }); put("is_active", data.optInt("is_active", 1)) }
            writableDatabase.update("price_list_items", values, "id = ?", arrayOf(id.toString()))
        } finally { dbLock.unlock() }
    }

    fun deletePriceListItem(id: Long, stationScopeId: Int? = null): Int {
        require(id > 0)
        dbLock.lock()
        return try {
            val where = if (stationScopeId != null) {
                require(stationScopeId > 0)
                "id = ? AND EXISTS (SELECT 1 FROM price_lists pl WHERE pl.id = price_list_items.price_list_id AND pl.station_id = ? AND pl.is_deleted = 0)"
            } else "id = ?"
            val args = if (stationScopeId != null) arrayOf(id.toString(), stationScopeId.toString()) else arrayOf(id.toString())
            writableDatabase.delete("price_list_items", where, args)
        } finally { dbLock.unlock() }
    }


    private fun employeePaymentRows(query: String, args: Array<String>): List<Map<String, Any>> {
        val result = mutableListOf<Map<String, Any>>()
        readableDatabase.rawQuery(query, args).use { cursor ->
            while (cursor.moveToNext()) {
                val row = mutableMapOf<String, Any>()
                for (i in 0 until cursor.columnCount) {
                    row[cursor.getColumnName(i)] = when (cursor.getType(i)) {
                        Cursor.FIELD_TYPE_NULL -> ""
                        Cursor.FIELD_TYPE_INTEGER -> cursor.getLong(i)
                        Cursor.FIELD_TYPE_FLOAT -> cursor.getDouble(i)
                        Cursor.FIELD_TYPE_STRING -> cursor.getString(i) ?: ""
                        else -> cursor.getString(i) ?: ""
                    }
                }
                result += row
            }
        }
        return result
    }

    fun getEmployees(includeInactive: Boolean = false): List<Map<String, Any>> = employeePaymentRows(
        "SELECT id, uuid, employee_code, full_name, full_name_ar, national_id, phone, department, job_title, job_title_ar, employment_type, hire_date, basic_salary, total_salary, status, station_id, branch_id, user_id FROM employees WHERE is_deleted = 0${if (!includeInactive) " AND status = 'active'" else ""} ORDER BY full_name_ar ASC",
        emptyArray()
    )

    fun getEmployeeById(employeeId: Int, stationScopeId: Int? = null): Map<String, Any>? {
        val args = if (stationScopeId != null) arrayOf(employeeId.toString(), stationScopeId.toString()) else arrayOf(employeeId.toString())
        val scope = if (stationScopeId != null) " AND station_id = ?" else ""
        return employeePaymentRows("SELECT id, uuid, employee_code, full_name, full_name_ar, department, job_title, total_salary, status FROM employees WHERE id = ? AND is_deleted = 0$scope", args).firstOrNull()
    }

    fun getEmployeePaymentRecords(options: String = "{}", stationScopeId: Int? = null): List<Map<String, Any>> {
        val params = try { JSONObject(options) } catch (_: Exception) { JSONObject() }
        val conditions = mutableListOf("ep.is_deleted = 0")
        val args = mutableListOf<String>()
        if (stationScopeId != null) { require(stationScopeId > 0); conditions += "ep.station_id = ?"; args += stationScopeId.toString() }
        params.optInt("employee_id", 0).takeIf { it > 0 }?.let { conditions += "ep.employee_id = ?"; args += it.toString() }
        params.optString("type").takeIf { it.isNotBlank() }?.let { conditions += "ep.type = ?"; args += it }
        params.optString("status").takeIf { it.isNotBlank() }?.let { conditions += "ep.status = ?"; args += it }
        params.optString("from_date").takeIf { it.isNotBlank() }?.let { conditions += "ep.date >= ?"; args += it }
        params.optString("to_date").takeIf { it.isNotBlank() }?.let { conditions += "ep.date <= ?"; args += it }
        params.optString("search").takeIf { it.isNotBlank() }?.let { conditions += "(e.full_name LIKE ? OR e.full_name_ar LIKE ? OR ep.description LIKE ?)"; repeat(3) { args += "%$it%" } }
        val limit = params.optInt("limit", 500).coerceIn(1, 1000)
        args += limit.toString()
        return employeePaymentRows("SELECT ep.*, e.full_name AS employee_name, e.full_name_ar AS employee_name_ar, e.employee_code, e.department, e.job_title, e.total_salary AS employee_base_salary FROM employee_payments ep LEFT JOIN employees e ON ep.employee_id = e.id WHERE ${conditions.joinToString(" AND ")} ORDER BY ep.date DESC, ep.id DESC LIMIT ?", args.toTypedArray())
    }

    fun insertEmployeePayment(data: JSONObject, stationScopeId: Int, actorId: Long): Long {
        require(stationScopeId > 0 && actorId > 0)
        val employeeId = data.optLong("employee_id").also { require(it > 0) }
        dbLock.lock()
        return try {
            writableDatabase.rawQuery("SELECT 1 FROM employees WHERE id = ? AND station_id = ? AND is_deleted = 0", arrayOf(employeeId.toString(), stationScopeId.toString())).use { require(it.moveToFirst()) { "الموظف خارج نطاق المحطة" } }
            writableDatabase.insertOrThrow("employee_payments", null, ContentValues().apply {
                put("uuid", UUID.randomUUID().toString()); put("employee_id", employeeId); put("station_id", stationScopeId); put("payroll_id", data.optLong("payroll_id").takeIf { it > 0 }); put("amount", data.optDouble("amount", 0.0)); put("type", data.optString("type", "salary")); put("description", data.optString("description")); put("date", data.optString("date", getCurrentDate())); put("operator", data.optString("operator", actorId.toString())); put("payment_method", data.optString("payment_method", "cash")); put("cash_box_id", data.optLong("cash_box_id").takeIf { it > 0 }); put("bank_account_id", data.optLong("bank_account_id").takeIf { it > 0 }); put("status", data.optString("status", "pending")); put("reference", data.optString("reference")); put("notes", data.optString("notes")); put("period_from", data.optString("period_from")); put("period_to", data.optString("period_to")); put("created_at", getCurrentDateTime()); put("updated_at", getCurrentDateTime()); put("created_by", actorId); put("is_deleted", 0)
            })
        } finally { dbLock.unlock() }
    }

    fun updateEmployeePayment(id: Long, data: JSONObject, stationScopeId: Int, actorId: Long): Int {
        require(id > 0 && stationScopeId > 0 && actorId > 0)
        dbLock.lock()
        return try { writableDatabase.update("employee_payments", ContentValues().apply { put("amount", data.optDouble("amount", 0.0)); put("type", data.optString("type", "salary")); put("description", data.optString("description")); put("date", data.optString("date", getCurrentDate())); put("operator", data.optString("operator", actorId.toString())); put("status", data.optString("status", "pending")); put("notes", data.optString("notes")); put("period_from", data.optString("period_from")); put("period_to", data.optString("period_to")); put("updated_at", getCurrentDateTime()); put("updated_by", actorId) }, "id = ? AND station_id = ? AND is_deleted = 0", arrayOf(id.toString(), stationScopeId.toString())) } finally { dbLock.unlock() }
    }

